    public function validacion_add_importacion_medicos($id, $id_user) {

        //$model_stock = new Stock_farmacia();
        //$lotes = $model_stock->ShowLotesById_productoAndId_farmacia($id_producto, $id_farmacia, $cantidad_prescrita);
        //return $lotes;
        $model_farma = new Farmacia;
        $farma = $model_farma->GetFarmaByUser($id_user);
        $id_farmacia = $farma->id;
        $nombre_farmacia = $farma->nombre;
        $id_carga_inicial = 0;
        //----------------------------------------------------------------------
        $modelstock = new Stock_farmacia;
        $date = Carbon::now();
        $fecha = $date->format('d-m-Y');
        $importar = Importacione::find($id);
        $url_data = $importar->url_data;
        //----------------------------------------------------------------------
        //$insert_carga = new Carga();
        $insert_carga = array();

        Excel::load('storage/app/' . $url_data, function($reader) use($id, $id_farmacia, $fecha, $id_user, &$insert_carga) {
            $n = 0;
            foreach ($reader->get() as $book) {
                $validator = Validator::make($book->all(), [
                    'cantidad' => 'required|numeric',
                    'codigo' => 'required|max:12',
                    'registro_sanitario' => 'required|max:20',
                    'lote' => 'required|max:20',
                    'fecha_vencimiento' => 'required|date',
		    'precio' => 'required|numeric'
                ]);

                if ($validator->fails()) {
                    $insert_carga[$n]["codigo"] = "1234566";
                    $insert_carga[$n]["nombre"] = "producto de prueba";
                    $messages = (string) $validator->messages();
                    $insert_carga[$n]["msg"] = $messages;

                    $n = $n + 1;
                    //echo $failedRules = $validator->failed();
                    //$validator = Validator::make($input, $rules);
                    //$messages = $validator->messages();
                } else {

                    if ($book->cantidad <= 0):
                        $insert_carga[$n]["msg"] = "Cantidad menor o igual a cero";
                        $insert_carga[$n]["tipo"] = 1;
                        $insert_carga[$n]["codigo"] = $book->codigo;
                        $insert_carga[$n]["nombre"] = $book->nombre;
                        $insert_carga[$n]["cantidad"] = $book->cantidad;
                        $insert_carga[$n]["fecha_vencimiento"] = $book->fecha_vencimiento;
                    endif;

                    $producto = Producto::where('codigo', '=', $book->codigo)->where('estado', '=', 1)->first();
                    if (!isset($producto->codigo)):
                        $insert_carga[$n]["msg"] = "Codigo incorrecto";
                        $insert_carga[$n]["tipo"] = 2;
                        $insert_carga[$n]["codigo"] = $book->codigo;
                        $insert_carga[$n]["nombre"] = $book->nombre;
                        $insert_carga[$n]["cantidad"] = $book->cantidad;
                        $insert_carga[$n]["fecha_vencimiento"] = $book->fecha_vencimiento;
                    endif;

                    $fecha_vencimiento = str_replace("/", "-", $book->fecha_vencimiento);
                    //$fecha_vencimiento = explode("-",$fecha_vencimiento);
                    $date = Carbon::createFromFormat('Y-m-d', substr($fecha_vencimiento, 0, 10));
                    //$date = $date->format('d-m-Y');
                    //if((checkdate((int)$fecha_vencimiento[1],(int)$fecha_vencimiento[0],(int)$fecha_vencimiento[2])) || (1900 == 1900)):
                    if (substr($fecha_vencimiento, 0, 4) == "1900"):
                        $insert_carga[$n]["msg"] = "Fecha de Vencimiento Incorrecta";
                        $insert_carga[$n]["tipo"] = 3;
                        $insert_carga[$n]["codigo"] = $book->codigo;
                        $insert_carga[$n]["nombre"] = $book->nombre;
                        $insert_carga[$n]["cantidad"] = $book->cantidad;
                        $insert_carga[$n]["fecha_vencimiento"] = $fecha_vencimiento;
                    endif;

                    $n = $n + 1;
                }
            }
            if($n>0){
				$update_importacion = Importacione::find($id);
				$update_importacion->estado = 5;
				$update_importacion->fecha_importacion = $fecha;
				$update_importacion->save();
			}
        });
        /*
          $insert_carga = new Carga();
          $insert_carga->codigo = "12345678";
          $insert_carga->nombre = "producto de prueba";
         */
        return json_encode($insert_carga);
    }
    public function exportar_reporte_saludMaterna($id_user, $fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_servicio, $id_consultorio, $id_medico,$id_atencione) {
		
		if($dni==0)$dni="";
		if($paciente==0)$paciente="";
		
		$modelusuario = new Farmacia();
        $usuario = $modelusuario->GetNombreUsuarioByIdUser($id_user);
        $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;
		$paciente= strtoupper($paciente);
        Excel::create('Exportar Reportes de Salud-Materna', function($excel) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_servicio, $id_consultorio, $id_medico, $nombre_usuario, $id_user,$id_atencione) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_servicio, $id_consultorio, $id_medico, $nombre_usuario, $id_user,$id_atencione) {
				
				$modelfarma = new Farmacia;
				$model_usuario = new User;
				$model_medico = new \App\Models\Medico();
				$model_citas = new \App\Models\Cita();
				$farmacia = $modelfarma->GetFarmaByUser($id_user);
				$id_farmacia = $farmacia->id;
                $establecimiento = $modelfarma->GetEstablecimientoPNP($id_farmacia);
				$modo_validacion = $farmacia->modo_validacion;
				//----------------------------------------------------------------------
				$usuario_actual = $model_usuario->GetById($id_user);
				$flagemergenciareferencia = $usuario_actual->flaghistoria;
				$medico = 0;
				if($flagemergenciareferencia!=1){
					$medico_actual = $model_medico->GetMedicoByDniAndEstablecimiento($usuario_actual->dni,$farmacia->id_establecimiento);
					$medico = $medico_actual->id;
				}
				
				$p[]=$fecha_ini;
				$p[]=$fecha_fin;
				$p[]=$dni;
				$p[]=$paciente;
                if(Auth::user()->flaghospitalizacion==1):
        				  $p[]=0;
        				  $p[]=0;
                else:
                  $p[]=$id_servicio;
                  $p[]=$id_consultorio;
                endif;
				$p[]=$id_medico;
				$p[]=$estado;
				$p[]=$id_atencione;
				$p[]=Auth::user()->id_establecimiento;
				$p[]=1;
				$p[]=10000;
				$citas = $model_citas->salud_maternareporte($p);
				$nro_atendidas = isset($citas[0]->totalrows)?$citas[0]->totalrows:0;
				//$citas = $model_citas->AllCitaConfirmaAtencionFecha($fecha, $dni, $paciente, $medico, $estado);
				//$nro_atendidas = $model_citas->GetCountCitaConfirmaAtencionFecha($fecha, $dni, $paciente, $medico, $estado);		
                //--------------------------------------------------------------
                $variable = [];
                $n = 1;
                array_push($variable, array($establecimiento->nombre));
                array_push($variable, array("Reporte de Atenciones Medicas"));
                array_push($variable, array("Fecha Desde: " . $fecha_ini));
				array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                array_push($variable, array("Total: " . $nro_atendidas . " atenciones"));
                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array(""));
                  array_push($variable, array("N", "TIPO DOC", "NUMERO DOC","PACIENTE","FECHA DE NACIMIENTO", "EDAD",
                    "RESPONSABLE CITA","FECHA_ULTIMA_REGLA","FECHA_PROBABLE_PARTO","FECHA_PARTO","NUM_DOC","SEXO","ESTADO","SITUACION","NEONATOSS"));

                
                    foreach ($citas as $r) {
                        $condicion = "NO";
                        if($r->condicion == 1)$condicion = "SI";
                        if($id_consultorio==1357):
                            array_push($variable, array($n++,$r->tipo_doc_ident, $r->nro_doc_ident,$r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,$r->edadafiliado,$r->atencion, $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre, $r->fech_ult_regla, $r->fech_prob_parto, $r->fecha_parto, $r->num_doc, $r->sexo,$r->estado));
                        else:
                            if ($r->id_sub_consultorio != 1357) 
                            $situacion = '';
                            if (!is_null($r->id_gestacion)) {
                                $situacion = 'Gestante';
                            } elseif (!is_null($r->id_puerperio)) {
                                $situacion = 'Puerpera';
                            } elseif (!is_null($r->neonatos)) {
                                $situacion = 'Neonata';
                            }

                                array_push($variable, array(
                                    $n++,
                                    $r->tipo_doc_ident,
                                    $r->nro_doc_ident,
                                    $r->asegurado_paterno . ' ' . $r->asegurado_materno . ', ' . $r->asegurado_nombre,
                                    $r->edadafiliado,
                                    $r->atencion,
                                    $r->medico_paterno . ' ' . $r->medico_materno . ', ' . $r->medico_nombre,
                                    $r->fech_ult_regla,
                                    $r->fech_prob_parto,
                                    $r->fecha_parto,
                                    $r->num_doc,
                                    $r->sexo,
                                    $r->estado,
                                    $situacion,
                                    $r->neonatos,
                                     // Agregar la situación determinada
                                ));                           
                           
                            endif;
    
                    }
                    $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
                });
            })->export('xls');
    }


