    public function add_importacion_stocks($id, $id_user) {
      $model_farma = new Farmacia;
      $farma = $model_farma->GetFarmaByUser($id_user);
      $id_farmacia = $farma->id;
      $nombre_farmacia = $farma->nombre;
      $id_carga_inicial = 0;
      //----------------------------------------------------------------------
      $modelstock = new Stock_farmacia;
      $date = Carbon::now();
      $fecha = $date->format('d-m-Y');
      $importar = Importacione::find($id);
      $url_data = $importar->url_data;
      //----------------------------------------------------------------------
      Excel::load('storage/app/' . $url_data, function($reader) use($id, $id_farmacia, $fecha, $id_user, &$id_carga_inicial) {
        $n=0;
        foreach ($reader->get() as $book) {
          $validator = Validator::make($book->all(), [
                    'cantidad' => 'required|numeric',
                    'codigo' => 'required|max:12',
                    'registro_sanitario' => 'required|max:20',
                    'lote' => 'required|max:20',
                    'fecha_vencimiento' => 'required|date',
                    'precio' => 'required|numeric'
          ]);
          if ($validator->fails()) {
            $n=$n+1;
            if($n>1){
              Session::flash('flash_message', 'Solo se importó algunos productos, revise el archivo excel que ha importado que probablemente tenga exitan productos con datos incorrectos');
              return redirect('/from_registrar_cabecera_carga_inicial/' . $id_user);
            }else{
              Session::flash('flash_message', 'No se importó ningún producto, los datos de los productos son incorrectos, revise el archivo excel que ha importado');
              return redirect('/from_registrar_cabecera_carga_inicial/' . $id_user);
            }
          } else {
              $n=$n+1;                    
	      if($n == 1):
                $cabecera_carga = new Carga_inicial_stock();
                $cabecera_carga->id_farmacia = $id_farmacia;
                $cabecera_carga->id_user = $id_user;
                $cabecera_carga->estado = 1;
                $cabecera_carga->fecha_corte = $fecha;
                $cabecera_carga->save();
                $id_carga_inicial = $cabecera_carga->id;
	      endif;

              $producto = Producto::where('codigo', '=', $book->codigo)->where('estado', '=', 1)->first();
              $insert_carga = new Carga();
              $insert_carga->codigo = $book->codigo;
              $insert_carga->nombre = $producto->nombre;
              $insert_carga->registro_sanitario = $book->registro_sanitario;
              $insert_carga->lote = $book->lote;
              $insert_carga->cantidad = $book->cantidad;
              $insert_carga->fecha_vencimiento = $book->fecha_vencimiento;
              $insert_carga->precio_promedio = $book->precio;
              $insert_carga->id_farmacia = $id_farmacia;
              $insert_carga->fecha_ingreso = $fecha;
              $insert_carga->id_producto = $producto->id;
              $insert_carga->id_carga_inicial = $id_carga_inicial;
              $insert_carga->estado = 1;
              $insert_carga->save();
              //----------------------------------------------
              $update_importacion = Importacione::find($id);
              $update_importacion->estado = 1;
              $update_importacion->fecha_importacion = $fecha;
              $update_importacion->save();

          }

        }
      });
      Session::flash('flash_message', 'Se Agrego correctamente todos los productos importados, proceda a revisar los datos para luego ..!!');
        return redirect('/from_registrar_cabecera_carga_inicial/' . $id_farmacia);
    }

    public function add_importacion_medicos($id, $id_user) {
        $date = Carbon::now();
        $fecha = $date->format('d-m-Y');
        $importar = \App\Models\Importacione::find($id);
        $url_data = $importar->url_data;
        Excel::load('storage/app/' . $url_data, function($reader) {
            foreach ($reader->get() as $book) {
                Medico::create([
                    'dni' => $book->dni,
                    'colegiatura' => $book->colegiatura,
                    'nombre' => $book->nombre,
                    'paterno' => $book->paterno,
                    'materno' => $book->materno,
                    'especialidad' => $book->especialidad,
                    'id_establecimiento' => $book->id_establecimiento
                ]);
            }
        });

        $importar->estado = 1;
        $importar->fecha_importacion = $fecha;
        $importar->save();
        Session::flash('flash_message', 'Importación exitosa');
        return redirect('/importaciones_medicos/' . $id_user);
    }

    public function import() {
        $nombre = 'medico.xlsx';
        Excel::load($nombre, function($reader) {
            foreach ($reader->get() as $book) {
                Medico::create([
                    'dni' => $book->dni,
                    'colegiatura' => $book->colegiatura,
                    'nombre' => $book->nombre,
                    'paterno' => $book->paterno,
                    'materno' => $book->materno,
                    'especialidad' => $book->especialidad,
                    'id_establecimiento' => $book->id_establecimiento
                ]);
            }
        });
        return Medico::all();
    }

    public function usuarios_por_ipress_excel($id_farmacia, $nombre_farmacia) {
