		$model_producto = new Producto;
        $productos = $model_producto->ProductosFarmaciasSegunNivel($nivel);
		$n = 0;
		
        Excel::create('importStock_' . $nombre_farmacia, function($excel) use($nombre_farmacia,&$n,&$productos) {
            $excel->sheet('GENERAL', function($sheet) use($nombre_farmacia,&$n,&$productos) {
                $sheet->row(1, array(
                    'codigo', 'nombre', 'unidad','registro_sanitario', 'lote', 'cantidad', 'fecha_vencimiento', 'precio'
                ));
