	public function exportar_reporte_receta_por_beneficiario($fecha_inicio, $fecha_fin, $dni_beneficiario) {
        Excel::create('Exportar Reportes Recetas por Beneficiario', function($excel) use($fecha_inicio, $fecha_fin, $dni_beneficiario) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $dni_beneficiario) {
				
				$model_receta = new \App\Models\Receta_vale;
				$beneficiario = $model_receta->ShowByDNI($dni_beneficiario);
                                //print_r($beneficiario);
				$recetas = $model_receta->AllRecetasByDniAndFechas($dni_beneficiario,$fecha_inicio,$fecha_fin);
				
                //var_dump($cies); exit;                
                $variable = [];
                $n = 0;
				$cantidadTotal = 0;
				$importe_total = 0;
                foreach ($recetas as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Recetas por Beneficiario"));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                array_push($variable, array("Total: " . $n));
				
                                array_push($variable, array("TIPO DOCUMENTO: " . $beneficiario[0]->tipodoc_beneficiario));
				array_push($variable, array("NRO. DOCUMENTO: " . $beneficiario[0]->dni_beneficiario));
				array_push($variable, array("APELLIDOS Y NOMBRES: " . $beneficiario[0]->paterno_beneficiario." ".$beneficiario[0]->materno_beneficiario.", ".$beneficiario[0]->nombre_beneficiario));
				array_push($variable, array("TIPO DE BENEFICARIO: " . $beneficiario[0]->tipo_beneficiario));
				
                array_push($variable, array(""));
                array_push($variable, array("N", "Farmacia", "Numero de Receta", "Fecha de Receta", "Productos Farmacéuticos y Dispositivos médicos", "Cantidad", "Precio", "Importe"));
                $m = 1;
                foreach ($recetas as $c) {
					$cantidadTotal += $c->cantidad_dispensada;
					$importe 		= $c->cantidad_dispensada * $c->precio_unitario;
					$importe_total += $importe;
                    array_push($variable, array($m++, $c->farmacia, $c->nro_receta, $c->fecha_expedicion, $c->codigo." - ".$c->producto, $c->cantidad_dispensada, number_format($c->precio_unitario, 6, '.', ','), number_format($importe, 6, '.', ',')));
                }
				
				array_push($variable, array("", "", "", "", "", $cantidadTotal, "", number_format($importe_total, 6, '.', ',')));
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6')->mergeCells('A7:C7');
            });
        })->export('xlsx');
    }
	
