	public function exportar_reporte_productos_atendidos($fecha_inicio, $fecha_fin, $nombre_farmacia) {
        Excel::create('Exportar Reportes de Productos con Promedio Mensual', function($excel) use($fecha_inicio, $fecha_fin, $nombre_farmacia) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $nombre_farmacia) {
				
				/******************************/
				$txtfechaDesde_=explode("-",$fecha_inicio);
				$txtfechaHasta_=explode("-",$fecha_fin);
				
				$fechaIni=$txtfechaDesde_[2]."/".$txtfechaDesde_[1]."/01"; 
				$fechaFin=$txtfechaHasta_[2]."/".$txtfechaHasta_[1]."/01";
				
				$mes = date("m", strtotime($fechaIni));
				$ano=  date("Y", strtotime($fechaIni));
				
				$limite=$txtfechaHasta_[1].'/'.$txtfechaHasta_[2];
				$nuevo=0;
				
				$validarFechaDesde = $txtfechaDesde_[1].'/'.$txtfechaDesde_[2];
				$validarFechaHasta = $txtfechaHasta_[1].'/'.$txtfechaHasta_[2];
				
				$arrayMeses=array();
				$arrayMeses[]=$mes."/".$ano;

				/*****************************/
				$model_receta = new \App\Models\Receta_vale;
				$productos = $model_receta->ShowProductosAtendidosAlterno($fecha_inicio, $fecha_fin, $nombre_farmacia);
				
                $variable = [];
                $n = 0;
				$cantidadTotal = 0;
				$importe_total = 0;
                foreach ($productos as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Recetas por Beneficiario"));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                array_push($variable, array("Total: " . $n));
                array_push($variable, array(""));
				$cabecera = array();
				$n = 0;
				$cabecera[] = "N";
				$cabecera[] = "Código";
				$cabecera[] = "Productos Farmacéuticos y Disp. Médicos";
				$cabecera[] = $mes."/".$ano;
				$m = 0;
				while($nuevo!=$limite && $validarFechaDesde!=$validarFechaHasta):
						$m++;
						$nuevo=date("m/Y", mktime(0, 0, 0, $mes+$m, 1, $ano));
						$arrayMeses[]=$nuevo;
						$cabecera[] = $nuevo;
				endwhile;
				
				$cabecera[] = "Acumulado";
				$cabecera[] = "Promedio Mensual";
				$cabecera[] = "Stock Actual";
				$cabecera[] = "Número de Meses";
				array_push($variable, $cabecera);
				
                $m = 1;
                foreach ($productos as $c) {
					$acumulado = 0;
                                        $nro_mes_acumulado = \App\Models\Kardexe::ShowNroMesByProd($c->id_producto,$nombre_farmacia,$fecha_inicio,$fecha_fin);
					$datos = array();
					$n++;
					$datos[] = $n;
					$datos[] = $c->codigo;
					$datos[] = $c->nombre;
                                        $nromes=0;
					foreach($arrayMeses as $rowMes):
                                                $nromes ++;
						$fechaMes = explode("/",$rowMes);
						$month = $fechaMes[1].'-'.$fechaMes[0];
						$aux = date('Y-m-d', strtotime("{$month} + 1 month"));
						$last_day = date('Y-m-d', strtotime("{$aux} - 1 day"));
						$fecha_inicio_='01-'.str_replace("/","-",$rowMes);
						$fecha_fin_=$last_day;
                                
						$total = \App\Models\Kardexe::ShowTotalByProd($c->id_producto,$nombre_farmacia,$fecha_inicio_,$fecha_fin_);
                                                if(isset($total->total)){
                                                    $stock = $total->total;
                                                } else {
                                                    $stock = 0;
                                                }
                                                
						$egresos = \App\Models\Kardexe::ShowEgresosByProd($c->id_producto,$nombre_farmacia,$fecha_inicio_,$fecha_fin_);
						$recetasDevueltas = \App\Models\Kardexe::ShowRecetasDevueltas($c->id_producto,$nombre_farmacia,$fecha_inicio_,$fecha_fin_);
						$nro_mes = \App\Models\Kardexe::ShowNroMesByProd($c->id_producto,$nombre_farmacia,$fecha_inicio_,$fecha_fin_);
						$g = 0;
						if($nro_mes->nro_mes > 0):
							$g = ($egresos->total-$recetasDevueltas->recetas_devueltas) / $nro_mes->nro_mes;
							$acumulado+=$g;
						endif; 
                                
                        $datos[] = $g;
                    endforeach;
                        
						$datos[] = $acumulado;
						$promedio = $acumulado/$nro_mes_acumulado->nro_mes;
						$datos[] = round($promedio);
                                                $datos[] = $stock;
						
						$provision = 0;
						if($promedio > 0):
							$provision = $stock / $promedio;
						endif;
						
						$provision = round($provision,0);
						$datos[] = $nromes;
					
					array_push($variable, $datos);
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
	
	
