	public function descarga_reportes($fecha_inicio, $fecha_fin) {
	
		$model_farma = new Farmacia;
		
		$farmaciaAll = DB::table('farmacias')->get();
		foreach($farmaciaAll as $rowFarmaciaAll):
		
		$id_farmacia = $rowFarmaciaAll->id;
        $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
        $nombre_farmacia = $farma->nombre;
		
		$RecetaExiste = DB::table('receta_vales')->where('id_farmacia','=',$id_farmacia)->first();
		
		if(isset($RecetaExiste->id) && $RecetaExiste->id > 0):
				
        Excel::create('Reporte_produtos_atendidos', function($excel) use($fecha_inicio, $fecha_fin, $id_farmacia) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_farmacia) {
                $model_farma = new Farmacia;
