		Excel::create('Reportes_de_Productos_por_Fecha_de_Vencimiento', function($excel) use($fecha_inicio, $fecha_fin, $id_farmacia,$nombre_farmacia) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_farmacia,$nombre_farmacia) {
				
				$txtfechaDesde_=explode("-",$fecha_inicio);
				$txtfechaHasta_=explode("-",$fecha_fin);
				
				$fechaIni=$txtfechaDesde_[2]."/".$txtfechaDesde_[1]."/01"; 
				$fechaFin=$txtfechaHasta_[2]."/".$txtfechaHasta_[1]."/01";
				
				$mes = date("m", strtotime($fechaIni));
				$ano=  date("Y", strtotime($fechaIni));
				
				$limite=$txtfechaHasta_[1].'/'.$txtfechaHasta_[2];
				$nuevo=0;
				
				$validarFechaDesde = $txtfechaDesde_[1].'/'.$txtfechaDesde_[2];
				$validarFechaHasta = $txtfechaHasta_[1].'/'.$txtfechaHasta_[2];
								
				$arrayMeses=array();
				$arrayMeses[]=$mes."/".$ano;
				
				//$model_stock = new \App\Models\Stock_farmacia;
				//$stocks = $model_stock->GetStockPorLotesByFechaVencimiento($id_farmacia, $fecha_inicio, $fecha_fin);
				$model_kardex = new \App\Models\Kardexe;
				$stocks = $model_kardex->GetKardexLotesByCodigoProductoAndIdFarmaciaAndFechasVencimiento("", $id_farmacia, $fecha_inicio, $fecha_fin);
				
                $variable = [];
                $n = 0;
				$cantidadTotal = 0;
				$importe_total = 0;
                foreach ($stocks as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Productos por Fecha de Vencimiento"));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                array_push($variable, array("Total: " . $n));
                array_push($variable, array(""));
				$cabecera = array();
				$n = 0;
				$cabecera[] = "Nro";
				$cabecera[] = "Código";
				$cabecera[] = "Producto Farmacéutico o Dispositivo Médico";
				$cabecera[] = "Unidad";
				$cabecera[] = "Lote";
				$cabecera[] = "R.S.";
				$cabecera[] = "Stock Actual";
				$cabecera[] = $mes."/".$ano;
				$m = 0;
				while($nuevo!=$limite && $validarFechaDesde!=$validarFechaHasta):
						$m++;
						$nuevo=date("m/Y", mktime(0, 0, 0, $mes+$m, 1, $ano));
						$arrayMeses[]=$nuevo;
						$cabecera[] = $nuevo;
				endwhile;
				
				array_push($variable, $cabecera);
				
                $m = 1;
                foreach ($stocks as $c) {
					$acumulado = 0;
                    $nro_mes_acumulado = \App\Models\Kardexe::ShowNroMesByProd($c->id_producto,$nombre_farmacia,$fecha_inicio,$fecha_fin);
					$datos = array();
					$n++;
					$datos[] = $n;
					$datos[] = $c->prod_farmaceutico;
					$datos[] = $c->prod_farmaceutico;
					$datos[] = $c->abreviatura;
					$datos[] = $c->lote;
					$datos[] = $c->registro_sanitario;
					$datos[] = $c->cantidad;
					
					foreach($arrayMeses as $rowMes):
                                
						$fechaMes = explode("/",$rowMes);
						$month = $fechaMes[1].'-'.$fechaMes[0];
						$aux = date('Y-m-d', strtotime("{$month} + 1 month"));
						$last_day = date('Y-m-d', strtotime("{$aux} - 1 day"));
						$fecha_inicio_='01-'.str_replace("/","-",$rowMes);
						$fecha_fin_=$last_day;
                                
						//$fv = \App\Models\Stock_farmacia::GetStockPorLotesByFechaVencimientoAndProducto($id_farmacia, $fecha_inicio_, $fecha_fin_,$c->codigo_producto);
						$fv = \App\Models\Kardexe::GetKardexLotesByCodigoProductoAndIdFarmaciaAndFechasVencimiento($c->id_producto, $id_farmacia, $fecha_inicio_, $fecha_fin_);
                                
						if(count($fv) > 0):
							$originalDate3 = $fv[0]->fecha_vencimiento;
							$fecha_ven = date("m-Y", strtotime($originalDate3));
							$datos[] = $fecha_ven;
						else:
							$datos[] = "";
						endif;
                                
                    endforeach;
					
					array_push($variable, $datos);
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->store('xls',storage_path('reportes/'.$fecha_fin.'/'.$nombre_farmacia));
		
