	public function exportar_reporte_admision($fecha_inicio, $fecha_fin, $id_farmacia, $dni_beneficiario ,$nro_admision) {
	
        Excel::create('Exportar Reportes de Admision', function($excel) use($fecha_inicio, $fecha_fin, $id_farmacia, $dni_beneficiario ,$nro_admision) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_farmacia, $dni_beneficiario ,$nro_admision) {
				
				if($dni_beneficiario!="" || $nro_admision!=""):
					$fechaDesde 	= "";
					$fechaHasta 	= "";
				endif;
				
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                //------------------------------------------------------                        
                $model_receta = new \App\Models\Receta_vale;
				$recetas=$model_receta->AllAdmisionByFarmaAndFechaDesdeHasta($id_farmacia, $fecha_inicio ,$fecha_fin, $dni_beneficiario, $nro_admision);
                $variable = [];
                $n = 0;
                foreach ($recetas as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Admisión del " . $nombre_farmacia));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                //array_push($variable, array("Diagnosticos según prescripción: " . $n));
                array_push($variable, array(""));
                array_push($variable, array("N", "Nro. Admisión", "Fecha","Servicio","DNI","Beneficiario","Tipo","Registrador"));
                $m = 1;
                foreach ($recetas as $c) {
					$originalDate2 = $c->fecha_admision;
                    $fecha = date("d-m-Y", strtotime($originalDate2));
                    array_push($variable, array($m++, $c->nro_admision, $fecha,$c->consultorio,$c->dni_beneficiario, utf8_decode($c->paterno_beneficiario." ".$c->materno_beneficiario.", ".$c->nombre_beneficiario), $c->tipo_beneficiario, $c->name));
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
	
    	public function exportar_reporte_kardex_lote($fecha_inicio, $fecha_fin, $id_producto, $id_user) {
	
        Excel::create('Exportar Reportes de Kardex lote', function($excel) use($fecha_inicio, $fecha_fin, $id_producto, $id_user) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_producto, $id_user) {
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByUser($id_user);
                $id_farmacia = $farma->id;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                //------------------------------------------------------                        
                $model_receta = new \App\Models\Receta_vale;
                $model_kardex = new \App\Models\Kardexe();
                $kardex = $model_receta->AllKardexByFarmaAndProducto($id_farmacia,$nombre_farmacia, $id_producto, $fecha_inicio, $fecha_fin);
		            //print_r($kardex);
                $variable = [];
                $n = 0;
                foreach ($kardex as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Kardex del " . $nombre_farmacia));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                //array_push($variable, array("Diagnosticos según prescripción: " . $n));
                array_push($variable, array(""));
                //array_push($variable, array("N", "ID","Fecha Movimiento", "Hora","Tipo Documento", "Num Documento", "Codigo","Producto","Registro Sanitario","Lote","Fecha de Vencimiento","precio_unitario", "Saldo Anterior","Ingreso","Salida","Nuevo Saldo"));
                array_push($variable, array("N", "ID","Fecha Movimiento", "Hora","Tipo Documento", "Num Documento", "Codigo","Producto","Registro Sanitario","Lote","Fecha de Vencimiento","precio_unitario", "Saldo Anterior","Ingreso","Salida","Nuevo Saldo","Presentación"));
                $m = 1;
                $fecha_inicio = strtotime('-1 day', strtotime($fecha_inicio));
                $fecha_inicio = date('j-m-Y', $fecha_inicio);

                $kardex_inicial = $model_kardex->ShowTotalKardexByFarmaciaResumen($id_farmacia, $id_producto, $fecha_inicio);
                //$saldo = (isset($kardex_inicial[0])) ? $kardex_inicial[0] : 0;
                        if(isset($kardex_inicial[0]->total)):
                            if($kardex_inicial[0]->id_producto==11045 || $kardex_inicial[0]->id_producto==15938 || $kardex_inicial[0]->id_producto==14607 || $kardex_inicial[0]->id_producto==14608):
                                $saldo =$kardex_inicial[0]->total/1000;
                            else:
                                $saldo =$kardex_inicial[0]->total;
                            endif;
                        else:
                            $saldo =0;
                        endif;
                        
                        foreach ($kardex as $c) {
                        
                            //$fecha = date("d-m-Y", strtotime($originalDate2));
                            if($m == 1){
                                $saldo = $saldo;
                            } else {
                                $saldo = $nsaldo;
                            }
                            if ($c->id_tipo_movimiento == 1 || $c->id_tipo_movimiento == 2 || $c->id_tipo_movimiento == 3 || $c->id_tipo_movimiento == 8 || $c->id_tipo_movimiento == 9)://Ingresos
                                if($c->id_producto==11045 || $c->id_producto==15938 || $c->id_producto==14607 || $c->id_producto==14608):
                                    $nsaldo = $saldo + $c->cantidad/1000;
                                    $ingreso = $c->cantidad/1000;
                                else:
                                    $nsaldo = $saldo + $c->cantidad;
                                    $ingreso = $c->cantidad;
                                endif;
                                $salida = 0;
                            endif;
                            if ($c->id_tipo_movimiento == 4 || $c->id_tipo_movimiento == 5 || $c->id_tipo_movimiento == 6 || $c->id_tipo_movimiento == 7)://Salidas
                                if($c->id_producto==11045 || $c->id_producto==15938 || $c->id_producto==14607 || $c->id_producto==14608):
                                    $nsaldo = $saldo - $c->cantidad/1000;  
                                    $salida = $c->cantidad/1000;
                                else:
                                    $nsaldo = $saldo - $c->cantidad;  
                                    $salida = $c->cantidad;
                                endif;
                                $ingreso = 0;
                            endif;                    
                            $originalDate3 = $c->created_at;
                            $hora = date("H:i:s", strtotime($originalDate3));
                                                                                
                                
                           //array_push($variable, array($m++, $c->id,$c->fecha_movimiento,$hora,$c->tipo_movimiento, $c->numero_movimiento,$c->codigo_producto,$c->nombre_producto,$c->registro_sanitario,$c->lote,$c->fecha_vencimiento,$c->precio_unitario,$saldo,$ingreso,$salida,$nsaldo));
                           array_push($variable, array($m++, $c->id,$c->fecha_movimiento,$hora,$c->tipo_movimiento, $c->numero_movimiento,$c->codigo_producto,$c->nombre_producto,$c->registro_sanitario,$c->lote,$c->fecha_vencimiento,$c->precio_unitario,$saldo,$ingreso,$salida,$nsaldo,$c->presentacion_comercial));
                        }
                    
                
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
    
    	public function exportar_reporte_recetas_by_producto($id_farmacia, $id_producto, $fecha_inicio, $fecha_fin) {
	
