                   array_push($variable, array($m++, $c->_fecha,$c->_nroreceta, $c->_tipdocbene,$c->_nrodocbene,$c->_nrohcbene,$c->_beneficiario,$c->_medico,$c->_servicio,$c->_diagnostico,$c->_usuario,$cantdispensanda));
