	public function exportar_consolidado_stock($fecha_inicio, $fecha_fin, $id_user, $id_anaquel, $id_consultorio) {
	   
        Excel::create('Exportar Reportes de Consolidado de Movimiento por Producto', function($excel) use($fecha_inicio, $fecha_fin, $id_user, $id_anaquel, $id_consultorio) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_user, $id_anaquel, $id_consultorio) {
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByUser($id_user);
                $id_farmacia = $farma->id;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                
                if ($id_consultorio <> 0){
                    $model_consultorio = new Consultorio;
                    $consultorio= $model_consultorio->GetNombreById($id_consultorio);
                    $nom_consultorio = $consultorio->nombre;
                }
                //------------------------------------------------------                        
                //$model_receta = new \App\Models\Receta_vale;
                $model_kardex = new \App\Models\Kardexe();
                //$kardex = $model_receta->AllKardexByFarmaAndProducto($id_farmacia, $id_producto, $fecha_inicio, $fecha_fin);
				
                if ($fecha_inicio == "0"):
                        $fecha_fin=$model_kardex->getFechaServidor();
                        $fecha_ini = strtotime($fecha_fin);
                        $fecha_ini = date('Y-m-j', $fecha_ini)." 00:00:00";
                        $fecha_fin = $fecha_fin." 23:59:59";
                else:
                        $fecha_ini = $fecha_inicio;
                        $fecha_fin = $fecha_fin;
                endif;

                $kardex = $model_kardex->ShowTotalKardexByFarmaciaConsolidado($farma->id,$fecha_ini,$fecha_fin, $id_anaquel, $id_consultorio);

                $variable = [];
                $n = 0;
				if(isset($kardex)){
					foreach ($kardex as $c) {
						$n++;
					}
				}
                array_push($variable, array("Reporte de Consolidado de Movimiento por Producto del " . $nombre_farmacia));
                array_push($variable, array('De: ' . $fecha_inicio . ' a ' . $fecha_fin));
                if ($id_consultorio <> 0){
                    array_push($variable, array('Servicio: ' . $nom_consultorio));
                }
                array_push($variable, array(""));
                array_push($variable, array("N", "Codigo", "Detalle de Producto", "U.Medida", "Tipo de Producto", "Anaquel","Saldo Anterior","Entradas","Salidas", "Stock Actual","P.Unit","Vencimiento"));
                $m = 1;
				if(isset($kardex)){
					foreach ($kardex as $c) {
					if($c->fecha_vencimiento == ""){ $fecVen = "Vencido";} else{$fecVen = $c->fecha_vencimiento;}
					  if($c->presentacion==1)
						{
                           array_push($variable, array($m++, $c->codigo_producto,$c->nombre_producto, $c->unidad,$c->nombre_tipoproducto,$c->anaquel, number_format($c->stock_desde, 3, '.', ','),number_format($c->ingresos, 3, '.', ','),number_format(($c->egresos-$c->devueltas),3, '.', ','),number_format($c->stock_hasta, 3, '.', ','),number_format($c->precio_unitario, 3, '.', ','), $fecVen));
						}
					  else
						{
						  if($c->id_producto==11045 || $c->id_producto==15938 || $c->id_producto==14607 || $c->id_producto==14608)
                            {
                                array_push($variable, array($m++, $c->codigo_producto,$c->nombre_producto, $c->unidad,$c->nombre_tipoproducto,$c->anaquel, number_format($c->stock_desde/1000, 3, '.', ','),number_format($c->ingresos/1000, 3, '.', ','),number_format(($c->egresos/1000-$c->devueltas/1000),3, '.', ','),number_format($c->stock_hasta/1000, 3, '.', ','),number_format($c->precio_unitario, 3, '.', ','), $fecVen));
                            }
                            else
                            {
                                array_push($variable, array($m++, $c->codigo_producto,$c->nombre_producto, $c->unidad,$c->nombre_tipoproducto,$c->anaquel, number_format($c->stock_desde, 0, '.', ','),number_format($c->ingresos, 0, '.', ','),number_format(($c->egresos-$c->devueltas), 0, '.', ','),number_format($c->stock_hasta, 0, '.', ','),number_format($c->precio_unitario, 2, '.', ','), $fecVen));
                            }
						}
					   
					}
				}
                $sheet->with($variable)->mergeCells('A2:F2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
    
	
	public function exportar_reporte_quirurgico($fecha_inicio, $fecha_fin, $id_farmacia, $dni_beneficiario ,$nro_admision) {
	
        Excel::create('Exportar Reportes de Centro Quirurgico', function($excel) use($fecha_inicio, $fecha_fin, $id_farmacia, $dni_beneficiario ,$nro_admision) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_farmacia, $dni_beneficiario ,$nro_admision) {
				
				if($dni_beneficiario!="" || $nro_admision!=""):
					$fechaDesde 	= "";
					$fechaHasta 	= "";
				endif;
				
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                //------------------------------------------------------                        
                $model_receta = new \App\Models\Receta_vale;
				$recetas=$model_receta->AllQuirurgicoByFarmaAndFechaDesdeHasta($id_farmacia, $fecha_inicio ,$fecha_fin, $dni_beneficiario, $nro_admision);
				//print_r($recetas);
                $variable = [];
                $n = 0;
                foreach ($recetas as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Centro Quirurgico del " . $nombre_farmacia));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                //array_push($variable, array("Diagnosticos según prescripción: " . $n));
                array_push($variable, array(""));
                array_push($variable, array("N", "Nro. Admisión", "Nro. Quirurgico", "Fecha", "Servicio","Origen","Sala","Turno", "DNI","Beneficiario","Tipo","Registrador"));
                $m = 1;
                foreach ($recetas as $c) {
					$turno = "";
					if($c->turno == "M")$turno = "MAÑANA";
					if($c->turno == "T")$turno = "TARDE";
					$originalDate2 = $c->fecha_quirurgico;
                    $fecha = date("d-m-Y", strtotime($originalDate2));
                    array_push($variable, array($m++, $c->nro_admision,$c->nro_quirurgico, $fecha, $c->consultorio,$c->origen_paciente,$c->sala,$turno,$c->dni_beneficiario, utf8_decode($c->paterno_beneficiario." ".$c->materno_beneficiario.", ".$c->nombre_beneficiario), $c->tipo_beneficiario, $c->name));
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
	
	public function exportar_reporte_receta($fecha_inicio, $fecha_fin, $id_farmacia, $dni_beneficiario ,$nro_receta, $estado, $iddispensador, $idconsultorio) {
	
        Excel::create('Exportar Reportes de Receta', function($excel) use($fecha_inicio, $fecha_fin, $id_farmacia, $dni_beneficiario ,$nro_receta, $estado,$iddispensador, $idconsultorio) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_farmacia, $dni_beneficiario ,$nro_receta, $estado,$iddispensador,$idconsultorio) {
				
				if($dni_beneficiario!="" || $nro_admision!=""):
					$fechaDesde 	= "";
					$fechaHasta 	= "";
				endif;
				
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                //print_r($nombre_farmacia);exit();
                //------------------------------------------------------                        
                $model_receta = new \App\Models\Receta_vale;
                if ($iddispensador == 0) $iddispensador="";
				if($estado == 1):
					$recetas=$model_receta->AllRecetasByFarmaAndFechaDesdeHasta($id_farmacia, $fecha_inicio ,$fecha_fin, $dni_beneficiario, $nro_receta, $iddispensador, $idconsultorio);
                    //dd($recetas);
                else:
					$recetas=$model_receta->AllRecetasInvalidasByFarmaAndFechaDesdeHasta($id_farmacia, $fecha_inicio ,$fecha_fin, $dni_beneficiario, $nro_receta, $iddispensador, $idconsultorio);
				endif;
                $variable = [];
                $n = 0;
                foreach ($recetas as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Receta del " . $nombre_farmacia));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                //array_push($variable, array("Diagnosticos según prescripción: " . $n));
                array_push($variable, array(""));
                //array_push($variable, array("N", "Nro. Admisión", "Nro. Receta","Fecha", "DNI","Beneficiario","Tipo","Dispensador"));
                if($id_farmacia==21){
                  array_push($variable, array("N","Servicio", "Tipo Via","Sub Via","Final","Nro. Receta","Hora Registro","Fecha Dispensación","Fecha Expedición", "Tipo Doc.", "Nro. Doc.","Beneficiario","Tipo","Dispensador"));  
                }
                else
                {
                  if($id_farmacia==22){
                    
                    array_push($variable, array("N", "Tipo Receta","Servicio","Nro. Receta","Hora Registro","Fecha Dispensación","Fecha Expedición", "Tipo Doc.", "Nro. Doc.","Beneficiario","Tipo","Dispensador"));
                  }
                else
                  {
                    array_push($variable, array("N", "Servicio","Nro. Receta","Hora Registro","Fecha Dispensación","Fecha Expedición", "Tipo Doc.", "Nro. Doc.","Beneficiario","Tipo","Dispensador"));
                  }
                }
                
                $m = 1;
                foreach ($recetas as $c) {
                    $originalDate1 = $c->fecha_expedicion;
                    $fechaE = date("d-m-Y", strtotime($originalDate1));
                    $originalDate2 = $c->fecha_registro;
                    $fecha = date("d-m-Y", strtotime($originalDate2));
                    $originalDate3 = $c->created_at;
                    $hora = date("H:i:s", strtotime($originalDate3));
                        
                        
                    //array_push($variable, array($m++, $c->nro_admision, $c->nro_receta, $fecha, $c->dni_beneficiario, $c->paterno_beneficiario." ".$c->materno_beneficiario.", ".$c->nombre_beneficiario, $c->tipo_beneficiario, $c->name));
                    if($id_farmacia==21){
                      array_push($variable, array($m++,$c->consultorio, $c->tipo_via,$c->sub_via,$c->final_via,$c->nro_receta,$hora, $fechaE, $fecha, $c->tipodoc_beneficiario, $c->dni_beneficiario, $c->paterno_beneficiario." ".$c->materno_beneficiario.", ".$c->nombre_beneficiario, $c->tipo_beneficiario, $c->paterno_usuario." ".$c->materno_usuario.", ".$c->nombre_usuario));
                    }
                    else
                    {
                      if($id_farmacia==22){
                        array_push($variable, array($m++,$c->tipo_receta, $c->consultorio,$c->nro_receta,$hora, $fechaE, $fecha, $c->tipodoc_beneficiario, $c->dni_beneficiario, $c->paterno_beneficiario." ".$c->materno_beneficiario.", ".$c->nombre_beneficiario, $c->tipo_beneficiario, $c->paterno_usuario." ".$c->materno_usuario.", ".$c->nombre_usuario));
                      }
                      else
                      {
                        array_push($variable, array($m++, $c->consultorio,$c->nro_receta,$hora, $fechaE, $fecha, $c->tipodoc_beneficiario, $c->dni_beneficiario, $c->paterno_beneficiario." ".$c->materno_beneficiario.", ".$c->nombre_beneficiario, $c->tipo_beneficiario, $c->paterno_usuario." ".$c->materno_usuario.", ".$c->nombre_usuario));
                      }
                    }
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
	
	public function exportar_reporte_cita($id_user, $fecha_ini, $fecha_fin,$fecha_reg_ini, $fecha_reg_fin, $dni, $paciente, $estado, $id_servicio, $id_consultorio, $id_medico, $id_condicion_establecimiento, $id_condicion_servicio) {
		
		if($dni==0)$dni="";
		if($paciente==0)$paciente="";
		
		if($fecha_ini==0)$fecha_ini="";
		if($fecha_fin==0)$fecha_fin="";
		if($fecha_reg_ini==0)$fecha_reg_ini="";
		if($fecha_reg_fin==0)$fecha_reg_fin="";
		
		$modelusuario = new Farmacia();
        $usuario = $modelusuario->GetNombreUsuarioByIdUser($id_user);
		$nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;
		$paciente= strtoupper($paciente);
        Excel::create('Exportar Reportes de Cita', function($excel) use($fecha_ini, $fecha_fin,$fecha_reg_ini, $fecha_reg_fin, $dni, $paciente, $estado, $id_servicio, $id_consultorio, $id_medico, $nombre_usuario, $id_user, $id_condicion_establecimiento, $id_condicion_servicio) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin,$fecha_reg_ini, $fecha_reg_fin, $dni, $paciente, $estado, $id_servicio, $id_consultorio, $id_medico, $nombre_usuario, $id_user, $id_condicion_establecimiento, $id_condicion_servicio) {
				
				$modelfarma = new Farmacia;
				$model_usuario = new User;
				$model_medico = new \App\Models\Medico();
				$model_citas = new \App\Models\Cita();
				$farmacia = $modelfarma->GetFarmaByUser($id_user);
                $id_farmacia = $farmacia->id;
                $establecimiento = $modelfarma->GetEstablecimientoPNP($id_farmacia);
				$modo_validacion = $farmacia->modo_validacion;
				//----------------------------------------------------------------------
				$usuario_actual = $model_usuario->GetById($id_user);
				$flagemergenciareferencia = $usuario_actual->flaghistoria;
				$medico = 0;
				if($flagemergenciareferencia!=1){
                    if(Auth::user()->tipo_registro==1):
                       $medico_actual = $model_medico->GetMedicoByDniAndEstablecimiento($usuario_actual->dni,$farmacia->id_establecimiento);
					   $medico = $medico_actual->id;
                    endif;
				}
				
				$p[]=$fecha_ini;
				$p[]=$fecha_fin;
				$p[]=$fecha_reg_ini;
				$p[]=$fecha_reg_fin;
				$p[]=$dni;
				$p[]=$paciente;
				//$p[]=$id_servicio;
				$p[]=(isset($id_servicio) && $id_servicio!="")?$id_servicio:0;
				//$p[]=$id_consultorio;
				$p[]=(isset($id_consultorio) && $id_consultorio!="")?$id_consultorio:0;
				$p[]=$id_medico;
				$p[]=Auth::user()->id_establecimiento;
                $p[] = $id_condicion_establecimiento;
                $p[] = $id_condicion_servicio;
				$p[]=$estado;
				$p[]=1;
				$p[]=50000;
				$citas = $model_citas->listar_cita_ajax($p);
                $nro_atendidas = isset($citas[0]->totalrows)?$citas[0]->totalrows:0;  
				//$citas = $model_citas->AllCitaConfirmaPacienteFecha($fecha, $dni, $paciente, $medico, $estado);
				//$nro_atendidas = $model_citas->GetCountCitaConfirmaPacienteFecha($fecha, $dni, $paciente, $medico, $estado);
                //--------------------------------------------------------------
         
                $variable = [];
                $n = 1;
                array_push($variable, array($establecimiento->nombre));
                array_push($variable, array("Reporte de Citas"));
                array_push($variable, array("Fecha Cita Desde: " . $fecha_ini));
				array_push($variable, array("Fecha Cita Hasta: " . $fecha_fin));
				array_push($variable, array("Fecha Registro Desde: " . $fecha_reg_ini));
				array_push($variable, array("Fecha Registro Hasta: " . $fecha_reg_fin));
                array_push($variable, array("Total: " . $nro_atendidas . " citas"));
                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array(""));
                array_push($variable, array("N","FECHA CITA", "HORA CITA","FECHA REGISTRO","HORA REGISTRO", "TIPO DOC", "NUMERO DOC", "NUMERO HISTORIA", "PACIENTE","PARENTESCO","SEXO","FECHA DE NACIMIENTO", "EDAD", "TELEFONO", "TELEFONO 2",
                    "RESPONSABLE CITA","TIPO DE CITA","SERVICIO", "CONSULTORIO", "MEDICO", "ESTADO","CONDICION IPRESS","CONDICION UPSS","REFERIDO","ESTABLECIMIENTO REFERENCIA","OBSERVACION","CONSULTORIO REFERENCIA", "CODIGO SITEDS", "OBSERVACION DE CITAS"));
                foreach ($citas as $r) {
                    if($r->establecimiento_referencia == "0"){
                        $r->establecimiento_referencia = "";
                    }
					$medico = "";
					if($r->medico_paterno!="")$medico = $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre;
					
                  array_push($variable, array($n++,$r->dia,$r->hora,$r->dia_registro,$r->hora_registro, $r->tipo_doc_ident, $r->nro_doc_ident,$r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre ,$r->parentesco,$r->sexo,$r->fecha_nac, $r->edadafiliado, $r->telefono, $r->telefono2,$r->usuario_cita,$r->tipo_cita,$r->servicio, $r->consultorio, $medico, $r->estado_cita, $r->condicion_establecimiento,$r->condicion_servicio,$r->referido,$r->establecimiento_referencia,$r->comentario_estado_observado,$r->servicio_referencia, $r->codigo_siteds, $r->obs_registro_cita));
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
            });
        })->export('xls');
    }



