    if($r->medico_paterno != "") {
        $medico = $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre;
    }
    
    $datos = array($n++, $r->dia, $r->hora, $r->dia_registro, $r->hora_registro, $r->tipo_doc_ident, $r->nro_doc_ident, $r->nombre_estado_paciente, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre, $r->fech_ult_regla, $r->fech_prob_parto);
    
    // Si el paciente es gestante
    if ($r->nombre_estado_paciente == 'Gestante') {
        // Agrega valores nulos para las columnas adicionales
        array_push($datos, null, null, null, null, null);
    } elseif ($r->nombre_estado_paciente == 'Puerpera') {
        // Si el paciente es puerpera, llenar las columnas adicionales con los datos correspondientes
        array_push($datos, $r->fecha_parto,$r->cui,$r->num_doc,$r->sexo,$r->estado);
    }
        elseif ($r->nombre_estado_paciente == 'No gestante') {
            // Si la fecha de parto + 28 días es igual a la fecha actual, llenar todas las columnas adicionales
            $fechaPartoMas28Dias = date('Y-m-d', strtotime($r->fecha_parto . ' +28 days'));
            if ($fechaPartoMas28Dias == date('Y-m-d')) {
                array_push($datos, $r->fecha_parto, $r->tipo_doc, $r->num_doc, $r->sexo, $r->estado);
            } else {
                // De lo contrario, agregar valores nulos para las columnas adicionales
                array_push($datos, null, null, null, null, null);
            }
        }
        
        array_push($variable, $datos);
    }


$sheet->with($variable)
    ->mergeCells('A2:E2')
    ->mergeCells('A3:E3')
    ->mergeCells('A4:C4')
    ->mergeCells('A5:C5')
    ->mergeCells('A6:C6')
    ->row(1, function($row) { 
        $row->setBackground('#B3E5FC'); 
    });
});


        })->export('xls');
    }
    
