					$medico_actual = $model_medico->GetMedicoByDniAndEstablecimiento($usuario_actual->dni,$farmacia->id_establecimiento);
					$medico = $medico_actual->id;
				}
				
                $p[]=Auth::user()->id_establecimiento;
                $p[]=$fecha_ini;
                $p[]=$fecha_fin;
                $p[]=$dni;
                $p[]=$paciente;
                $p[]=$estado;
                $p[]=$id_atencion=2;
                $p[]=$id_prioridad;
                $p[]=$id_topico;
                //TODO: Definir la pagina y cantidad de registros desde el frontend
                $p[]=1;
                $p[]=10000;
                
                $evaluacion = $model_evaluacion->listar_evaluacion_emergencia($p);
                error_log("NUEVA CONSULTA");
                error_log(serialize(array($evaluacion)));
                $nro_atendidas = isset($evaluacion[0]->totalrows)?$evaluacion[0]->totalrows:0;
						
                $excelName = 'Exportar_Reportes_de_Evaluacion_' . $id_user . '_' . Carbon::now()->format('Y-m-d_H-i-s');
        $excelNameResponse = 'Exportar_Reportes_de_Evaluacion_' . $id_user . '_' . Carbon::now()->format('Y-m-d_H-i-s') . '.xlsx';
        Excel::create($excelName, function($excel) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $nombre_usuario, $id_user,$id_atencion,$id_prioridad, $id_topico,$establecimiento,$evaluacion) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $nombre_usuario, $id_user,$id_atencion,$id_prioridad, $id_topico,$establecimiento,$evaluacion) {
				
