                array_push($variable, array("Fecha Desde: " . $fecha_ini));
				array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                //array_push($variable, array("Total: " . $nro_atendidas . " evaluaciones"));
                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array(""));
                array_push($variable, array("N","FECHA", "HORA", "PRIORIDAD", "TOPICO", "NUMERO DOC", "PACIENTE","GRADO","PARENTESCO", "SEXO", "EDAD",
                    "PABELLON", "PISO", "CUARTO", "CAMA"));
                    
                foreach ($evaluacion as $r) {
					
