        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

    public function exportar_reporte_evaluacion_detallado(Request $request) {
        if(!empty($request->dni)){$dni=$request->dni;}else{$dni="";};
        if(!empty($request->fecha_ini)){$fecha_ini=$request->fecha_ini;}else{$fecha_ini="";}
            if(!empty($request->fecha_fin)){$fecha_fin=$request->fecha_fin;}else{$fecha_fin="";}
        if(!empty($request->estado)){$estado=$request->estado;}else{$estado=0;}
        if(!empty($request->id_prioridad)){$id_prioridad=$request->id_prioridad;}else{$id_prioridad=0;}
        if(!empty($request->id_topico)){$id_topico=$request->id_topico;}else{$id_topico=0;}
        if(!empty($request->id_user)){$id_user=$request->id_user;}else{$id_user="";}

        $modelusuario = new Farmacia();
        $usuario = $modelusuario->GetNombreUsuarioByIdUser($id_user);
        $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;
        $paciente= strtoupper($request->paciente);
        if(!empty($paciente)){$paciente=$paciente;}else{$paciente=""; }

        $excelName = 'Exportar_Reportesde_Evaluacion_es_Detallado_' . $id_user . '_' . Carbon::now()->format('Y-m-d_H-i-s');
        $excelNameResponse = 'Exportar_Reportesde_Evaluacion_es_Detallado_' . $id_user . '_' . Carbon::now()->format('Y-m-d_H-i-s') . '.xlsx';
        $excel = Excel::create($excelName, function($excel) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_prioridad, $id_topico, $nombre_usuario, $id_user) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_prioridad, $id_topico, $nombre_usuario, $id_user) {
              $modelfarma = new Farmacia;
              $model_evaluacion = new \App\Models\Evaluacione();
              $farmacia = $modelfarma->GetFarmaByUser($id_user);
              $id_farmacia = $farmacia->id;
              $establecimiento = $modelfarma->GetEstablecimientoPNP($id_farmacia);

              $p[]=$fecha_ini;
              $p[]=$fecha_fin;
              $p[]=$dni;
              $p[]=$paciente;
              if(Auth::user()->flaghospitalizacion==1):
                $p[]=0;
                $p[]=0;
              else:
                $p[]=(int)$id_prioridad;
                $p[]=(int)$id_topico;
              endif;
              $p[]=(int)$estado;
              $p[]=Auth::user()->id_establecimiento;
              $p[]=1;
              $p[]=10000;
            
              $encabezado_evaluacion_diagnosticos = $model_evaluacion->listar_evaluacion_diagnosticos($p); 
              $encabezado_evaluacion_procedimientos = $model_evaluacion->listar_evaluacion_procedimientos($p);

              $nro_atendidas = isset($encabezado_evaluacion_diagnosticos[0]->totalrows)?$encabezado_evaluacion_diagnosticos[0]->totalrows:0;        
              //--------------------------------------------------------------
              $variable = [];
              
              array_push($variable, array($establecimiento->nombre));
              array_push($variable, array("Reporte de Evaluaciones Médicas"));
              array_push($variable, array("Fecha Desde: " . $fecha_ini));
              array_push($variable, array("Fecha Hasta: " . $fecha_fin));
              array_push($variable, array("Total: " . $nro_atendidas . " atenciones"));
              array_push($variable, array("Usuario : " . $nombre_usuario));
              array_push($variable, array(""));
              array_push($variable, array("N","FECHA", "HORA", "TIPO DOC", "NUMERO DOC", "NUMERO HISTORIA", "PACIENTE","PARENTESCO","SEXO", "FECHA DE NACIMIENTO", "EDAD",
                  "AREA","PRIORIDAD","CAMA", "CUARTO", "PABELLON", "PISO", "TIPO DE ATENCION","RESPONSABLE ATENCION","DIAGNOSTICOS","TIPO DIAGNOSTICO","PROCEDIMIENTOS"));

              $contador = 0;
              $i_quedado = 0;
              $aux_r = null;
              $hay_procedimientos = false;
              foreach ($encabezado_evaluacion_diagnosticos as $r) {

                $hay_procedimientos = false;

                for($i = $i_quedado; $i < count($encabezado_evaluacion_procedimientos); $i++) {
                    $hay_procedimientos = true;

                    if (!empty($r->id_prestacion) && $r->id_prestacion == $encabezado_evaluacion_procedimientos[$i]->id_prestacion):

                        array_push($variable, array(
                            $r->orden, $r->fecha_atencion, $r->hora_ingreso, $r->tipo_doc_ident, $r->nro_doc_ident, 
                            $r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,$r->parentesco,$r->sexo, 
                            $r->fecha_nac, $r->edadafiliado,$r->area,$r->prioridad,$r->cama,$r->cuarto,$r->pabellon,$r->piso,$r->tipo_atencion,
                            $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre,
                            $r->codigo_dx." - ".$r->nombre_dx, $r->tipo_dx,
                            $encabezado_evaluacion_procedimientos[$i]->codigo_procedimiento." - ".$encabezado_evaluacion_procedimientos[$i]->nombre_procedimiento)
                        );
                        // Guardamos la ultima data en variable auxiliar
                        $aux_r = $r;

                        $i_quedado = $i_quedado+1;
                        break;
                    else:
                        // Validacion del procedimiento con la variable auxiliar.
                        // Esto es en el caso que hayga mas procedimientos que registros de prestaciones (que ya incluyen diagnosticos)
                        if (!empty($aux_r->id_prestacion) && $aux_r->id_prestacion == $encabezado_evaluacion_procedimientos[$i]->id_prestacion) {

                            array_push($variable, array(
                                $aux_r->orden, $aux_r->fecha_atencion, $aux_r->hora_ingreso, $aux_r->tipo_doc_ident, $aux_r->nro_doc_ident, 
                                $aux_r->nro_historia,$aux_r->asegurado_paterno.' '.$aux_r->asegurado_materno.', '.$aux_r->asegurado_nombre,$aux_r->parentesco,$aux_r->sexo, 
                                $aux_r->fecha_nac, $aux_r->edadafiliado, $aux_r->area,$aux_r->prioridad,$aux_r->cama,$aux_r->cuarto,$aux_r->pabellon,$aux_r->piso,$aux_r->tipo_atencion,
                                $aux_r->medico_paterno.' '.$aux_r->medico_materno.', '.$aux_r->medico_nombre,
                                '', '', $encabezado_evaluacion_procedimientos[$i]->codigo_procedimiento." - ".$encabezado_evaluacion_procedimientos[$i]->nombre_procedimiento)
                            );

                            $i_quedado = $i_quedado+1;

                        } else {
                            // Si no es el caso que hayga mas procedimientos que prestaciones
                            // Se procede a registrar la prestacion sin procedimiento (quiere decir que hay mas prestaciones que diagnosticos)
                            array_push($variable, array(
                                $r->orden, $r->fecha_atencion, $r->hora_ingreso, $r->tipo_doc_ident, $r->nro_doc_ident, 
                                $r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,$r->parentesco, $r->sexo,
                                $r->fecha_nac, $r->edadafiliado,$r->area,$r->prioridad,$r->cama,$r->cuarto,$r->pabellon,$r->piso,$r->tipo_atencion,
                                $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre, 
                                $r->codigo_dx." - ".$r->nombre_dx, $r->tipo_dx, '')
                            );
                            break;
                        }
                    endif;
                }

                $contador++;

                // Validacion que es el ultimo registro de prestaciones
                // Y como no hay mas procedimientos se procede a registrar la prestacion sin procedimiento
                if ($hay_procedimientos == false) {
                    if ($contador == count($encabezado_evaluacion_diagnosticos)) {
                        array_push($variable, array(
                            $r->orden, $r->fecha_atencion, $r->hora_ingreso, $r->tipo_doc_ident, $r->nro_doc_ident, 
                            $r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,$r->parentesco,$r->sexo,
                            $r->fecha_nac, $r->edadafiliado,$r->area,$r->prioridad,$r->cama,$r->cuarto,$r->pabellon,$r->piso,$r->tipo_atencion, 
                            $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre, 
                            $r->codigo_dx." - ".$r->nombre_dx, $r->tipo_dx, '')
                        );
                    }
                }

              }  
              
              $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
              });
    });
       
    $fileUrl = $excel->store('xlsx', false, true)['full'];
    return response()->json(['excelNameResponse' => $excelNameResponse]);

    
  }


	public function exportar_ordenes_ingresadas($fecha_inicio, $fecha_fin, $id_farmacia, $num_doc ,$num_siaf, $reg_sanitario, $lote, $l_origen ,$id_proveedor, $id_tipo_proceso, $id_tipo_producto,$idconcepto,$id_producto) {
  
        Excel::create('Exportar Reportes de Internamiento de Compra', function($excel) use($fecha_inicio, $fecha_fin, $id_farmacia, $num_doc ,$num_siaf, $reg_sanitario, $lote, $l_origen ,$id_proveedor, $id_tipo_proceso, $id_tipo_producto,$idconcepto,$id_producto) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_farmacia, $num_doc ,$num_siaf, $reg_sanitario, $lote, $l_origen ,$id_proveedor, $id_tipo_proceso, $id_tipo_producto,$idconcepto,$id_producto) {
        
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                //----------------------------------------------------                     
                $model_receta = new \App\Models\Receta_vale;
                if ($l_origen == 0) $l_origen="";
                if ($id_proveedor == 0) $id_proveedor="";
                if ($id_tipo_proceso == 0) $id_tipo_proceso="";
                if ($id_tipo_producto == 0) $id_tipo_producto="";
                if ($id_producto == 0) $id_producto="";
                if ($idconcepto == 0) $idconcepto="";

                if ($num_doc!=0):
                    $num_doc=str_pad($num_doc, 7, "0", STR_PAD_LEFT);
                else:
                    $num_doc=$num_doc;
                endif;

                if ($num_siaf!=0):
                    $num_siaf=str_pad($num_siaf, 10, "0", STR_PAD_LEFT);
                else:
                    $num_siaf=$num_siaf;
                endif;        
                
                $fechaDesde = date("Y-m-d", strtotime($fecha_inicio));
                $fechaHasta = date("Y-m-d", strtotime($fecha_fin));

                $model_guias = new Guia_entrada();        
                $ordenes_compra = $model_guias->ShowAllIngresos($id_farmacia, $fechaDesde, $fechaHasta, $l_origen, $num_doc,$num_siaf,$reg_sanitario,$lote, $idconcepto,$id_producto,$id_tipo_producto,$id_proveedor,$id_tipo_proceso);
        
                $variable = [];
                $n = 0;
                foreach ($ordenes_compra as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Internamiento del " . $nombre_farmacia));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                array_push($variable, array(""));               
                
                array_push($variable, array("N", "Origen","Fecha Registro","Fecha Entrada","Concepto","Num Documento","Num SIAF", "Tipo Producto","Factura","Guia", "Codigo","Producto","R.S.","Lote","F. Venc", "P.U.", "Cantidad","Proveedor","Proceso","Nro Entrega","Total Entrega","Cuenta","Clasificador","Registrador"));

                $m = 1;
                foreach ($ordenes_compra as $c) {
		  $originalDate3 = $c->created_at;
                  $fechaR = date("d-m-Y", strtotime($originalDate3));                  
		  $originalDate1 = $c->fecha_entrada;
                  $fechaE = date("d-m-Y", strtotime($originalDate1));
                  $originalDate2 = $c->fecha_vencimiento;
                  $fechaV = date("d-m-Y", strtotime($originalDate2));                  
                  
                  if($c->pc!=0)
                    $descripcion =  $c->nombre_producto.' ('.$c->cantidad.' X '.$c->presentacion_comercial.') ';
                  else
                    $descripcion =  $c->nombre_producto;

                  if($c->tipo_concepto==11){
                    $lugar_origen=$c->lugar_origen_ipress;
                  }
                  else
                  {   if($c->tipo_concepto==7 || $c->tipo_concepto==8){
                          $lugar_origen=$c->lugar_origen_prov;
                      }
                      else
                      {
                        $lugar_origen=$c->lugar_origen_dep;
                      }
                  }             

                  if($c->id_concepto==1){
                    $cuenta=$c->cuenta;
                    $gasto=$c->clas_gasto;
                  }else{
                    $cuenta="";
                    $gasto="";
                  }

                  array_push($variable, array($m++, $lugar_origen,$fechaR,$fechaE,$c->conceptos, $c->num_concepto, $c->siaf, $c->tipo_producto, $c->factura,$c->guia_entrada,$c->cod_producto, $descripcion,$c->registro_sanitario,$c->lote, $fechaV, $c->p_unitario,$c->cantidad*$c->presentacion_comercial,$c->proveedor,$c->nro_proceso."-".$c->abre_proceso,$c->nro_entrega,$c->total_entrega,$cuenta,$gasto, $c->paterno_usuario." ".$c->materno_usuario.", ".$c->nombre_usuario));                 
                            
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
