   public function exportar_ordenes_salidas($fecha_inicio, $fecha_fin, $id_farmacia,$reg_sanitario, $lote, $l_dependencia ,$l_establecimiento, $id_tipo_producto,$id_producto,$estado) {

        Excel::create('Exportar Reportes de Pecosa', function($excel) use($fecha_inicio, $fecha_fin, $id_farmacia, $reg_sanitario, $lote, $l_dependencia ,$l_establecimiento, $id_tipo_producto,$id_producto,$estado) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_farmacia,$reg_sanitario, $lote, $l_dependencia ,$l_establecimiento, $id_tipo_producto,$id_producto,$estado) {
        
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                //----------------------------------------------------                
                if ($l_dependencia == 0) $l_dependencia="";
                if ($l_establecimiento == 0) $l_establecimiento="";
                if ($id_tipo_producto == 0) $id_tipo_producto="";
                if ($id_producto == 0) $id_producto="";
                
                $fechaDesde = date("Y-m-d", strtotime($fecha_inicio));
                $fechaHasta = date("Y-m-d", strtotime($fecha_fin));

                $model_transferencias = new Transferencia();    
                $ordenes_salidas = $model_transferencias->ShowAllSalidas($id_farmacia, $fechaDesde, $fechaHasta,$estado,$reg_sanitario,$lote,$id_producto,$id_tipo_producto,$l_establecimiento,$l_dependencia);        

                $variable = [];
                $n = 0;
                foreach ($ordenes_salidas as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Pecosas de " . $nombre_farmacia));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                array_push($variable, array(""));               
                
                array_push($variable, array("N","Fecha", "Tipo Producto","Destino","Recibe", "Num Pecosa","Codigo","Producto","R.S.","Lote","F. Venc", "P.U.", "Cantidad","Total","Responsable Registro","Estado"));

                $m = 1;


                foreach ($ordenes_salidas as $c) {
                  $originalDate1 = $c->fecha_salida;
                  $fechaE = date("d-m-Y", strtotime($originalDate1));
                  $originalDate2 = $c->fecha_vencimiento;
                  $fechaV = date("d-m-Y", strtotime($originalDate2));  
                  if($c->pc!=0)
                    $descripcion =  $c->nombre_producto.' ('.$c->cantidad.' X '.$c->presentacion_comercial.') ';
                  else
                    $descripcion =  $c->nombre_producto;
					
        				  if($c->estado==6||$c->estado==4):
        					   $estado="Atendido";
        				  else:
        					   $estado="Programado";
        				  endif;

                  if(is_null($c->lugar_destino_establecimiento)){
                    array_push($variable, array($m++,$fechaE,$c->tipo_producto,$c->lugar_destino_dependencia,$c->nombre_jefe_servicio, $c->nro_acta, $c->cod_producto, $descripcion,$c->registro_sanitario,$c->lote, $fechaV, $c->p_unitario,$c->cantidad*$c->presentacion_comercial,$c->cantidad*$c->presentacion_comercial*$c->p_unitario,$c->nombre_jefe_farmacia_local,$estado));
                  }
                  else
                  { 
                    if($c->lugar_destino_establecimiento){
                      array_push($variable, array($m++,$fechaE,$c->tipo_producto,$c->lugar_destino_establecimiento,$c->nombre_jefe_servicio, $c->nro_acta, $c->cod_producto, $descripcion,$c->registro_sanitario,$c->lote, $fechaV, $c->p_unitario,$c->cantidad*$c->presentacion_comercial,$c->cantidad*$c->presentacion_comercial*$c->p_unitario,$c->nombre_jefe_farmacia_local,$estado));
                    }
                    else{
                      if($c->lugar_destino_farmacia){
                        if($c->lugar_destino_farmacia!=0){
                          array_push($variable, array($m++,$fechaE,$c->tipo_producto,$c->lugar_destino_farmacia,$c->nombre_jefe_servicio, $c->nro_acta, $c->cod_producto, $descripcion,$c->registro_sanitario,$c->lote, $fechaV, $c->p_unitario,$c->cantidad*$c->presentacion_comercial,$c->cantidad*$c->presentacion_comercial*$c->p_unitario,$c->nombre_jefe_farmacia_local,$estado));
                        }
                      }
                      else{
                        if($c->lugar_destino_dependencia){
                          array_push($variable, array($m++,$fechaE,$c->tipo_producto,$c->lugar_destino_dependencia,$c->nombre_jefe_servicio, $c->nro_acta, $c->cod_producto, $descripcion,$c->registro_sanitario,$c->lote, $fechaV, $c->p_unitario,$c->cantidad*$c->presentacion_comercial,$c->cantidad*$c->presentacion_comercial*$c->p_unitario,$c->nombre_jefe_farmacia_local,$estado));
                        }
                      }
                    }
                  }
                  
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }

    public function exportar_salidas_farmacia($fecha_inicio, $fecha_fin, $id_farmacia,$reg_sanitario, $lote, $id_tipo_producto, $id_producto) {

        Excel::create('Exportar Reportes de Pecosa', function($excel) use($fecha_inicio, $fecha_fin, $id_farmacia,$reg_sanitario, $lote, $id_tipo_producto, $id_producto) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_farmacia,$reg_sanitario, $lote, $id_tipo_producto, $id_producto) {
        
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                //----------------------------------------------------                
                if ($id_tipo_producto == 0) $id_tipo_producto="";
                if ($id_producto == 0) $id_producto="";
                
                $fechaDesde = date("Y-m-d", strtotime($fecha_inicio));
                $fechaHasta = date("Y-m-d", strtotime($fecha_fin));

                $model_transferencias = new Transferencia();    
                $ordenes_salidas = $model_transferencias->ShowAllSalidasFarmacia($id_farmacia, $fechaDesde, $fechaHasta,$reg_sanitario,$lote,$id_producto,$id_tipo_producto);
                $variable = [];
                $n = 0;
                foreach ($ordenes_salidas as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Pecosas de " . $nombre_farmacia));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                array_push($variable, array(""));               
                
                array_push($variable, array("N","Fecha", "Tipo Producto","Destino","Recibe", "Num Pecosa","Codigo","Producto","R.S.","Lote","F. Venc", "P.U.", "Cantidad","Total","Responsable Registro"));

                $m = 1;

                foreach ($ordenes_salidas as $c) {
                  $originalDate1 = $c->fecha_salida;
                  $fechaE = date("d-m-Y", strtotime($originalDate1));
                  $originalDate2 = $c->fecha_vencimiento;
                  $fechaV = date("d-m-Y", strtotime($originalDate2));  
                  if($c->pc!=0)
                    $descripcion =  $c->nombre_producto.' ('.$c->cantidad.' X '.$c->presentacion_comercial.') ';
                  else
                    $descripcion =  $c->nombre_producto;
          
                  if($c->lugar_destino_farmacia){
                      array_push($variable, array($m++,$fechaE,$c->tipo_producto,$c->lugar_destino_farmacia,$c->nombre_jefe_servicio, $c->nro_acta, $c->cod_producto, $descripcion,$c->registro_sanitario,$c->lote, $fechaV, $c->p_unitario,$c->cantidad*$c->presentacion_comercial,$c->cantidad*$c->presentacion_comercial*$c->p_unitario,$c->nombre_jefe_farmacia_local));
                  }                                            
                  else
                  {   if($c->lugar_destino_consultorio){
                              array_push($variable, array($m++,$fechaE,$c->tipo_producto,$c->lugar_destino_consultorio,$c->nombre_jefe_servicio, $c->nro_acta, $c->cod_producto, $descripcion,$c->registro_sanitario,$c->lote, $fechaV, $c->p_unitario,$c->cantidad*$c->presentacion_comercial,$c->cantidad*$c->presentacion_comercial*$c->p_unitario,$c->nombre_jefe_farmacia_local));
                      }
                      else
                      {   if($c->lugar_destino_establecimiento){
                             array_push($variable, array($m++,$fechaE,$c->tipo_producto,$c->lugar_destino_establecimiento,$c->nombre_jefe_servicio, $c->nro_acta, $c->cod_producto, $descripcion,$c->registro_sanitario,$c->lote, $fechaV, $c->p_unitario,$c->cantidad*$c->presentacion_comercial,$c->cantidad*$c->presentacion_comercial*$c->p_unitario,$c->nombre_jefe_farmacia_local));
                          }
                          else{
                              if($c->lugar_destino_dependencia)
                                  array_push($variable, array($m++,$fechaE,$c->tipo_producto,$c->lugar_destino_dependencia,$c->nombre_jefe_servicio, $c->nro_acta, $c->cod_producto, $descripcion,$c->registro_sanitario,$c->lote, $fechaV, $c->p_unitario,$c->cantidad*$c->presentacion_comercial,$c->cantidad*$c->presentacion_comercial*$c->p_unitario,$c->nombre_jefe_farmacia_local));
                          }
                      }
                  }

                }

                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
	
   public function exportar_reporte_servicio($fecha_inicio, $fecha_fin, $id_farmacia, $id_consultorio) {
  
        Excel::create('Exportar Reportes de Receta', function($excel) use($fecha_inicio, $fecha_fin, $id_farmacia, $id_consultorio) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_farmacia, $id_consultorio) {
        
        
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                //print_r($nombre_farmacia);exit();
                //------------------------------------------------------                        
                $model_receta = new \App\Models\Receta_vale;
                if ($id_consultorio == 0) $id_consultorio="";
        
          $recetas=$model_receta->AllRecetasByFarmaAndFechaDesdeHastaServicio($id_farmacia, $fecha_inicio, $fecha_fin, $id_consultorio);
        
        
                $variable = [];
                $n = 0;
                foreach ($recetas as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Beneficiario por Servicio del " . $nombre_farmacia));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                //array_push($variable, array("Diagnosticos según prescripción: " . $n));
                array_push($variable, array(""));
                //array_push($variable, array("N", "Nro. Admisión", "Nro. Receta","Fecha", "DNI","Beneficiario","Tipo","Dispensador"));
                
                                                
                $m = 1;
                if($id_farmacia==22){
                  array_push($variable, array("N", "Tipo Receta","Servicio","Tipo Doc.", "Nro. Doc.","Beneficiario","Tipo"));
                  foreach ($recetas as $c) {
                      array_push($variable, array($m++, $c->tipo_receta, $c->nombre, $c->tipodoc_beneficiario, $c->dni_beneficiario, $c->paterno_beneficiario." ".$c->materno_beneficiario.", ".$c->nombre_beneficiario, $c->tipo_beneficiario));
                    
                  }  
                }
                else
                {
                  array_push($variable, array("N", "Servicio","Tipo Doc.", "Nro. Doc.","Beneficiario","Tipo"));
                  foreach ($recetas as $c) {
                      array_push($variable, array($m++, $c->nombre, $c->tipodoc_beneficiario, $c->dni_beneficiario, $c->paterno_beneficiario." ".$c->materno_beneficiario.", ".$c->nombre_beneficiario, $c->tipo_beneficiario));
                    
                  }  
                }
                
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
   
