        else:
            $hospitalizado = $model_hospitalizado->AllHospitalizadosAltaByFarmaAndFechaDesdeHasta($id_farmacia, $fechaDesde, $fechaHasta, $dni_beneficiario, $nro_hospitalizacion, $iddispensador);
