                //array_push($variable, array("N", "Nro. Admisión", "Nro. Receta","Fecha", "DNI","Beneficiario","Tipo","Dispensador"));
              if ($estado == 1):
                array_push($variable, array("N", "Nro. Hospitalizados","Sala","Cuarto","Cama","Fecha Ingreso","Fecha Alta", "Nro. Doc.","Beneficiario","Tipo","Diagnostico","Medico que ordeno hospitalizacion"));
              else:
                array_push($variable, array("N", "Nro. Hospitalizados","Sala","Cuarto","Cama","Fecha Ingreso","Fecha Alta", "Nro. Doc.","Beneficiario","Tipo","Diagnostico","Medico que dio el alta al paciente","Condicion"));
              endif;

                $m = 1;
                foreach ($hospitalizado as $c) {
                    $originalDate1 = $c->fecha_ingreso;
                    $fechaE = date("d-m-Y", strtotime($originalDate1));
                    $originalDate2 = $c->fecha_salida;
                    if(is_null($originalDate2)){
                      $fecha = "";
                    }
                    else
                    {
                      $fecha = date("d-m-Y", strtotime($originalDate2));
                    }

                    switch ($c->condicion) {
                      case 'AL': $condicion='ALIVIADO';break;
                      case 'CU': $condicion='CURADO';break;
                      case 'NT': $condicion='NO TRATADO';break;
                      case 'FU': $condicion='FUGADO';break;
                      case 'FA': $condicion='FALLECIDO';break;
                      
                    }
                    
                    if ($estado == 1):
                      array_push($variable, array($m++, $c->nro_hospitalizacion,$c->nombre_consultorio,$c->nombre_cuarto,$c->nombre_cama, $fechaE, $fecha, $c->dni_beneficiario, $c->paterno_beneficiario." ".$c->materno_beneficiario.", ".$c->nombre_beneficiario, $c->tipo_beneficiario, $c->codigo_diagnostico."-".$c->nombre_diagnostico,$c->paterno_medico." ".$c->materno_medico.", ".$c->nombre_medico));
                    else:
                      array_push($variable, array($m++, $c->nro_hospitalizacion,$c->nombre_consultorio,$c->nombre_cuarto,$c->nombre_cama, $fechaE, $fecha, $c->dni_beneficiario, $c->paterno_beneficiario." ".$c->materno_beneficiario.", ".$c->nombre_beneficiario, $c->tipo_beneficiario, $c->codigo_diagnostico."-".$c->nombre_diagnostico,$c->paterno_medico." ".$c->materno_medico.", ".$c->nombre_medico,$condicion));
                    endif;

                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
  

    public function exportar_reporte_trama($fecha_inicio, $fecha_fin, $id_establecimiento) {
  
        
        Excel::create('Exportar Trama para SALUDPOL', function($excel) use($fecha_inicio, $fecha_fin, $id_establecimiento) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_establecimiento) {
        
                //------------------------------------------------------                        
                $model_receta = new \App\Models\Receta_vale;
        
                $recetas=$model_receta->TramaAllRecetasByFarmaAndFechaDesdeHasta($id_establecimiento, $fecha_inicio ,$fecha_fin); 
        
                $variable = [];
                $n = 0;
                foreach ($recetas as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Trama SALUDPOL "));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                array_push($variable, array(""));
                array_push($variable, array("N","Nro Receta", "Tipo Documento","N Documento","Nombre Paciente", "Apellido Paterno", "Apellido Materno","Tipo Atencion","Fecha Expedicion","Fecha Atencion","DNI Medico","Nombre Medico","Apellido Paterno","Apellido Materno","Especialidad","Servicio","Codigo DX","Descripcion Diagnostico","Tipo Producto","Codigo","Descripcion","Cantidad","Precio","IPRESS"));
                $m = 1;

                foreach ($recetas as $c) {
                    $originalDate1 = $c->_fecha_registro;
                    $fecha1= date("d-m-Y", strtotime($originalDate1));                    
                    $originalDate2 = $c->_fecha_expedicion;
                    $fecha2= date("d-m-Y", strtotime($originalDate2));  
                    
                    array_push($variable, array($m++, $c->_nro_receta,$c->_tipodoc_beneficiario, $c->_dni_beneficiario, $c->_nombre_beneficiario, $c->_paterno_beneficiario, $c->_materno_beneficiario,  $c->_tipo_receta,$fecha2,$fecha1,$c->_dni_medico, $c->_nombre_medico, $c->_paterno_medico, $c->_materno_medico, $c->_especialidad_medico, $c->_nombre_servicio, $c->_codigo_dx, $c->_nombre_dx, $c->_tipo_producto, $c->_codigo_producto, $c->_nomb_producto, $c->_cantidad,$c->_precio, $c->_cod_ipress));
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
  
