    public function imprimir_requerimientos($iduser, $id_requerimiento) {
        //====================
        $model_farma = new Farmacia;
        $farma = $model_farma->GetFarmaByUser($iduser);
        $id_farmacia = $farma->id;
        $nombre_farmacia = $farma->nombre;
        $requerimientodato=  \App\Models\Requerimiento::where('id',$id_requerimiento)->first();
        $fecha_requerimiento=$requerimientodato->created_at;
        $date_requerimiento = date("d-m-Y", strtotime($fecha_requerimiento));        
        //====================
        Excel::create('Requerimiento '.$requerimientodato->documento.' con fecha '.$date_requerimiento, function($excel) use($id_farmacia, $nombre_farmacia, $id_requerimiento) {
            $excel->sheet('GENERAL', function($sheet) use($id_farmacia, $nombre_farmacia, $id_requerimiento) {
                //$model_requerimientos = new \App\Models\Requerimiento;
                //$requerimientos = $model_requerimientos->ShowRequerimientosByIdRequerimiento();
                $requerimientos = DB::table('requerimientos')
                        ->select('requerimientos.*')
                        ->where('id', $id_requerimiento)
                        ->first();
                $productos = DB::table('req_productos')
                        ->join('productos', 'req_productos.codigo_producto', '=', 'productos.codigo')
                        ->join('unidades', 'productos.id_unidad', '=', 'unidades.id')
                        ->select('req_productos.*', 'unidades.abreviatura', 'productos.nombre')
                        ->orderBy('productos.nombre', 'asc')
                        ->where('req_productos.id_requerimiento', $id_requerimiento)
                        ->where('req_productos.estado', 1)
                        ->get();
                //var_dump($productos); exit;
                $originalDate2 = $requerimientos->created_at;
                //var_dump($originalDate2); exit;
                $fecha = date("d-m-Y", strtotime($originalDate2));
                $variable = [];
                $n = 1;
                array_push($variable, array($nombre_farmacia));
                if ($requerimientos->fecha == 2) {
                    array_push($variable, array("REQUERIMIENTOS N° ".$requerimientos->numero));
                    array_push($variable, array("Fecha:".$requerimientos->created_at));
                } else {                    
                    array_push($variable, array("REQUERIMIENTOS N° ".$requerimientos->numero));
                    array_push($variable, array("Fecha: ".$requerimientos->created_at));
                }
                array_push($variable, array(""));
                array_push($variable, array("N", "CODIGO", "DESCRIPCION", "UNIDAD", "CANTIDAD"));
                foreach ($productos as $p) {
                    array_push($variable, array($n++, $p->codigo_producto, $p->nombre, $p->abreviatura, $p->cantidad));
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:C3')->mergeCells('A4:C4')->mergeCells('D3:E3');
            });
        })->export('xls');
    }

