			}
		
		
		
		
			$time = time();
			$nuevoFormatoFecha= date("d-m-Y (H:i:s)", $time);
			$variable = [];
			$n = 1;
			array_push($variable, array($nombre_farmacia));
			array_push($variable, array("REPORTE DE STOCK AL " . $nuevoFormatoFecha));
			array_push($variable, array(""));
			array_push($variable, array("N", "CÓDIGO", "PRODUCTO FARMACÉUTICO O DISPOSITIVO MÉDICO", "UNIDAD","SITUACIÓN","STOCK ACTUAL"));
			foreach ($resultado as $r) {
					
						$cpm = "";
						$cpma = "";
						$meses_provicion = "";
						  
						if($r['cantidad']>0 && ($r['egresos']-$r['recetas_devueltas'])==0){
							$cpma = -1;//-1
						}else{
							if ($r['nro_mes'] == 0) {
								$cpma = -1;
							} 
							else 
							{                                        
								if(($r['egresos']-$r['recetas_devueltas'])==0){
									$cpma = 0;
								}else{
									$cpma = ($r['egresos']-$r['recetas_devueltas']) / $r['nro_mes'];
									//$cpma = round($g,0);
								}
							}
						}
						
						if(($r['egresos']-$r['recetas_devueltas'])==0){
							$meses_provicion = 0;
						}else {
							$provision = round(($r['cantidad'] / $cpma),1);
							$meses_provicion = $provision;
						}
						
					/**************************/						
					$color="";
					$situacionTemp="";
					
					if($situacion==0):
					
						if($r['cantidad']==0):
							$situac="Desabastecido";//rojo
							$situacionTemp=1;
							array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,"0"));
						else:
							if($cpma <= 0):
								$situac="Sin Rotacion";
								$situacionTemp=5;
								array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad']));
							endif;
							if($cpma>=0 && $meses_provicion >= 0 && $meses_provicion < 2):
								$situac="SubStock";
								$situacionTemp=4;
								array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad']));
							endif;
							if($meses_provicion >= 2 && $meses_provicion <=6):
								$situac="NormoStock";
								$situacionTemp=3;
								array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad']));
							endif;
							if($meses_provicion > 6):
								$situac="SobreStock";
								$situacionTemp=2;
								array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad']));
							endif;
							
						endif;
					
					elseif($situacion>0):
						
						if($r['cantidad']==0):
							$situac="Desabastecido";//rojo
							$situacionTemp=1;
							if($situacion==$situacionTemp):
								array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,"0"));
							endif;
						else:
							
							if($cpma <= 0):
								$situac="Sin Rotacion";
								$situacionTemp=5;
								if($situacion==$situacionTemp):
									array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad']));
								endif;
							endif;
							if($meses_provicion > 0 && $meses_provicion < 2):
								$situac="SubStock";
								$situacionTemp=4;
								if($situacion==$situacionTemp):
									array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad']));
								endif;
							endif;
							if($meses_provicion >= 2 && $meses_provicion <=6):
								$situac="NormoStock";
								$situacionTemp=3;
								if($situacion==$situacionTemp):
									array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad']));
								endif;
							endif;
							if($meses_provicion > 6):
								$situac="SobreStock";
								$situacionTemp=2;
								if($situacion==$situacionTemp):
									array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad']));
								endif;
							endif;
							
						endif;
						
					endif;
						
						
                }
                $sheet->setStyle(array(
                    'font' => array(
                        'name' => 'arial',
                        'size' => 12,
                        'bold' => true,
                        'text-align' => 'center'
                    )
                ));
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3');
                $sheet->setStyle(array(
                    'font' => array(
                        'name' => 'arial',
                        'size' => 12,
                        'bold' => false,
                        'text-align' => 'center'
                    )
                ));
            });
        })->export('xls');
    }

    public function imprimir_minstock_byidfarmacia($id_farmacia) {
        //====================
        $model_farma = new Farmacia;
        $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
        $nombre_farmacia = $farma->nombre;
        $date = Carbon::now();
        $fecha = $date->format('d-m-Y');
        //====================
        Excel::create('Reporte de Productos con Stock Mínimo', function($excel) use($id_farmacia, $nombre_farmacia, $fecha) {
            $excel->sheet('GENERAL', function($sheet) use($id_farmacia, $nombre_farmacia, $fecha) {
                $stocks = DB::table('stock_farmacias')
                        ->join('productos', 'stock_farmacias.codigo_producto', '=', 'productos.codigo')
                        ->join('unidades', 'productos.id_unidad', '=', 'unidades.id')
                        ->select('stock_farmacias.*', 'unidades.abreviatura')
                        ->where('stock_farmacias.id_farmacia', '=', $id_farmacia)
                        ->where('stock_farmacias.cantidad', '<=', 100)
                        ->where('stock_farmacias.cantidad', '>', 0)
                        ->orderBy('stock_farmacias.nombre_producto', 'asc')
                        ->get();               
                $time = time(); $nuevoFormatoFecha= date("d-m-Y (H:i:s)", $time);
                $variable = [];
