                array_push($variable, array(""));
                array_push($variable, array("N", "CODIGO", "NOMBRE", "UNIDAD","SITUACION","CANTIDAD"));
                foreach ($stocks as $s) {
                    array_push($variable, array($n++, $s->codigo_producto, $s->nombre_producto, $s->abreviatura,"Stock Mínimo", $s->cantidad));
