    public function imprimir_productos_proximos_vencer($id_farmacia, $meses) {
        //----------------------------------------------------------------------
        $model_farma = new Farmacia;
        $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
        $nombre_farmacia = $farma->nombre;
        //====================
        Excel::create('Reporte de Stock', function($excel) use($id_farmacia, $nombre_farmacia, $meses) {
            $excel->sheet('GENERAL', function($sheet) use($id_farmacia, $nombre_farmacia, $meses) {
				$model_kardex = new Kardexe();
                $fecha_inicio_venc = $model_kardex->getFechaServidor();
                $fecha_fin_venc = $model_kardex->getFechaServidorRestaMesesV3($meses);
                $fechaParsed = new DateTime($fecha_fin_venc);
                $mesAndAnio = $fechaParsed->format("Y-m");
                $onlyMes = $fechaParsed->format("m");
                $stocks = $model_kardex->GetKardexLotesByCodigoProductoAndIdFarmaciaAndFechasVencimientoV2("", $id_farmacia, $fecha_inicio_venc, $onlyMes=="02" ? $mesAndAnio.'-28' : $mesAndAnio.'-30');
                $time = time(); 
                $variable = [];
                $n = 1;
                array_push($variable, array($nombre_farmacia));
                array_push($variable, array("PRODUCTOS PROXIMOS A VENCER AL " . ($onlyMes=="02" ? '28-'.$mesAndAnio : '30-'.$mesAndAnio)));
                array_push($variable, array(""));
                array_push($variable, array("N", "CÓDIGO", "PRODUCTO FARMACÉUTICO O DISPOSITIVO MÉDICO", "UNIDAD", "LOTE", "R.S.", "STOCK ACTUAL", "FECHA VENCIMIENTO"));
                foreach ($stocks as $s) {
                    array_push($variable, array($n++, $s->codigo_producto, $s->prod_farmaceutico, $s->abreviatura, $s->lote, $s->registro_sanitario, $s->cantidad, $s->fecha_vencimiento));
                }
                $sheet->setStyle(array(
                    'font' => array(
                        'name' => 'arial',
                        'size' => 12,
                        'bold' => true,
                        'text-align' => 'center'
                    )
                ));
                $sheet->with($variable)->mergeCells('A2:I2')->mergeCells('A3:I3');
                $sheet->setStyle(array(
                    'font' => array(
                        'name' => 'arial',
                        'size' => 12,
                        'bold' => false,
                        'text-align' => 'center'
                    )
                ));
            });
        })->export('xls');
    }
