    public function exportar_stockFarmaciaByEstablecimiento($id_establecimiento) {
        //====================
        Excel::create('Reporte de Stock actual por centro establecimiento', function($excel) use($id_establecimiento) {
            $excel->sheet('GENERAL', function($sheet) use($id_establecimiento) {


                //====================================
                $model_kardex = new Kardexe();
                //$kardexs = $model_kardex->ShowTotalKardexByFarmacia($nombre_farmacia, $fecha_fin, 0, $idconsultorio);
                $kardexs = $model_kardex->GetStockActualByIdEstablecimientoAndIdProducto($id_establecimiento, 0);

                $resultado = array();
                foreach ($kardexs as $k) {
                    $arrayarticulo = array('id_producto' => $k->id_producto,
                        'codigo_producto' => $k->codigo_producto,
                        'nombre_producto' => $k->nombre_producto,
                        'unidad' => $k->unidad,
                        'stock_actual' => $k->stock_actual
                    );

                    $resultado[] = $arrayarticulo;
                }

                $time = time();
                $nuevoFormatoFecha = date("d-m-Y (H:i:s)", $time);
                $variable = [];
                $n = 1;

                array_push($variable, array("REPORTE DE STOCK AL " . $nuevoFormatoFecha));
                array_push($variable, array(""));
                
                $cabecera = array();
                $cabecera[] = "N°";
                $cabecera[] = "Código";
                $cabecera[] = "Productos Farmacéuticos y Dispositivos médicos";
                $cabecera[] = "Unidad";
                $ff = App\Models\Farmacia::GetFarmaciaByIdEstablecimiento($id_establecimiento);
                if (isset($ff)) {
                    foreach ($ff as $f1) {
                      //if($f1->id!=2 and $f1->id!=11){
					  if($f1->id!=1 and $f1->id!=2 and $f1->id!=4 and  $f1->id!=11 and $f1->id!=12 and $f1->id!=13 and  $f1->id!=15 and $f1->id!=24 and  $f1->id!=27 and $f1->id!=30 and $f1->id!=35 and $f1->id!=45 and  $f1->id!=46 and $f1->id!=47 and  $f1->id!=52){
                       $name=explode("del",$f1->nombre);
                       $cabecera[] = $name[0];
                      }
                    }
                }
				$cabecera[]="Total";
                array_push($variable, $cabecera);
                
                foreach ($resultado as $r) {
                    $datos = array();
                    $datos[] = $n++;
                    $datos[] = $r['codigo_producto'];
                    $datos[] = $r['nombre_producto'];
                    $datos[] = $r['unidad'];                    
                    
                    $total = $r['stock_actual'];
                    $total = str_replace('{', '', $total);
                    $total = str_replace('}', '', $total);
                    $arr = explode(',',$total);
                    $cant = count($arr);
                    $total_fila=0;
                    if (isset($ff)) {
                        foreach ($ff as $f1) {
                          //if($f1->id!=2 and $f1->id!=11){
						  if($f1->id!=1 and $f1->id!=2 and $f1->id!=4 and  $f1->id!=11 and $f1->id!=12 and $f1->id!=13 and  $f1->id!=15 and $f1->id!=24 and  $f1->id!=27 and $f1->id!=30 and $f1->id!=35 and $f1->id!=45 and  $f1->id!=46 and $f1->id!=47 and  $f1->id!=52){
                            $stock = "";
                                for ($i = 0; $i <= $cant; $i++) {
                                    if(isset($arr[$i])){
                                        $arrF = explode('-',$arr[$i]);
                                        if($arrF[0] == $f1->id){
                                            $stock = $arrF[1];
                                            $total_fila=$total_fila+$stock;
                                        }
                                    }
                                }
                                if ($stock <> ""){
                                    $datos[] = $stock;
                                } else {
                                    $datos[] = "0";
                                }
                          }
                        }
                      if ($total_fila <> ""){
                          $datos[] = $total_fila;
                      } else {
                          $datos[] = "0";
                      }
                    }
                    
                    array_push($variable, $datos);
                }
                $sheet->setStyle(array(
                    'font' => array(
                        'name' => 'arial',
                        'size' => 12,
                        'bold' => true,
                        'text-align' => 'center'
                    )
                ));
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:D3');
                $sheet->setStyle(array(
                    'font' => array(
                        'name' => 'arial',
                        'size' => 12,
                        'bold' => false,
                        'text-align' => 'center'
                    )
                ));
            });
        })->export('xls');
    }

