            $meses_provicion = "";

            if($r['cantidad']<0.076){
                $r['cantidad'] = 0;
            }
              
            if($r['cantidad']>0 && ($r['egresos']-$r['recetas_devueltas'])==0){
              $cpma = -1;//-1
            }else{
              if ($r['nro_mes'] == 0) {
                $cpma = -1;
              } 
              else 
              {                                        
                if(($r['egresos']-$r['recetas_devueltas'])==0){
                  $cpma = 0;
                }else{
                  $cpma = ($r['egresos']-$r['recetas_devueltas']) / $r['nro_mes'];
                }
              }
            }
            
            if(($r['egresos']-$r['recetas_devueltas'])==0){
              $meses_provicion = 0;
            }else {
              $provision = round(($r['cantidad'] / $cpma),1);
              $meses_provicion = $provision;
            }
            
          
          $color="";
          $situacionTemp="";
          
          if($situacion==0):
          
            if($r['cantidad']==0):
              $situac="Desabastecido";//rojo
              $situacionTemp=1;
              array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,"0",$cpma));
            else:
              if($cpma <= 0):
                $situac="Sin Rotacion";
                $situacionTemp=5;
                array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad'],$cpma));
              endif;
              if($cpma>=0 && $meses_provicion >= 0 && $meses_provicion < 2):
                $situac="SubStock";
                $situacionTemp=4;
                array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad'],$cpma));
              endif;
              if($meses_provicion >= 2 && $meses_provicion <=6):
                $situac="NormoStock";
                $situacionTemp=3;
                array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad'],$cpma));
              endif;
              if($meses_provicion > 6):
                $situac="SobreStock";
                $situacionTemp=2;
                array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad'],$cpma));
              endif;
              
            endif;
          
          elseif($situacion>0):
            
            if($r['cantidad']==0):
              $situac="Desabastecido";//rojo
              $situacionTemp=1;
              if($situacion==$situacionTemp):
                array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,"0", $cpma));
              endif;
            else:
              
              if($cpma <= 0):
                $situac="Sin Rotacion";
                $situacionTemp=5;
                if($situacion==$situacionTemp):
                  array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad'],$cpma));
                endif;
              endif;
              if($meses_provicion > 0 && $meses_provicion < 2):
                $situac="SubStock";
                $situacionTemp=4;
                if($situacion==$situacionTemp):
                  array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad'],$cpma));
                endif;
              endif;
              if($meses_provicion >= 2 && $meses_provicion <=6):
                $situac="NormoStock";
                $situacionTemp=3;
                if($situacion==$situacionTemp):
                  array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad'],$cpma));
                endif;
              endif;
              if($meses_provicion > 6):
                $situac="SobreStock";
                $situacionTemp=2;
                if($situacion==$situacionTemp):
                  array_push($variable, array($n++, $r['codigo'], $r['nombre'], $r['unidad'],$situac,$r['cantidad'],$cpma));
                endif;
              endif;
              
            endif;
            
          endif;
            
            
                }
                $sheet->setStyle(array(
                    'font' => array(
                        'name' => 'arial',
                        'size' => 12,
                        'bold' => true,
                        'text-align' => 'center'
                    )
                ));
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3');
                $sheet->setStyle(array(
                    'font' => array(
                        'name' => 'arial',
                        'size' => 12,
                        'bold' => false,
                        'text-align' => 'center'
                    )
                ));
            });
        })->export('xls');
    
    
    }


