                    Log::info("INGRESE AL ELSE");
                    if($prestacion[0]->id_tipo_atencion!=3){
                        if(intval($prestacion[0]->flag) !== 1):
                            $obj->addEntry(public_path('/tmp/pdf/sin_firma/prestacion_'.$row.'.pdf'));
                        endif;
                        Log::info("INGRESE AL IF-ELSE");
                        if($prestacion[0]->id_tipo_atencion==2){//emergencia
                            $emergencia = Emergencia::where('id', $request->id_emergencia)->where('estado', 5)->first();
                            if($emergencia!=null):
                                if ($emergencia->origen_alta!=null) {
                                    $obj->addEntry(public_path('/tmp/pdf/sin_firma/alta_emergencia_'.$request->id_emergencia.'.pdf')); 
