                            endif;
                        }
                        else{
                            
                            $gastro = Gastroenterologia::where('prestacion_id', '=', $row)->first();
                            Log::info(["gastro-2" => $gastro]);
                        
                            if(isset($gastro)){
                                for ($i=0; $i < 2; $i++) { 
                                    switch($i){
                                        case 0: if ($gastro->baja == 1) {
                                                    $obj->addEntry(public_path('/tmp/pdf/sin_firma/informe_gastro_baja_'.$gastro->id.'.pdf'));
                                                } 
                                                break;
                                        case 1: if ($gastro->alta == 1) {
                                                    $obj->addEntry(public_path('/tmp/pdf/sin_firma/informe_gastro_alta_'.$gastro->id.'.pdf'));
                                                }
                                                break;
                                    }
                                }
                            }
                        }
                    }
                    else{
                        if(intval($prestacion[0]->flag) !== 1 && $prestacion[0]->id_establecimiento != 76){
                            $obj->addEntry(public_path('/tmp/pdf/sin_firma/prestacion_'.$row.'.pdf'));
                            Log::info("*** 1 ***");
                        }
                    }
                        
                	
                }

                if(isset($receta)){
                    foreach($receta as $rowrv){
                        if (intval($rowrv->flag) !== 1) {
                            $obj->addEntry(public_path('/tmp/pdf/sin_firma/receta_'.$rowrv->id.'.pdf')); 
