                       }
                    }
                }

                 if(isset($laboratorios)){
                     foreach($laboratorios as $laboratorio) {
                       if (intval($laboratorio->flag) !== 1){
                             $obj->addEntry(public_path('/tmp/pdf/sin_firma/laboratorio_'.$laboratorio->id.'.pdf')); 
                            Log::info("*** 3 ***");
		                 }
                     }
                }

                if(isset($radiologias)){
                    foreach($radiologias as $radiologia) {
                        if (intval($radiologia->flag) !== 1){
                            $obj->addEntry(public_path('/tmp/pdf/sin_firma/radiologia_'.$radiologia->id.'.pdf')); 
                            Log::info("*** 4 ***");
                        }
                    }
                }

                if(isset($interconsultas)){
                  foreach($interconsultas as $interconsulta) {
                    if (intval($interconsulta->flag) !== 1){
                        $obj->addEntry(public_path('/tmp/pdf/sin_firma/interconsulta_'.$interconsulta->id_interconsulta.'.pdf')); 
