                //    $obj->addEntry(public_path('/tmp/pdf/sin_firma/referencia_'.$referencias->id_referencia.'.pdf')); 
		//    $opt = 6;                  
  		//  }
                //}
            }
        
        Log::info("*** 6 ***");
	    $resultado["csv"]=$csv;
