	public function genera_csv_prestacion($id_prestacion,$id_transaccion){
		
		$path = public_path('tmp/csv');

		if (!is_dir($path)) {
			mkdir($path);
		}
		
		$csv = date("YmdHis");
		
		Excel::create($csv, function($excel) use($id_prestacion,$id_transaccion){
            $excel->sheet('GENERAL', function($sheet) use($id_prestacion,$id_transaccion) {
				$model_receta = new Receta_vale;
                $variable = [];
				$this->ver_prestacion_imprimir_openpol($id_transaccion);
				array_push($variable, array(url().'/tmp/pdf/sin_firma/prestacion_openpol_'.$id_transaccion.'.pdf', url().'/upload_firma_openpol/?name=cf_prestacion_openpol_'.$id_transaccion.'.pdf&id_tipo=prestacion&id_resol='.$id_prestacion.'&id_doc='.$id_transaccion, 'cf_prestacion_openpol_'.$id_transaccion.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().'/images/escudo.jpg','1','7'));
				if($id_prestacion > 0){
					$receta = $model_receta->GetRecetasByIdPrestacion($id_prestacion);
					if(isset($receta)){
						foreach($receta as $rowrv){
							$this->ver_receta_vale($rowrv->id);
							array_push($variable, array(url().'/tmp/pdf/sin_firma/receta_'.$rowrv->id.'.pdf', url().'/upload_firma_openpol/?name=cf_receta_'.$rowrv->id.'.pdf&id_tipo=receta&id_resol='.$rowrv->id, 'cf_receta_'.$rowrv->id.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().'/images/escudo.jpg','1','7'));
						}
					}
				}
				$sheet->fromArray($variable, null, '', false, false);
            });
		})->store('csv',public_path('tmp/csv'));
		
		return response()->json(['csv'=>$csv])->header('Content-Type', 'application/json');
	}
	
