	public function validar_firma_prestacion_old($id_prestacion,$id_transaccion){
		
		$cadena = "";
		$sw = false;
		$model_receta = new \App\Models\Receta_vale;
		$model_prestacion = new \App\Models\Prestaciones;
		
		$prestacion = $model_prestacion->GetPrestacionByIdPrestacion($id_prestacion);
		$path = public_path('tmp/pdf/firmados/');
		$path .="cf_prestacion_openpol_".$id_transaccion.".pdf";
		
		if (!is_file($path)) {
			$cadena .= ",".$path;
		}else{
		
			if(isset($prestacion)){
				if($prestacion->fecha_firma == ""){
					$uploadFtp = $this->subirftp(public_path('tmp/pdf/firmados/'),"cf_prestacion_openpol_".$id_transaccion.".pdf","ftp-lfs.saludpol.gob.pe","sgf-prv","Sf7P-2019@");
					if($uploadFtp){
						$prestacion->fecha_firma = date("d-m-Y H:i:s");
						$prestacion->ruta_prestacion = date("Y/m/d")."/cf_prestacion_openpol_".$id_transaccion.".pdf";
						$prestacion->save();
						//unlink($path);
						$this->update_transaction_openpol($prestacion->ruta_prestacion,$id_transaccion);
					}
				}else{
					$this->update_transaction_openpol($prestacion->ruta_prestacion,$id_transaccion);
				}
			}else{
				$uploadFtp = $this->subirftp(public_path('tmp/pdf/firmados/'),"cf_prestacion_openpol_".$id_transaccion.".pdf","ftp-lfs.saludpol.gob.pe","sgf-prv","Sf7P-2019@");
				if($uploadFtp){
					$ruta_prestacion = date("Y/m/d")."/cf_prestacion_openpol_".$id_transaccion.".pdf";
					$this->update_transaction_openpol($ruta_prestacion,$id_transaccion);
				}
			}
			
		}
		
		$recetas = $model_receta->GetRecetasByIdPrestacion($id_prestacion);
		if(isset($recetas)){
			foreach($recetas as $rv){
				$receta = \App\Models\Receta_vale::where('id', '=', $rv->id)->first();
				$path = public_path('tmp/pdf/firmados/');
				$path .="cf_receta_".$receta->id.".pdf";
				
				if (!is_file($path)) {
					$cadena .= ",".$path;
				}else{
					
					for($i = 0; $i<5; $i++){
					
						if($receta->fecha_firma == ""){
							$uploadFtpReceta = $this->subirftp(public_path('tmp/pdf/firmados/'),"cf_receta_".$receta->id.".pdf","ftp-lfs.saludpol.gob.pe","sgf-prv","Sf7P-2019@");
							if($uploadFtpReceta){
								$receta->fecha_firma = date("d-m-Y H:i:s");
								$receta->ruta_receta = date("Y/m/d")."/cf_receta_".$receta->id.".pdf";
								$receta->save();
								//unlink($path);
								$this->update_receta_openpol($receta->ruta_receta,$receta->nro_receta);
							}
						}
					
					}
				}
			
			}
			
		}
		
		//if($cadena == "")$sw = true;
		//$sw = "ok";
		//echo $sw;
		return response()->json(['sw'=>$sw])->header('Content-Type', 'application/json');
		
	}
	
