  public function ver_prestacion_receta_sigesapol($ano,$mes,$dia,$nro_receta) {
    if($ano==2023 && $mes>5):
        return Response::make(file_get_contents(public_path("tmp/pdf/firmados/${nro_receta}.pdf")), 200, [
            'Content-Type' => 'application/pdf',
            'Content-Disposition' => "inline; filename=${nro_receta}.pdf"
        ]);
      else:
        if($ano==2023 && $mes<5):
            return redirect('http://pdfsigesapol.dirsapolpnp.gob.pe:8084/'.$ano.'/'.$mes.'/'.$dia.'/'.$nro_receta.'.pdf');
        else:
            return Response::make(file_get_contents(public_path("tmp/pdf/firmados/${nro_receta}.pdf")), 200, [
                'Content-Type' => 'application/pdf',
                'Content-Disposition' => "inline; filename=${nro_receta}.pdf"
            ]);

        endif;
    endif;

  }

  private function documentoAseguradoBloqueado($data) {
    $tipo = isset($data[1]) ? $data[1] : null;
    $auxiliar_data_2 = isset($data[2]) ? $data[2] : null;
    $auxiliar_data_3 = isset($data[3]) ? $data[3] : null;
    $id = 0;

    switch ($tipo) {

        case 'prestacion':
