          return Response::make(file_get_contents(public_path("tmp/pdf/firmados/${nro_receta}.pdf")), 200, [
              'Content-Type' => 'application/pdf',
              'Content-Disposition' => "inline; filename=${nro_receta}.pdf"
          ]);
