                //dd($procradiologia);
                $camas = $model_emergencia->GetObtenerCama($hospitalizacion->id_cama_estado);
                if($radiologia->id_evaluacion!=0):
                    $evaluacion = \App\Models\Evaluacione::where('id', $radiologia->id_evaluacion)->first();
                    $medico = null;
                    $medico = $model_medico->GetMostrarMedicoById($evaluacion->id_medico);

                    if(count($medico)>0):
                       $prestacion->id_medico=$medico->id;
                        $prestacion->medico_nombre=$medico->nombre;
                        $prestacion->medico_paterno=$medico->paterno;
                        $prestacion->medico_materno=$medico->materno;
                        $prestacion->dni=$medico->dni;
                        $prestacion->colegiatura=$medico->colegiatura;
                        $prestacion->profesion=$medico->id;
                        $prestacion->rne=$medico->rne;
                        //$prestacion->especializacion=$medico->id;
                    endif;
                endif;
                $lista_rad = $model_radiologia->getVerRadCheckListPrestacionProcedimiento($prestacion->nivel_estable, $prestacion->id_tipo_atencion, $id_prestacion, $id_radiologia, $prestacion->id_consultorio);
                //($lista_rad);
                Log::info("lista_rad", ["lista_rad" => $lista_rad]);
                break;
        }

        $diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacionEvaluacion($id_prestacion, $radiologia->id_evaluacion);
        //$diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacion($id_prestacion);
        
        

        $carpeta = date("Y")."/".date("m")."/".date("d");
        $procradiologia = $model_prestacion->GetPrestacionRadiologia($id_prestacion,$id_radiologia);
        
        $prestacion_procedimiento = $model_radiologia->obtenerPrestacionProcedimientoPorIdPrestacionPorRadiologia($id_prestacion, $id_radiologia);
        $total_examenes_prestacion_procedimientos = count($prestacion_procedimiento);
        $total_categoria = $model_radiologia->getNumCategoria($prestacion->nivel_estable, $prestacion->id_tipo_atencion, $prestacion->id_consultorio);
        Log::info("total_categoria", ["total_categoria" => $total_categoria]);
        $num_categoria = $total_categoria->total;
        Log::info("count(lista_rad)", ["count(lista_rad)" => count($lista_rad),"num_categoria" => $num_categoria]);
        $total_examenes = count($lista_rad) + $num_categoria;
        $filas_por_columnas = "";
        $consultorio = $model_consultorio->GetNombreById($prestacion->id_consultorio);
        $num_columna=$consultorio->reporte_columnas_rad;
        $valorFN=($total_examenes / $num_columna);
        Log::info("filas_por_columnas", ["filas_por_columnas con decimales" => $valorFN]);
        Log::info("ceil", ["total_examenes" => $total_examenes, "num_columna" => $num_columna]);
        if($num_columna==0 ||$num_columna == null || $num_columna ==""){
          return response()->json(["Object"=> "Error","message"=> "No hay columnas configuradas para este servicio. Por favor agrega Columnas"]);
        }
        $filas_por_columnas = ceil($total_examenes / $num_columna);
        Log::info("filas_por_columnas", ["filas_por_columnas" => $total_examenes, "num_columna" => $num_columna]);
        $filas_por_columnas = intval($filas_por_columnas);
        $model_establecimiento = new App\Models\Establecimiento;
        $establecimiento = $model_establecimiento->GetById( auth()->user()->id_establecimiento );
        
        $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_radiologia_".$id_radiologia.".pdf";
        $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_radiologia_".$id_radiologia.".pdf");
        
            //return view('pdf.firmar_evolucion_hospitalizacion',compact('evolucion','diagnosticos','procedimientos','recetas','receta_productos','ordenes_laboratorio','orden_lab_examenes','ordenes_imagenologia','orden_img_examenes','interconsultas','codigo_qr','url_descarga','id_evolucion'));
            //return view('pdf.rad_reporte',compact('prestacion','diagnostico','radiologia','procradiologia','codigo_qr','url_descarga','titulo_reporte','adicional','lista_rad','total_examenes','filas_por_columnas','consultorio','establecimiento','total_examenes_prestacion_procedimientos','camas'));
        
            
            $pdf = \PDF::loadView('pdf.rad_reporte3',compact('prestacion','diagnostico','radiologia','procradiologia','codigo_qr','url_descarga','titulo_reporte','adicional','lista_rad','total_examenes','filas_por_columnas','consultorio','establecimiento','total_examenes_prestacion_procedimientos','camas'));
        
        $pdf->setPaper('A4', 'landscape');
        $pdf->getDomPDF()->set_option("enable_php", true);
        return $pdf->stream('ver_radiologia.pdf');
        
        
    }

    public function valida_ruta_archivo_tmp(){
        $path = public_path('tmp/pdf');
		if (!is_dir($path)) {
			mkdir($path);
		}
		
		$path = public_path('tmp/pdf/sin_firma/');
		if (!is_dir($path)) {
			mkdir($path);
		}

        return $path;
    }
	
	public function ver_prestacion_imprimir($id_prestacion) { 
		
		$path = public_path('tmp/pdf');
