                $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_prestacion_".$id_prestacion.".pdf");

                $pdf = \PDF::loadView('pdf.firmar_prestacion',compact('emergencia_triaje', 'natis', 'farmacia','eventosMarcados','prestacion','diagnostico','procedimiento','medicamentos','codigo_qr','url_descarga','cups_pnp','informe_html'));
