	public function upload_firma_(Request $request){
		
		$file = $request->getContent();
		
		$path = public_path('tmp/pdf/firmados/');
		if (!is_dir($path)) {
			mkdir($path);
		}
		
		$path_file = $path.$request->name;
		file_put_contents($path_file, $file);
		return "ok";
	}
	
	public function actualizar_prestacion(Request $request){
    
    
    $tipo = $request->id_tipo;
    $id = intval($request->id_resol);
    
    if($tipo == "prestacion"){
      $model_prestacion = new \App\Models\Prestaciones;
      $prestacion = $model_prestacion->GetPrestacionByIdPrestacion($id);
      for($i = 0; $i<5; $i++){
        if($prestacion->fecha_firma == ""){
            $prestacion->fecha_firma = date("d-m-Y H:i:s");
            $prestacion->ruta_prestacion = date("Y/m/d")."/cf_prestacion_".$id.".pdf";
            $prestacion->flag = 1;
            $prestacion->save();
        
        }
      }
        $gastro = Gastroenterologia::where('prestacion_id', '=', $id)->first();
        if(isset($gastro)){
            for ($i=0; $i < 2; $i++) { 
                switch($i){
                    case 0: if($gastro->baja == 1){
                                $gastro->baja_fecha_firma = date("d-m-Y H:i:s");
                                $gastro->baja_ruta_firma = date("Y/m/d")."/cf_informe_gastro_baja_".$gastro->id.".pdf";
                                $gastro->save();
                            
                            } 
                            break;
                    case 1: if($gastro->alta== 1){
                                $gastro->alta_fecha_firma = date("d-m-Y H:i:s");
                                $gastro->alta_ruta_firma = date("Y/m/d")."/cf_informe_gastro_alta_".$gastro->id.".pdf";
                                $gastro->save();
                            
                            } 
                            break;
                }
            }
        }
    }
    
    if($tipo == "receta"){
        $recetas = \App\Models\Receta_vale::where('id_prestacion', $id)->get();
        foreach($recetas as $receta){
            if($receta->fecha_firma == ""){
                $receta->fecha_firma = date("d-m-Y H:i:s");
                $receta->ruta_receta = date("Y/m/d")."/cf_receta_".$receta->id.".pdf";
                $receta->flag = 1;
                $receta->save();
            }
        }
    }

    if($tipo == "laboratorio"){
        $laboratorios = \App\Models\Laboratorio::where('id_prestacion', $id)->get();
        foreach($laboratorios as $laboratorio){
            if($laboratorio->fecha_firma == ""){
                $laboratorio->fecha_firma = date("d-m-Y H:i:s");
                $laboratorio->ruta_laboratorio = date("Y/m/d")."/cf_laboratorio_".$laboratorio->id.".pdf";
                $laboratorio->flag = 1;
                $laboratorio->save();
            }
        }
    }

    if($tipo == "radiologia"){
        $radiologias = \App\Models\Radiologia::where('id_prestacion', $id)->get();
        foreach($radiologias as $radiologia){
            if($radiologia->fecha_firma == ""){
                $radiologia->fecha_firma = date("d-m-Y H:i:s");
                $radiologia->ruta_radiologia = date("Y/m/d")."/cf_radiologia_".$radiologia->id.".pdf";
                $radiologia->flag = 1;
                $radiologia->save();
            }
        }
    }

    if($tipo == "interconsulta"){
        $interconsultas = \App\Models\Interconsulta::where('id_prestacion', $id)->get();
        foreach($interconsultas as $interconsulta){
            if($interconsulta->fecha_firma_interconsulta == ""){
                $interconsulta->fecha_firma_interconsulta = date("d-m-Y H:i:s");
                $interconsulta->ruta_interconsulta = date("Y/m/d")."/cf_interconsulta_".$interconsulta->id.".pdf";
                $interconsulta->flag = 1;
                $interconsulta->save();
            }
        }
    }

    if($tipo == "referencia"){
        $referencias = \App\Models\Referencia::where('id_prestacion', $id)->get();
        foreach($referencias as $referencia){
            if($referencia->fecha_firma_referencia == ""){
                $referencia->fecha_firma_referencia = date("d-m-Y H:i:s");
                $referencia->ruta_referencia = date("Y/m/d")."/cf_referencia_".$referencia->id.".pdf";
                $referencia->flag = 1;
                $referencia->save();
            }
        }
    }
  
    if($tipo == "emergencia_triaje"){
        $emergencia_triaje = \App\Models\Emergencia::where('id', $id)->get();
        foreach($emergencia_triaje as $triaje){
            if($triaje->fecha_firma_triaje == ""){
                $triaje->fecha_firma_triaje = date("d-m-Y H:i:s");
                $triaje->ruta_triaje = date("Y/m/d")."/cf_triaje_emergencia_".$id.".pdf";
                $triaje->flag_triaje = 1;
                $triaje->save();
            }
        }
    }
    if($tipo == "alta_medica" || $tipo == "alta_medica_aten" ){ //alta medica emergencia
            if($tipo == "alta_medica"):
                $alta_pac = \App\Models\Emergencia::where('id', $id)->get();
            else:
                $model_prestacion = new \App\Models\Prestaciones;
                $prestacion = $model_prestacion->GetPrestacionByIdPrestacion($id);
                $alta_pac = \App\Models\Emergencia::where('id', $prestacion->id_ext)->get();
            endif;
            
            foreach($alta_pac as $alta){
                if($alta->fecha_firma_egreso == ""){
                    $alta->fecha_firma_egreso = date("d-m-Y H:i:s");
                    $alta->ruta_egreso = date("Y/m/d")."/cf_alta_emergencia_".$alta->id.".pdf";
                    $alta->flag_firma_egreso = 1;
                    $alta->save();
                }
                if($alta->id_tipo_egres_med==2){
                    $alta->ruta_indicaciones = date("Y/m/d")."/cf_emergencia_indicaciones_alta_".$alta->id.".pdf";
                    $alta->save();

                    if($tipo == "alta_medica"):
                        $orden = HospitalizacionOrden::where('id_ext', $id)->where('id_estado_reg', '=', 1)->first();
                    else:
                        $orden = HospitalizacionOrden::where('id_ext', $prestacion->id_ext)->where('id_estado_reg', '=', 1)->first();
                    endif;
                    
                    $orden->fecha_firma = date("d-m-Y H:i:s");
                    $orden->ruta_orden = date("Y/m/d")."/cf_emergencia_indicaciones_alta_".$alta->id.".pdf";
                    $orden->flag_firma = 1;
                    $orden->save();
                }
                if($alta->id_tipo_egres_med==4){
                    $alta->ruta_epicrisis = date("Y/m/d")."/cf_emergencia_epicrisis_".$alta->id.".pdf";
                    $alta->save();
                }
            }
        }

    if($tipo == "hospitalizacion"){
        $model_prestacion = new \App\Models\Prestaciones;
        $prestacion = $model_prestacion->GetPrestacionByIdPrestacion($id);
        $cq_anestesia = DB::table('anestesia_quirurgicas')
                        ->where('anestesia_quirurgicas.id_prestacion','=',$id)
                        ->select('anestesia_quirurgicas.*')
                        ->first();
        
        if($prestacion->fecha_firma == ""){
            $prestacion->fecha_firma = date("d-m-Y H:i:s");
            $prestacion->ruta_prestacion = date("Y/m/d")."/cf_hospitalizacion_atencion_".$id.".pdf";
            $prestacion->flag = 1;
            $prestacion->save();
        }
        if (is_null($cq_anestesia)) {
            $obj_hoja = \App\Models\HospitalizacionAtencione::where('id', '=', $prestacion->id_ext)->first();
            if(isset($obj_hoja)){
                if($obj_hoja->fecha_firma_terapeutica == ""){
                    $obj_hoja->fecha_firma_terapeutica = date("d-m-Y H:i:s");
                    $obj_hoja->ruta_terapeutica = date("Y/m/d")."/cf_hoja_terapeutica_".$id.".pdf";
                    $obj_hoja->flag_terapeutica = 1;
                    $obj_hoja->save();
                }
            }
        }
    }
    
    if($tipo == "alta_hospitalizacion"){
        $alta_pac = \App\Models\Hospitalizacione::where('id', $id)->get();
        foreach($alta_pac as $alta){
            if($alta->fecha_firma_alta_medica == ""){
                $alta->fecha_firma_alta_medica = date("d-m-Y H:i:s");
                $alta->ruta_alta_medica = date("Y/m/d")."/cf_alta-hospitalizacion_".$alta->id.".pdf";
                $alta->ruta_epicrisis = date("Y/m/d")."/cf_hospitalizacion-epicrisis_".$alta->id.".pdf";
                $alta->ruta_papeleta_egreso = date("Y/m/d")."/cf_hospitalizacion-papeleta-egreso_".$alta->id.".pdf";
                $alta->flag_alta_medica = 1;
                $alta->save();
            }
        }
    }

    return "ok";
  }


    public function actualizar_monitoreo(Request $request) 
    {
        $model_monitoreo = new Monitoreo();
        $detallesMonitoreo = $model_monitoreo->detallarMonitoreo($request->id_monitoreo, $request->fecha_hora);
        $dateTime = new DateTime($request->fecha_hora);
        $timestamp = $dateTime->getTimestamp();
        $estado = false;
        foreach($detallesMonitoreo as $key => $detalle) {
            if($detalle->flag_firma == "" || $detalle->flag_firma == "0" || $detalle->flag_firma == null) {
                $estado = true;
                $monitoreo_detalle_para_actualizar = Monitoreo_detalles::find($detalle->id);
                $monitoreo_detalle_para_actualizar->fecha_firma = date("d-m-Y H:i:s");
                $monitoreo_detalle_para_actualizar->ruta_firma = date("Y/m/d")."/cf_monitoreo_hxt_" . $request->id_monitoreo . "_" . $timestamp . ".pdf";
                $monitoreo_detalle_para_actualizar->flag_firma = 1;
                $monitoreo_detalle_para_actualizar->save();
            }
        }
        return response()->json([$request->id_monitoreo, $request->fecha_hora, $detallesMonitoreo, $estado]);
    }

