    public function sinTokensAdmision(Request $request){
    
        $cadena = "";
        $sw = false;
        $model_emergencia = new \App\Models\Emergencia;
        
        foreach($request->mov as $row):
          
          if($request->proviene_formulario==1){
            $admision = $model_emergencia->GetEmergenciaById($row);
            if($admision->fecha_firma_admision == ""){
              $admision->fecha_firma_admision = date("d-m-Y H:i:s");
              $admision->fecha_registro_admision = date("d-m-Y H:i:s");
              $admision->ruta_admision = date("Y/m/d")."/cf_admision_emergencia_".$row.".pdf";
              $admision->flag_admision = 2; //sintoken
              $admision->save();
            }
          }
        endforeach;
        if($cadena == "")$sw = true;
        echo $sw;
    }

    public function sinTokensEgresoEmergencia(Request $request){
    
