        $fecha_firma = date("Y/m/d");

        $model_receta = new \App\Models\Receta_vale;
        $id_prestacion = intval($request->id_prestacion);
        $recetas_alta = $model_receta->GetDatosRecetasAltasByIdPrestacion($id_prestacion);

        foreach ($request->mov as $row):
          
            $emergencia = Emergencia::find($row);
            if (is_null($emergencia->fecha_firma_egreso)):
                $emergencia->fecha_firma_egreso = $fecha_hora_firma;
                $emergencia->ruta_egreso = $fecha_firma."/cf_alta_emergencia_" . $row . ".pdf";
