                if ($emergencia->id_tipo_egres_med == 2): // Hospitalizacion
                    $emergencia->ruta_indicaciones = $fecha_firma."/cf_emergencia_indicaciones_alta_" . $row . ".pdf";
                    if (!$emergencia->save()):
                        // 
                    endif;

                    $orden = HospitalizacionOrden::where('id_ext', $row)->where('id_estado_reg', '=', 1)->first();
                    if ($orden):
                        $orden->fecha_firma = $fecha_hora_firma;
                        $orden->ruta_orden = $fecha_firma."/cf_emergencia_indicaciones_alta_" . $row . ".pdf";
                        $orden->flag_firma = 2;
                        if (!$orden->save()):
                            // 
                        endif;
                    endif;

                elseif ($emergencia->id_tipo_egres_med == 4): // Fallecido
                    $emergencia->ruta_epicrisis = $fecha_firma."/cf_emergencia_epicrisis_" . $row . ".pdf";
                    if (!$emergencia->save()) {
                        // 
                    }
                endif;
            endif;
        endforeach;

        if (!empty($recetas_alta)):
            foreach ($recetas_alta as $rv):
                $recetas_alta = \App\Models\Receta_vale::where('id', $rv->id)->first();
                if ($recetas_alta && empty($receta->fecha_firma)):
                    $recetas_alta->fecha_firma = date("d-m-Y H:i:s");
                    $recetas_alta->ruta_receta = date("Y/m/d")."/cf_receta_".$recetas_alta->id.".pdf";
                    $recetas_alta->flag = 2;
                    $recetas_alta->save();
                endif;
            endforeach;
        endif;

        if ($cadena == "") $sw = true;
        echo $sw;
    }

