	public function subirFtpReceta(){
		
		$recetas = DB::table('receta_vales')
		->join('prestaciones', 'receta_vales.id_prestacion', '=', 'prestaciones.id')
		->select('receta_vales.id', DB::raw("to_char(prestaciones.fecha_firma::date,'yyyy/mm/dd') fecha_firma")/*, 'productos.nombre'*/)
		->orderBy('receta_vales.id', 'desc')
		->WhereNull('receta_vales.ruta_receta')
		->where('receta_vales.estado','<>',0)
		->where('prestaciones.fecha_firma','<>','')
		->get();
		
		foreach ($recetas as $rv) {
			$path = public_path('tmp/pdf/firmados/');
			$path .="cf_receta_".$rv->id.".pdf";						
			if (is_file($path)) {
				$receta = \App\Models\Receta_vale::where('id', '=', $rv->id)->first();
				$uploadFtpReceta = $this->subirftpnew(public_path('tmp/pdf/firmados/'),"cf_receta_".$receta->id.".pdf","ftp-lfs.saludpol.gob.pe","sgf-prv","Sf7P-2019@",$rv->fecha_firma);
				if($uploadFtpReceta){
					$receta->fecha_firma = date("d-m-Y", strtotime($rv->fecha_firma));
					$receta->ruta_receta = $rv->fecha_firma."/cf_receta_".$receta->id.".pdf";
					$receta->save();
					//unlink($path);
				}
			}
			
		}
		
	}
	
