                                $meses_provision = $r['cantidad'];
                            }
                        }
                        
                        /************************* */
                        $situac = "";
                        $situacionTemp = "";
                        if ($r['cantidad'] <= 0):
                            $situac = "Desabastecido";
                            $situacionTemp = 1;
                        else:
                            if ($cpma <= 0):
                                $situac = "Sin Rotacion";
                                $situacionTemp = 5;
                            endif;
                            if ($meses_provision > 0 && $meses_provision < 2):
                                $situac = "SubStock";
                                $situacionTemp = 4;
                            endif;
                            if ($meses_provision >= 2 && $meses_provision <= 6):
                                $situac = "NormoStock";
                                $situacionTemp = 3;
                            endif;
                            if ($meses_provision > 6):
                                $situac = "SobreStock";
                                $situacionTemp = 2;
                            endif;
                        endif;

                        if (($r['egresos'] - $r['recetas_devueltas']) == 0) {
                            $cpma=0;
                        } else {
                            $f = ($r['egresos'] - $r['recetas_devueltas']) / $r['nro_mes'];
                            $cpma= round($f, 0);
                        }
                    
                    if($cpma==0)
                      $cpma='0';
                    
                    if($r['movimiento'][1]['total']==0&&$r['movimiento'][8]['total']==0):                      
                      $total_ingreso='0';$valor_ingreso='0';
                    else:
                      $total_ingreso=$r['movimiento'][1]['total']+$r['movimiento'][8]['total'];
                      $valor_ingreso=$r['precio']*($r['movimiento'][1]['total']+$r['movimiento'][8]['total']);
                    endif;
                    
                    if($r['movimiento'][1]['total']==0)
                        $ingreso_regular='0';
                    else
                      $ingreso_regular=$r['movimiento'][1]['total'];

                    if($r['movimiento'][8]['total']==0)
                        $ingreso_transferencia='0';
                    else
                        $ingreso_transferencia=$r['movimiento'][8]['total'];

                    if($r['movimiento'][3]['total']-$r['movimiento'][6]['total']==0){//consumo
                      $consumo='0';
                      if($r['movimiento'][7]['total']==0){ //transferencia
                        $transferencia='0';
                        $total_salida='0';
                      }
                      else
                      {
                        $transferencia=$r['movimiento'][7]['total'];
                        $total_salida=$transferencia;
                      }
                    }
                    else
                    { $consumo=$r['movimiento'][3]['total']-$r['movimiento'][6]['total'];
                      if($r['movimiento'][7]['total']==0) //transferencia
                      { $transferencia='0';
                        $total_salida=$consumo;
                      }
                      else
                      {
                       $transferencia=$r['movimiento'][7]['total'];
                       $total_salida=$r['movimiento'][7]['total']+$consumo;  
                      }
                    }

                    if($meses_provision==0)
                      $meses_provision='0';

                    $precio= $r['precio'];

                    if($precio==0)
                      $total_valor='0';
                    else
                    {
                      if($total_salida=='0')
                        $total_valor='0';
                      else
                        $total_valor=$precio*$total_salida;
                    }  

                    if ($r['cantidad']==0)
                      $cant='0';
                    else
                      $cant=$r['cantidad'];

                    array_push($variable, array($m++,
                      $r['codigo'],
                      $r['nombre'], 
                      $r['precio'] ,
                      $cpma,
                      $r['movimiento'][0]['total'], //stock inicial
                      $ingreso_regular, //ingreso regular
                      $ingreso_transferencia, //ingreso transferencia
                      $total_ingreso,                       
                      $consumo,
                      $transferencia, //transferencia
                      $total_salida,
                      $cant,  
                      $r['fecha'], 
                      $meses_provision, 
                      $situac));
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        });
        // Devuelve la URL del archivo Excel generado
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

