	public function exportar_productos($id_tipo) {
        $n = 0;
        $model = new Producto;
        
        if($id_tipo==0)        
          $productos = $model->ShowAllMantenimiento();
        else
          $productos = $model->ShowByTipo($id_tipo);        
    
        Excel::create('PETITORIO_DIRSAPOL', function($excel) use(&$n,&$productos,$id_tipo) {
          $excel->sheet('GENERAL', function($sheet) use(&$n,&$productos,$id_tipo) {                
      
            $sheet->row(1, array(
                'PETITORIO DIRSAPOL PNP'
            ));
            $sheet->row(2, array(
                'codigo', 'codigo siga', 'nombre','abreviatura', 'tipo_producto', 'nivel', 'petitorio', 'covid'
            ));

            $n = 3;
            foreach ($productos as $p) {
              if(trim($p->codigo) != ""):
                if($id_tipo==0){
                  $sheet->row($n, array(              
                    $p->codigo,$p->codigo_siga,$p->nombre,$p->abreviatura, $p->tipo_producto, $p->nivel, $p->petitorio, $p->covid
                  ));
                }
                else
                {
                  $sheet->row($n, array(              
                    $p->codigo,$p->codigo_siga,$p->nombre,$p->abreviatura, $p->tipo, $p->nivel, $p->petitorio , $p->covid
                  ));
                }
                $n++;
              endif;
            }
                
          });
        })->export('xlsx');
    }
	
