                    $n = 1; $cantidad_total=0; $total=0;
                    foreach ($ingresos_compra as $r) {

                      if($r->pc!=0)
                        $descripcion =  $r->nombre_producto.' ('.$r->cantidad.' X '.$r->presentacion_comercial.') ';
                      else
                        $descripcion =  $r->nombre_producto;
                      
