                      $total += $subtotal;

                      $originalDate2 = $r->fecha_vencimiento;
                      $fechav = date("d-m-Y", strtotime($originalDate2));

                      
                      array_push($variable, array($n++,$r->numero, $fecha,$r->num_orden,$r->proveedor,$r->cod_producto,$descripcion,$r->lote,$r->registro_sanitario,$fechav,$subcantidadtotal,$r->precio_promedio,$subtotal));
                                
                    }

                    array_push($variable, array(""));
                    array_push($variable, array(""));  
                    array_push($variable, array("N", "Numero","F. Internamiento", "Concepto","Origen","Codigo","Producto","Lote","R.Sanitario", "F. Vencimiento","Cantidad","Precio","Total"));

                    $n = 1; $cantidad_total2=0; $total2=0;$subtotal2=0;$canttotal=0;
                    foreach ($ingresos_varios as $r) {

                      if($r->pc!=0)
                          $descripcion =  $r->nombre_producto.' ('.$r->cantidad.' X '.$r->presentacion_comercial.') ';
                      else
                          $descripcion =  $r->nombre_producto;
                      
                      $originalDate1 = $r->fecha_entrada;
                      $fecha = date("d-m-Y", strtotime($originalDate1));
                      //$originalDate2 = $r->fecha_orden;
                      //$fechao = date("d-m-Y", strtotime($originalDate2));  

                      $subtotal2=$r->cantidad*$r->p_unitario*$r->presentacion_comercial; 
                      $total2 += $subtotal2;
                      $canttotal+=$r->cantidad*$r->presentacion_comercial;

                      $originalDate2 = $r->fecha_vencimiento;
                      $fechav = date("d-m-Y", strtotime($originalDate2));

                      if($r->tipo_concepto==11){
                          $lugar=$r->lugar_origen_ipress;
                      }
                      else
                      {   if($r->tipo_concepto==7 || $r->tipo_concepto==8){
                              $lugar=$r->lugar_origen_prov;
                          }
                          else
                          {
                              $lugar=$r->lugar_origen_dep;
                          }
                      }
                      
                      array_push($variable, array($n++, $r->numero,$fecha,$r->conceptos,$lugar,$r->cod_producto,$descripcion,$r->lote,$r->registro_sanitario,$fechav,$r->cantidad*$r->presentacion_comercial,$r->p_unitario,$subtotal2));
                                
                    }

                    array_push($variable, array(""));
                    array_push($variable, array(""));  
                    array_push($variable, array("N", "Numero Pecosa","F. Pecosa","F. Atencion","Destino","Codigo","Producto","Lote","R.Sanitario","F. Vencimiento", "Cantidad Entregada","Precio Unit","Total"));

                    
                    $n = 1; $cantidad_totals3=0; $totals3=0; $subtotals3=0;$subcantidadtotals3=0;
                    foreach ($ordenes_salidas as $r) {

                      if($r->pc!=0)
                          $descripcion =  $r->nombre_producto.' ('.$r->cantidad.' X '.$r->presentacion_comercial.') ';
                      else
                          $descripcion =  $r->nombre_producto;
                      
                      $originalDate1 = $r->fecha_salida;
                      $fecha = date("d-m-Y", strtotime($originalDate1));
                      
                      $subtotal2=$r->cantidad*$r->p_unitario*$r->presentacion_comercial; 
                      $total2 += $subtotal2;
                      $canttotal+=$r->cantidad*$r->presentacion_comercial;

                      if($r->lugar_destino_dependencia)
                        $destino= $r->lugar_destino_dependencia;
                      if($r->lugar_destino_farmacia){
                        if($r->lugar_destino_farmacia!=0)
                        $destino= $r->lugar_destino_farmacia;
                      }
                      if($r->lugar_destino_establecimiento)
                        $destino= $r->lugar_destino_establecimiento;  

                      $originalDate2 = $r->fecha_vencimiento;
                      $fechav = date("d-m-Y", strtotime($originalDate2));

                      $subcantidadtotals3=$r->cantidad*$r->presentacion_comercial;
                      $cantidad_totals3 += $subcantidadtotals3;

                      $subtotals3=$r->p_unitario*$r->cantidad*$r->presentacion_comercial; 
                      $totals3 += $subtotals3;

                      $muestra=number_format($subtotals3, 6, '.', '');
                      
                      array_push($variable, array($n++, $r->nro_acta,$fecha,$fecha,$destino,$r->cod_producto,$descripcion,$r->registro_sanitario,$r->lote,$fechav, $subcantidadtotals3,$r->p_unitario, $muestra));
                                
                    }

                    $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
                });
            })->export('xlsx');

        }
        else
        {
            Session::flash('flash_message', 'Esta opción es solo para almacén San Borja');
            return redirect('/movimiento_producto/');
        }

        
    }

