    public function exportar_total_producto_establecimiento() {
  
        Excel::create('Exportar Productos a Nivel Nacional', function($excel) {
            $excel->sheet('GENERAL', function($sheet) {
                
                //------------------------------------------------------
                $model_productos = new Producto();
                $result = $model_productos->total_producto_establecimiento();
                $variable = [];
                $n = 0;
                foreach ($result as $c) {
                    $n++;
                }
                array_push($variable, array(" Reporte de Productos a nivel Nacional Por Establecimientos "));
                array_push($variable, array(""));
                array_push($variable, array("N", "Establecimiento","Farmacia","Tipo de Producto","C&oacute;digo","Producto","Unidad","Stock Actual","Covid","Petitorio"));
                
                $m = 1;
                
                foreach ($result as $c) {
                    if( $c->establecimiento == 'DIRSAPOL' ):
                          $establecimiento= 'DROGUERIA UNIDAD EJECUTORA 020: SANIDAD DE LA PNP';
                    else:
                          $establecimiento= $c->establecimiento;
                    endif;
                    
                    if($c->stock_actual>0):
                      array_push($variable, array($m++, $establecimiento,$c->farmacias, $c->tipo_producto, $c->codigo_producto, $c->nombre_producto, $c->unidad, $c->stock_actual, $c->covid,$c->petitorio));
                    else:
                      array_push($variable, array($m++, $establecimiento,$c->farmacias, $c->tipo_producto, $c->codigo_producto, $c->nombre_producto, $c->unidad, '0', $c->covid,$c->petitorio));
                    endif;
                }
                $sheet->with($variable)->mergeCells('A2:F2')->mergeCells('A3:F3');
            });
        })->export('xlsx');
    }
	
	
