    public function exportar_ingresos_farmacia($fecha_inicio, $fecha_fin, $id_farmacia, $num_doc , $reg_sanitario, $lote, $id_tipo_producto,$id_producto) {
  
        Excel::create('Exportar Reportes de Internamiento de Compra', function($excel) use($fecha_inicio, $fecha_fin, $id_farmacia, $num_doc , $reg_sanitario, $lote, $id_tipo_producto,$id_producto) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_farmacia, $num_doc , $reg_sanitario, $lote, $id_tipo_producto,$id_producto) {
        
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                //----------------------------------------------------                     
                $model_receta = new \App\Models\Receta_vale;
                if ($id_tipo_producto == 0) $id_tipo_producto="";
                if ($id_producto == 0) $id_producto="";
                
                $fechaDesde = date("Y-m-d", strtotime($fecha_inicio));
                $fechaHasta = date("Y-m-d", strtotime($fecha_fin));

                $model_guias = new Guia_entrada();        
                $ordenes_compra = $model_guias->ShowAllIngresosFarmacia($id_farmacia, $fechaDesde, $fechaHasta, $num_doc,$reg_sanitario,$lote,$id_producto, $id_tipo_producto);

                $variable = [];
                $n = 0;
                foreach ($ordenes_compra as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Internamiento del " . $nombre_farmacia));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                array_push($variable, array(""));               
                
                array_push($variable, array("N", "Origen","Fecha","Num Documento", "Tipo Movimiento","Tipo Producto", "Codigo","Producto","R.S.","Lote","F. Venc", "P.U.", "Cantidad","Responsable"));

                $m = 1;
                foreach ($ordenes_compra as $c) {
                  $originalDate1 = $c->fecha_movimiento;
                  $fechaE = date("d-m-Y", strtotime($originalDate1));
                  $originalDate2 = $c->fecha_vencimiento;
                  $fechaV = date("d-m-Y", strtotime($originalDate2));                  
                  
                  if($c->pc!=0)
                    $descripcion =  $c->nombre_producto.' ('.$c->cantidad.' X '.$c->presentacion_comercial.') ';
                  else
                    $descripcion =  $c->nombre_producto;

                  if($c->id_tipo_movimiento==9){
                      $lugar=$c->nombre_farmacia;
                  }
                  else
                  {   
                    $lugar= $c->nombre_farmacia;
                  }

                  array_push($variable, array($m++, $lugar,$fechaE,$c->numero_movimiento, $c->tipo_movimiento, $c->tipo_producto, $c->codigo_producto, $descripcion,$c->registro_sanitario,$c->lote,$fechaV,$c->p_unitario, $c->cantidad*$c->presentacion_comercial, $c->paterno_usuario." ".$c->materno_usuario.", ".$c->nombre_usuario));
                            
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }

