    public function exportar_reporte_productividad_medico($fecha_ini, $fecha_fin) {
      
      Excel::create('Exportar Reporte de Productividad Medico', function($excel) use($fecha_ini, $fecha_fin) {
          $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin) {
              
              $model_est = new Establecimiento;
              $id_establecimiento = Auth::user()->id_establecimiento;
              $model_receta = new Receta_vale();
              $data = $model_receta->productividad_medico($id_establecimiento,$fecha_ini,$fecha_fin);

              $variable = [];
              $n = 1;
              
              
              $establecimiento = $model_est->GetById(Auth::user()->id_establecimiento);
              $nombre_establecimiento = $establecimiento[0]->nombre;

              array_push($variable, array($nombre_establecimiento));
              array_push($variable, array("Reporte de Productividad Medico"));
              array_push($variable, array("Fecha Desde: " . $fecha_ini));
              array_push($variable, array("Fecha Hasta: " . $fecha_fin));
              //array_push($variable, array("Total: " . $nro_atendidas . " atenciones"));
              //array_push($variable, array("Usuario : " . $nombre_usuario ));
              array_push($variable, array(""));
              array_push($variable, array("N","CONSULTORIO", "DNI","MEDICO","CITAS ATENDIDAS"));
              foreach ($data as $r) {
                  array_push($variable, array($n++,$r->consultorio,$r->documento, $r->medico, $r->citas_atendidas));
              }
              $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
          });
      })->export('xls');
    }

