  public function genera_zip_admision_emergencia(Request $request){
    $csv = $this->genera_nombre_csv();

    $obj = new Archive7z(public_path('tmp/zip/sin_firma/'.$csv.'.7z'));
    
    foreach($request->mov as $row) {
      $this->genera_pdf_admision_emergencia($row, true);
      $obj->addEntry(public_path("/tmp/pdf/sin_firma/admision_emergencia_{$row}.pdf")); 
    }

    $resultado["csv"]=$csv;
    $resultado["sw"]=true;
    echo json_encode($resultado);
  }

  public function registra_firma_admision_emergencia(Request $request){
    $tipo = $request->id_tipo;
    $id = $request->id_resol;

    $emergencias = \App\Models\Emergencia::where('id', $id)->get();
    
    foreach($emergencias as $admision){
      if($admision->fecha_firma_admision == ""){
          $admision->fecha_firma_admision = date("d-m-Y H:i:s");
          $admision->ruta_admision = date("Y/m/d")."/cf_admision_emergencia_{$admision->id}.pdf";
          $admision->flag_admision = 1;
          $admision->save();
      }
    }
    return "ok";
  }

