  public function genera_zip_interconsulta_rpta(Request $request){
      
    $path = public_path('tmp/csv');
    $path_zip = public_path('tmp/zip');

    if (!is_dir($path)) {
        mkdir($path);
    }

    if (!is_dir($path_zip)) {
        mkdir($path_zip);
        mkdir(public_path('tmp/zip/firmados'));
        mkdir(public_path('tmp/zip/sin_firma'));
    }
    
    $csv = "";
    if (Auth::check()):
        $csv .= Auth::user()->id;
    endif;
    //$csv = Auth::user()->id;
    $csv .= "_".date("YmdHis");
    
        

    Excel::create($csv, function($excel) use($request){
        $excel->sheet('GENERAL', function($sheet) use($request) {
            $model_receta = new Receta_vale;
            $model_laboratorio = new \App\Models\Laboratorio;
            $model_radiologia = new \App\Models\Radiologia;
            $model_interconsulta = new \App\Models\Interconsulta;
            $variable = [];
            
            foreach($request->mov as $row):

                $this->genera_pdf_interconsulta_rpta($row, true);
                //$obj->addEntry(public_path("/tmp/pdf/sin_firma/interconsulta_rpta_{$row}.pdf")); 
                
                $receta = $model_receta->GetRecetasByIdInterconsulta($row);
                $laboratorios = $model_laboratorio->GetLaboratorioByIdInterconsulta($row);
                $radiologias = $model_radiologia->GetRadiologiaByIdInterconsulta($row);

                //genera pdf recetas
                if(isset($receta)){
                    foreach($receta as $rowrv){
                        if ($rowrv->ruta_receta == "") {
                            $this->ver_receta_vale($rowrv->id);
                        }
                    }
                  }
                
                //genera pdf laboratorios
                 if(isset($laboratorios)){
                    foreach($laboratorios as $laboratorio) {
                         if ($laboratorio->fecha_firma == ""){
                            if ($laboratorio->id_establecimiento == 76){
                                $this->ver_laboratorio_imprimir($laboratorio->id);
                            }
                            else{

                             $this->generateRUAPdf_nivel1y2($laboratorio->id);
                            }
                         }
                     }
                }

                //genera pdf radiologias
                if(isset($radiologias)){
                    foreach($radiologias as $radiologia) {
                        if ($radiologia->fecha_firma == ""){
                            $this->ver_radiologia_imprimir($radiologia->id);
                        }
                    }
                }

            endforeach;
            $sheet->fromArray($variable, null, '', false, false);
        });
    })->store('csv',public_path('tmp/csv'));

        $obj = new Archive7z(public_path('tmp/zip/sin_firma/'.$csv.'.7z'));

        $model_receta = new Receta_vale;
        $model_laboratorio = new \App\Models\Laboratorio;
        $model_radiologia = new \App\Models\Radiologia;
        
        foreach($request->mov as $row){
            //$evaluacion = $model_evaluacion->GetEstadoFirmaEvaluacion($id_evaluacion);
            
            $receta = $model_receta->GetRecetasByIdInterconsulta($row);
            $laboratorios = $model_laboratorio->GetLaboratorioByIdInterconsulta($row);
            $radiologias = $model_radiologia->GetRadiologiaByIdInterconsulta($row);            
            
            $obj->addEntry(public_path('/tmp/pdf/sin_firma/interconsulta_rpta_'.$row.'.pdf')); 
            
            
            

            if(isset($receta)){
                foreach($receta as $rowrv){

                    if ($rowrv->ruta_receta == "") {
                        $obj->addEntry(public_path('/tmp/pdf/sin_firma/receta_'.$rowrv->id.'.pdf')); 
                  }
                }

            }



            if(isset($laboratorios)){
                 foreach($laboratorios as $laboratorio) {
                   if ($laboratorio->fecha_firma == ""){
                         $obj->addEntry(public_path('/tmp/pdf/sin_firma/laboratorio_'.$laboratorio->id.'.pdf')); 
                   }
                 }
            }
            
            if(isset($radiologias)){
                foreach($radiologias as $radiologia) {
                    if ($radiologia->fecha_firma == ""){
                        $obj->addEntry(public_path('/tmp/pdf/sin_firma/radiologia_'.$radiologia->id.'.pdf')); 
                    }
                }
            }
        }

    $resultado["csv"]=$csv;
    $resultado["sw"]=true;
    echo json_encode($resultado);
  }

  public function genera_pdf_interconsulta_rpta($id_interconsulta,$guardar = false){
        $path = $this->valida_ruta_archivo_tmp();
        $modelfarma = new Farmacia;
