        $interconsulta = $model_interconsulta->GetInterconsulta($id_interconsulta);
        $id_prestacion = $interconsulta->id_prestacion;
        $prestacion = $model_prestacion->GetPrestacionById($id_prestacion);
        $diagnostico = $model_interconsulta->GetDiagnosticoByIdInterconsulta( $id_interconsulta);
        $procedimiento = $model_prestacion->GetProcedimientosByIdPrestacionydiagInterconsulta($id_prestacion,1, $id_interconsulta);
        
        if ($interconsulta->id_tipo_atencion == 2):
            $model_emergencia = new \App\Models\Emergencia;
            $datoadicional = null;
            $obtenerdato = $model_emergencia->GetObtenerServicioActual($prestacion->id_ext);
            $datoadicional = $model_emergencia->GetObtenerCama($obtenerdato->cama);
            
            $prestacion->servicio= $obtenerdato->consultorio;
            $prestacion->consultorio= $obtenerdato->servicio;
            $prestacion->pabellon= $datoadicional->pabellon;
            $prestacion->cuarto= $datoadicional->cuarto;
            $prestacion->cama= $datoadicional->cama;
            
            if($interconsulta->id_evaluacion==0):
              $interconsulta = $model_interconsulta->GetInterconsultaById($id_prestacion,$id_interconsulta);
            else:
              $interconsulta = $model_interconsulta->GetInterconsultaByIdEvaluacion($id_prestacion,$interconsulta->id_evaluacion,$id_interconsulta);
            endif;
        else:
            $interconsulta = $model_interconsulta->GetInterconsultaById2($id_interconsulta);
            
            $obtenerdato =  $model_hospitalizacion->GetObtenerDatos($prestacion->id_ext); // JALA LOS DATOS DE LA CAMA ACTUAL, PERO DEBEMOS DE JALAR LA CAMA DE ESE MOMENTO (PREGUNTAR) 

            $prestacion = $model_prestacion->GetPrestacionById($id_prestacion);
            $prestacion->servicio= $obtenerdato->servicio;
            $prestacion->consultorio= $obtenerdato->consultorio;
            $prestacion->pabellon= $obtenerdato->pabellon;
            $prestacion->cuarto= $obtenerdato->cuarto;
            $prestacion->cama= $obtenerdato->cama;

        endif;

        $carpeta = date("Y")."/".date("m")."/".date("d");
        $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_interconsulta_rpta_".$id_interconsulta.".pdf";
        $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_interconsulta_rpta_".$id_interconsulta.".pdf");
        $pdf = \PDF::loadView('pdf.firma_interconsulta_rpta',compact('prestacion','diagnostico','procedimiento','interconsulta','codigo_qr','url_descarga','id_interconsulta'));
        $pdf->getDomPDF()->set_option("enable_php", true);
        if ($guardar){
              file_put_contents($path."interconsulta_rpta_{$id_interconsulta}.pdf", $pdf->output());
        } else {
            return $pdf->stream('interconsulta_rpta.pdf');
        }
  }
  


  public function registra_firma_interconsulta_rpta(Request $request){
    $tipo = $request->id_tipo;
    $id = $request->id_resol;

    $interconsultas = \App\Models\Interconsulta::where('id', $id)->get();
    
    foreach($interconsultas as $interconsulta){
      if($interconsulta->fecha_rpta_firma_interconsulta == ""){
          $interconsulta->fecha_rpta_firma_interconsulta = date("d-m-Y H:i:s");
          $interconsulta->ruta_rpta_interconsulta = date("Y/m/d")."/cf_interconsulta_rpta_{$interconsulta->id}.pdf";
          $interconsulta->flag_rpta = 1;
          $interconsulta->save();
      }
    }

    
    $recetas = \App\Models\Receta_vale::where('id_interconsulta', $id)->get();
    foreach($recetas as $receta){
        if($receta->fecha_firma == ""){
            $receta->fecha_firma = date("d-m-Y H:i:s");
            $receta->ruta_receta = date("Y/m/d")."/cf_receta_".$receta->id.".pdf";
            $receta->flag = 1;
            $receta->save();
        }
    }
    

    $laboratorios = \App\Models\Laboratorio::where('id_interconsulta', $id)->get();
    foreach($laboratorios as $laboratorio){
        if($laboratorio->fecha_firma == ""){
            $laboratorio->fecha_firma = date("d-m-Y H:i:s");
            $laboratorio->ruta_laboratorio = date("Y/m/d")."/cf_laboratorio_".$laboratorio->id.".pdf";
            $laboratorio->flag = 1;
            $laboratorio->save();
        }
    }
    
    $radiologias = \App\Models\Radiologia::where('id_interconsulta', $id)->get();
    foreach($radiologias as $radiologia){
        if($radiologia->fecha_firma == ""){
            $radiologia->fecha_firma = date("d-m-Y H:i:s");
            $radiologia->ruta_radiologia = date("Y/m/d")."/cf_radiologia_".$radiologia->id.".pdf";
            $radiologia->flag = 1;
            $radiologia->save();
        }
    }
    
    return "ok";
  }

