  public function genera_pdf_interconsulta($id_interconsulta,$guardar = false){
    $path = $this->valida_ruta_archivo_tmp();

    $model_prestacion = new \App\Models\Prestaciones;
    $model_interconsulta = new \App\Models\Interconsulta;
    $model_evaluacion = new \App\Models\Evaluacione;

    $interconsultax = $model_interconsulta->GetBuscaInterconsultaById($id_interconsulta);

    $id_prestacion=$interconsultax->id_prestacion;

    if($interconsultax->id_evaluacion==0):
        $interconsulta = $model_interconsulta->GetInterconsultaById($id_prestacion,$id_interconsulta);
    else:
        $interconsulta = $model_interconsulta->GetInterconsultaByIdEvaluacion($id_prestacion,$interconsultax->id_evaluacion,$id_interconsulta);
    endif;
    $prestacion = $model_prestacion->GetPrestacionById($id_prestacion);

    $model_establecimiento = new Establecimiento();
    $establecimiento = $model_establecimiento->GetByIdEstablecimiento($prestacion->id_establecimiento);
    
    if ($prestacion->id_tipo_atencion==2):
        if (intval($establecimiento->nivel) === 2 || intval($establecimiento->nivel) === 3):
            $model_emergencia = new \App\Models\Emergencia;
            $datoadicional = null;
            $obtenerdato = $model_emergencia->GetObtenerServicioActual($prestacion->id_ext);
            $datoadicional = $model_emergencia->GetObtenerCama($obtenerdato->cama);
            
            $prestacion->servicio= $obtenerdato->consultorio;
            $prestacion->consultorio= $obtenerdato->servicio;
            $prestacion->pabellon= $datoadicional->pabellon;
            $prestacion->cuarto= $datoadicional->cuarto;
            $prestacion->cama= $datoadicional->cama;

            if($interconsultax->id_evaluacion==0):
                $diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacionEmergencia($id_prestacion);
                $interconsulta = $model_interconsulta->GetInterconsultaById($id_prestacion,$id_interconsulta);
                $procedimiento = $model_prestacion->GetProcedimientosByIdPrestacionEmergencia($id_prestacion, 1);
            else:  //evaluacion emergencia
                $diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacionEmergencia($id_prestacion);
                $diagnostico_evaluacion = $model_evaluacion->GetDiagnosticoByIdEvaluacion($interconsultax->id_evaluacion);
                $interconsulta = $model_interconsulta->GetInterconsultaByIdEvaluacion($id_prestacion,$interconsultax->id_evaluacion,$id_interconsulta);
                $procedimiento = $model_prestacion->GetProcedimientosByIdPrestacionEmergencia($id_prestacion, 1);
                $procedimiento_evaluacion = $model_prestacion->GetProcedimientosByIdPrestacionydiagEvaluacion($id_prestacion, 1, $interconsultax->id_evaluacion);
            endif;
        endif;
    else:
        if ($prestacion->id_tipo_atencion==3):
            if (intval($establecimiento->nivel) === 2 || intval($establecimiento->nivel) === 3):
                $model_cama = new \App\Models\Cama();
                $obtenerdato =  $model_cama->GetHospitalizacionCamaActualByHospitalizacionId($prestacion->id_ext); // JALA LOS DATOS DE LA CAMA ACTUAL, PERO DEBEMOS DE JALAR LA CAMA DE ESE MOMENTO (PREGUNTAR) 

                // $prestacion = $model_prestacion->GetPrestacionById($id_prestacion);
                $prestacion->servicio= $obtenerdato->servicio_encargado;
                $prestacion->consultorio= $obtenerdato->consultorio;
                $prestacion->pabellon= $obtenerdato->pabellon;
                $prestacion->cuarto= $obtenerdato->cuarto;
                $prestacion->cama= $obtenerdato->cama;

                $interconsulta = $model_interconsulta->GetInterconsultaById2($id_interconsulta);
            
                if ($interconsultax->id_evaluacion != 0):
                  $diagnostico = $model_evaluacion->GetDiagnosticoByIdEvaluacion($interconsultax->id_evaluacion);
                  $procedimiento = $model_prestacion->GetProcedimientosByIdPrestacionydiagEvaluacion($id_prestacion, 1, $interconsultax->id_evaluacion);
                else:
                    $diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacionHospitalizacion($id_prestacion);
                    $procedimiento = $model_prestacion->GetProcedimientosByIdPrestacionHospitalizacion($id_prestacion, 1); 
                endif;
            endif;
        else:
            $diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacion($id_prestacion);
            $procedimiento = $model_prestacion->GetProcedimientosByIdPrestacion($id_prestacion, 1);   
            $interconsulta = $model_interconsulta->GetInterconsultaById($id_prestacion,$id_interconsulta);
        endif;
    endif;
    $carpeta = date("Y")."/".date("m")."/".date("d");
    $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_interconsulta_".$id_prestacion.".pdf";
    $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_interconsulta_".$id_interconsulta.".pdf");
    
    if ($guardar) {
        $pdf = \PDF::loadView('pdf.firma_interconsulta',compact('prestacion','diagnostico','procedimiento','interconsulta','codigo_qr','url_descarga','id_interconsulta'));
        $pdf->getDomPDF()->set_option("enable_php", true);
        file_put_contents($path."interconsulta_{$id_interconsulta}.pdf", $pdf->output());
    } else {
