        if($tipo == "evolucion"){
          $evoluciones = \App\Models\Evolucion::where('id', $id)->get();
        
            foreach($evoluciones as $evolucion){
              if($evolucion->fecha_firma == ""){
                  $evolucion->fecha_firma = date("d-m-Y H:i:s");
