    public function ver_plantilla_rua($prestacion,$diagnostico,$laboratorio,$proclaboratorio,$id_laboratorio) {
        
        $carpeta = date("Y")."/".date("m")."/".date("d");
        $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/1/".$carpeta."/cf_laboratorio_".$id_laboratorio.".pdf";
        $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_laboratorio_".$id_laboratorio.".pdf");
        

        $model_establecimieto = new Establecimiento;
        $establecimiento = $model_establecimieto->GetById($prestacion->id_establecimiento);
        $nivel = $establecimiento[0]->nivel;  
        $codigo_ipress = $establecimiento[0]->codigo;
        $tipo_atencion = $prestacion->id_tipo_atencion;
        
        $model_laboratorio = new \App\Models\Laboratorio;        
        $lista_rua = $model_laboratorio->getVerRua($nivel, $tipo_atencion);
        $total_categoria = $model_laboratorio->getNumCategoria($nivel, $tipo_atencion);
        $num_categoria = $total_categoria->total;
        $total_examenes = count($lista_rua) + $num_categoria;
        
        //$categorias = $model_laboratorio->getCategoriaNivelRua($nivel, $tipo_atencion);

        if($nivel==1){
            $num_columna=2;
            $sum=$total_examenes%2;
            $adicional = 50-$total_examenes;
            if($sum==0){
                $adicional = 50-$total_examenes + 1;    
            }
        }
        else{
            if($nivel>1 && $tipo_atencion==2){ //emergencia
                $num_columna=2;
                $sum=$total_examenes%2;
                $adicional = 50-$total_examenes + $sum;
                if($sum!=0){
                    $adicional = 50-$total_examenes;    
                }
                
            }else{
                $num_columna=4;
                $sum=$total_examenes%2;
                $adicional = 180-$total_examenes + $sum;
                if($sum!=0){
                    $adicional = 180-$total_examenes;    
                }      
            }
        }

        $sw=0; $total_marcado=0;
        foreach($lista_rua as $e) {   
            $i=1;

            foreach($proclaboratorio as $key=>$p){
                if($p->id==$e->id){
                    $e->muestra=1;
                    $total_marcado++;
                    break;
                }
                else{
                    $e->muestra=0;
                }
            }
        }
        
	$total_marcado_letra=$model_laboratorio->convertir($total_marcado);

        switch($prestacion->parentesco){
             case 'PADRES': $p='P'; break;
             case 'HIJO MENOR DE EDAD': $p='H'; break;
             case 'CONCUBINA(O)': $p='C';break;
             case 'CONYUGE': $p='C';break;
             case 'HIJO MAYOR DE EDAD': $p='H'; break;
             case 'HIJO INCAPACITADO': $p='H'; break;
             case 'DERECHOHABIENTE': $p='O';break;
             case 'TITULAR': $p='T';break;
             case 'PADRES SOBREVIVIENTE': $p='P';break;
             case 'ESPOSA': $p='C'; break;
             case 'HIJO NO INCAPACITADO': $p='H';break;
             case 'OTROS': $p='O';break;
             case 'CIVIL': $p='O';break;
        } 
        if($nivel==1){
            $pdf = \PDF::loadView('pdf.prueba_firma_rua_nivel_1',compact('prestacion','diagnostico','laboratorio','proclaboratorio','codigo_qr','url_descarga','adicional','nivel','tipo_atencion','lista_rua', 'codigo_ipress','total_examenes','total_reg','adicional_rua','adicional')); 
        }
        else{
            if($nivel>1 && $tipo_atencion==2){ //emergencia
                $pdf = \PDF::loadView('pdf.prueba_firmar_rua_emergencia',compact('prestacion','diagnostico','laboratorio','proclaboratorio','codigo_qr','url_descarga','adicional','nivel','tipo_atencion','lista_rua', 'codigo_ipress','total_examenes','total_reg','adicional_rua','adicional'));   
            }else{
                if($nivel==3){ //ambulatorio
                    if($tipo_atencion==1){ //ambulatorio
                        $pdf = \PDF::loadView('pdf.prueba_firmar_rua_nivel_3',compact('prestacion','diagnostico','laboratorio','proclaboratorio','codigo_qr','url_descarga','adicional','nivel','tipo_atencion','lista_rua', 'codigo_ipress','total_examenes','total_reg','adicional_rua','adicional','total_marcado','total_marcado_letra','p'));
                        /*view('pdf.prueba_firmar_rua_nivel_3',compact('prestacion','diagnostico','laboratorio','proclaboratorio','codigo_qr','url_descarga','adicional','nivel','tipo_atencion','lista_rua', 'codigo_ipress','total_examenes','total_reg','adicional_rua','adicional'));*/
                    }
                    else{ //hospitalizacion
                        $pdf = \PDF::loadView('pdf.prueba_firmar_rua_hospitalizacion_3',compact('prestacion','diagnostico','laboratorio','proclaboratorio','codigo_qr','url_descarga','adicional','nivel','tipo_atencion','lista_rua', 'codigo_ipress','total_examenes','total_reg','adicional_rua','adicional'));
                    }
                }
                else{
                    if($tipo_atencion==1){ //ambulatorio
                        $pdf = \PDF::loadView('pdf.prueba_firmar_rua_nivel_3',compact('prestacion','diagnostico','laboratorio','proclaboratorio','codigo_qr','url_descarga','adicional','nivel','tipo_atencion','lista_rua', 'codigo_ipress','total_examenes','total_reg','adicional_rua','adicional'));
                    }
                    else{ //hospitalizacion
                        $pdf = \PDF::loadView('pdf.prueba_firmar_rua_hospitalizacion_3',compact('prestacion','diagnostico','laboratorio','proclaboratorio','codigo_qr','url_descarga','adicional','nivel','tipo_atencion','lista_rua', 'codigo_ipress','total_examenes','total_reg','adicional_rua','adicional'));
                    }   

                    

                }
            }
        }
        $pdf->setPaper('A4', 'landscape');
	$pdf->getDomPDF()->set_option("enable_php", true);
        return $pdf;
        
    }

    public function print_atencion($id_prestacion) {

        $model_prestacion = new \App\Models\Prestaciones;
        $model_receta = new Receta_vale;

        $prestacion = $model_prestacion->GetPrestacionById($id_prestacion);
        $diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacion($id_prestacion);
        $procedimiento = $model_prestacion->GetProcedimientoByIdPrestacionNew($id_prestacion);
        $receta = $model_receta->GetDatosRecetasByIdPrestacion($id_prestacion);
        $proclaboratorio = $model_prestacion->GetProcedimientosByIdPrestacionLab($id_prestacion);
        $procradiologia = $model_prestacion->GetProcedimientosRadiologicosByIdPrestacion($id_prestacion);
        $resumen_costo_atencion = $model_prestacion->GetResumenPrecioPorAtencion($id_prestacion);

        if ($prestacion->id_tipo_atencion==2):
            if ($prestacion->id_establecimiento==76  || $prestacion->id_establecimiento==26 || $prestacion->id_establecimiento==77 || $prestacion->id_establecimiento==75):
                $model_emergencia = new \App\Models\Emergencia;
                $obtenerdato = $model_emergencia->GetObtenerServicio($prestacion->id_ext);
                if($obtenerdato->id_prioridad!=4):
                    $prestacion->servicio= $obtenerdato->servicio;
                    $prestacion->consultorio= $obtenerdato->consultorio;
                else:
                    $prestacion->servicio= $obtenerdato->servicio;
                    $prestacion->consultorio= $obtenerdato->consultorio;
                endif;
            endif;
        else:
            if ($prestacion->id_tipo_atencion==3):
                if ($prestacion->id_establecimiento==76):
                    $model_hospitalizacion = new \App\Models\Hospitalizacione;
                    $obtenerdatoh = $model_hospitalizacion->GetObtenerDatos($prestacion->id_ext);
                    $prestacion->servicio= $obtenerdatoh->servicio;
                    $prestacion->consultorio= $obtenerdatoh->consultorio;
                    $prestacion->pabellon= $obtenerdatoh->pabellon;
                    $prestacion->piso= $obtenerdatoh->piso;
                    $prestacion->cuarto= $obtenerdatoh->cuarto;
                    $prestacion->cama= $obtenerdatoh->cama;
                endif;
            endif;
        endif;
        // dd($proclaboratorio);
        $carpeta = date("Y")."/".date("m")."/".date("d");
        //$url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_prestacion_".$id_prestacion.".pdf";
        //$codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_prestacion_".$id_prestacion.".pdf");
        $pdf = \PDF::loadView('pdf.atencion',compact('prestacion','diagnostico','procedimiento','codigo_qr','url_descarga','receta','proclaboratorio','procradiologia','resumen_costo_atencion'));
        $pdf->getDomPDF()->set_option("enable_php", true);
        return $pdf->stream('atencion.pdf');
    }

