    public function genera_zip_imagenologia(Request $request){
        $path = public_path('tmp'.DIRECTORY_SEPARATOR.'csv');
        $path_zip = public_path('tmp'.DIRECTORY_SEPARATOR.'zip');
    
        if (!is_dir($path)) {
            mkdir($path);
        }

        if (!is_dir($path_zip)) {
            mkdir($path_zip);
            mkdir(public_path('tmp'.DIRECTORY_SEPARATOR.'zip'.DIRECTORY_SEPARATOR.'firmados'));
            mkdir(public_path('tmp'.DIRECTORY_SEPARATOR.'zip'.DIRECTORY_SEPARATOR.'sin_firma'));
        }
        
        $csv = "";
        if (Auth::check()):
            $csv .= Auth::user()->id;
        endif;
        //$csv = Auth::user()->id;
        $csv .= "_".date("YmdHis");

        Excel::create($csv, function($excel) use($request){
            $excel->sheet('GENERAL', function($sheet) use($request) {
                $model_prestacion = new \App\Models\Prestaciones;
                $model_radiologia = new \App\Models\Radiologia;
                $model_medico = new \App\Models\Medico;
                $model_consultorio = new \App\Models\Consultorio;
                $radiologia = $model_radiologia->GetRadiologiaById($request->mov[0]);
                
                
                $id_prestacion=$radiologia->id_prestacion;
                $prestacion = $model_prestacion->GetPrestacionById($id_prestacion);
                Log::info("Los parametros de GetProcedimientosByIdPrestacionAndIdLabRadAndTipoAndIdServicioRad es la siguiente : ",array($id_prestacion, $request->mov[0], 3, $request->id_servicio_radiologia, $request->id_pp));
                $procradiologia = $model_prestacion->GetProcedimientosByIdPrestacionAndIdLabRadAndTipoAndIdServicioRad($request->mov[0],$request->id_servicio_radiologia, $request->id_pp);
                Log::info("El valor de procradiologia es la siguiente : ",$procradiologia);
                $variable = [];
                //genera pdf laboratorios
                if(isset($procradiologia)){
                    foreach($procradiologia as $row) {
