  public function genera_pdf_informe_imagenologia($prestacion, $radiologia, $id_prestacion,$id_radiologia, $id_servicio_radiologia, $idpp, $guardar = false){
        $path = $this->valida_ruta_archivo_tmp();
        Log::info('Entro en la función genera_pdf_informe_imagenologia');
        $model_radiologia = new \App\Models\Radiologia;
        $model_medico = new \App\Models\Medico;
        $procradiologia = $model_radiologia->GetProcedimientosByIdRadiologiaAndIdServicioRadiologia(/*$id_prestacion,$id_radiologia,$id_servicio_radiologia,*/$idpp);
        
        $medico = "";
        if (!empty($procradiologia[0]->dni_medico_validacion)):
            $medico = $model_medico->GetMedicoByDNI($procradiologia[0]->dni_medico_validacion);
        endif;

        $carpeta = date("Y")."/".date("m")."/".date("d");
        $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_informe-imagenologia_".$idpp.".pdf";
        $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_informe-imagenologia_".$idpp.".pdf");
        
        $pdf = \PDF::loadView('pdf.examen_radiologia_lns',compact('prestacion','radiologia','procradiologia','medico','codigo_qr','url_descarga','id_radiologia'));
        $pdf->getDomPDF()->set_option("enable_php", true);

        if ($guardar){
          file_put_contents($path."informe-imagenologia_{$idpp}.pdf", $pdf->output());
          // Verifica si el archivo existe
            if (File::exists($path . "informe-imagenologia_{$idpp}.pdf")) {
                // Si existe, registrar en el log que el archivo se generó correctamente
                Log::info("El archivo PDF se generó y guardó correctamente: informe-imagenologia_{$idpp}.pdf");
            } else {
                // Si no existe, registrar en el log un mensaje de error
                Log::error("Error al generar o guardar el archivo PDF: informe-imagenologia_{$idpp}.pdf");
            }
        } else {
          return $pdf->stream('informe-imagenologia.pdf');
        }
    }
    
