    public function genera_hoja_his($tipo_atencion,$id_establecimiento,$fecha_atencion,$id_medico, $id_consultorio,$id_hoja_his, $guardar = false){
        $path = $this->valida_ruta_archivo_tmp();
        
        $model_consultorio = new Consultorio;        
        $upss = $model_consultorio->ShowCodigoUpssIdTipoAtencion($id_consultorio,$tipo_atencion);
        
        $id_servicio=$upss[0]->id;
        $codigo_upss=$upss[0]->codigo;
        $nombre_upss=$upss[0]->nombre;

        $dni_medico=Auth::user()->dni;
        $id_establecimiento=Auth::user()->id_establecimiento;

        $model_establecimiento = new Establecimiento();
        $establecimiento = $model_establecimiento->GetByIdEstablecimiento($id_establecimiento);

        $modelmedico = new Medico();
        
        if(Auth::user()->flagservicios==1){
            $medico = $modelmedico->GetMostrarMedicoById($id_medico);    
        }else
        {
            $medico = $modelmedico->GetMostrarMedicoByDNI($dni_medico);    
        }

        $fecha_atencion = $fecha_atencion;
        $prestaciones = $modelmedico->GetMostrarAtencionesMedicoByHIS($tipo_atencion,$id_establecimiento,$fecha_atencion,$id_medico, $id_consultorio);
        switch ($tipo_atencion) {
            case '1': $nombre_atencion='AMBULATORIO';break;
            case '2': $nombre_atencion='EMERGENCIA';break;
            case '3': $nombre_atencion='HOSPITALIZACION';break;
            case '4': $nombre_atencion='OTRO';break;
        }
          
        $carpeta = date("Y")."/".date("m")."/".date("d");
        
        $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_hoja_his_".$id_hoja_his.".pdf";
        $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_hoja_his_".$id_hoja_his.".pdf");
        $pdf = \PDF::loadView('pdf.firmar_hoja_his',compact('establecimiento','codigo_upss','medico','fecha_atencion','prestaciones','nombre_atencion','tipo_atencion','nombre_upss','codigo_qr','url_descarga'));  
        $pdf->getDomPDF()->set_option("enable_php", true);

        if ($guardar){
          file_put_contents($path."hoja_his_{$id_hoja_his}.pdf", $pdf->output());
        } else {
          return $pdf->stream('hoja_his.pdf');
        }
    }

    
