      public function exportar_reporte_apertura(Request $request){
     
        if($request->dni==0)$request->dni="0";
        if($request->fecha_ini==0)$request->fecha_ini="";
        if($request->fecha_fin==0)$request->fecha_fin="";
        $iduser = Auth::user()->id;
        $fechaHasta =$request->fecha_fin;
        $fechaDesde =$request->fecha_ini;
        $dni =$request->dni;

            if (is_null($dni))
                $dni="";
            else
                $dni=strtoupper($dni);

            $fechaHasta = date('d-m-Y', strtotime($fechaHasta));
            $fechaDesde = date('d-m-Y', strtotime($fechaDesde));
            $id_establecimiento = Auth::user()->id_establecimiento;
            if($id_establecimiento==76){ 
              $id_establecimiento = 0;
            }

        $excelName = 'Reporte_Fema_Apertura_'. $iduser. '_' . Carbon::now()->format('Y-m-d_H-i-s');
        $excelNameResponse = 'Reporte_Fema_Apertura_'. $iduser . '_' . Carbon::now()->format('Y-m-d_H-i-s'). '.xlsx';
        $excel = Excel::create($excelName , function($excel) use($fechaDesde, $fechaHasta,$dni,$id_establecimiento ) {
        $excel->sheet('GENERAL', function($sheet) use($fechaDesde, $fechaHasta, $dni ,$id_establecimiento) {
            
            $variable = [];
            $n = 1;

            $model_fema = new Fema_fichaReporte();
            $femas = $model_fema->GetAllFema($fechaDesde, $fechaHasta, $dni, $id_establecimiento);

            $sheet->mergeCells('A1:U1');
            $sheet->cell('A1', function($cell) {$cell->setValue('DATOS DE APERTURA - FEMA');  $cell->setFontSize(15); $cell->setFontWeight('bold'); $cell->setAlignment('center'); $cell->setValignment('middle'); });
            
            $sheet->mergeCells('A3:A3');
            $sheet->cell('A3', function($cell) {$cell->setValue('#');   $cell->setFontSize(13); $cell->setFontWeight('bold'); $cell->setAlignment('center'); $cell->setValignment('middle'); $cell->setBackground('#3809F7'); });
            $sheet->mergeCells('B3:F3');
            $sheet->cell('B3', function($cell) {$cell->setValue('DATOS DE LAS IPRESS QUE NOTIFICA');   $cell->setFontSize(13); $cell->setFontWeight('bold'); $cell->setAlignment('center'); $cell->setValignment('middle'); $cell->setBackground('#F73409'); });
            $sheet->mergeCells('G3:U3');
            $sheet->cell('G3', function($cell) {$cell->setValue('DATOS DE LA PERSONA');   $cell->setFontSize(13); $cell->setFontWeight('bold'); $cell->setAlignment('center'); $cell->setValignment('middle'); $cell->setBackground('#09BB62');});
            
            
            array_push($variable, array('Reporte FEMA - Apertura  De ' . $fechaDesde . ' a ' . $fechaHasta));
            array_push($variable, array(""));
            array_push($variable, array("N","Fecha Registro","Hora Registro", "Establecimiento","Proceso","Sub-Proceso","DNI", "Nombre", "Apellido Paterno", "Apellido Materno", "CIP","Grado","Sexo","Edad", "Fecha Nacimiento", "Estado civil", "Unidad", "Situación", "Telefono","Departamento/Provincia/Distrito", "Registrador"));
            foreach ($femas as $u) {
              
                array_push($variable, array($n++, $u->fecha_reg, $u->hora_reg,$u->establecimiento,$u->proceso,$u->tipo_proceso,$u->nro_doc_ident, $u->nombre, $u->paterno, $u->materno, $u->carnet,$u->grado,$u->sexo, $u->edad,$u->fecha_nac,$u->estado_civil, $u->unidades_pnp,$u->situacion_pnp,$u->celular,$u->domicilio, $u->usu_paterno .''. $u->usu_materno.', '.$u->usu_nombre )); 
            }

            $sheet->with($variable)->mergeCells('A2:U2'); 
        });
    });
    $excel->store('xlsx', false, true)['full'];
    return response()->json(['excelNameResponse' => $excelNameResponse]);
  }

