    public function exportar_reporte_atencion_estados($fechaDesde, $fechaHasta, $idconsultorio, $id_farmacia, $estado){
        Excel::create('Exportar Reportes de Estados de Atenciones', function($excel) use($fechaDesde, $fechaHasta, $idconsultorio, $id_farmacia, $estado) {
            $excel->sheet('GENERAL', function($sheet) use($fechaDesde, $fechaHasta, $idconsultorio, $id_farmacia, $estado){

                $model_estados_atenciones = new Prestaciones();
                $estados_atenciones = $model_estados_atenciones->getReporteByRangoDeFechaByConsultorio($fechaDesde, $fechaHasta, $idconsultorio, $id_farmacia, $estado);
                $variable = [];
                $n = 0;
                
                foreach($estados_atenciones as $ea){
                    $n++;
                }

                array_push($variable, array("Reporte de Etenciones Médicas"));
                array_push($variable, array('De ' . $fechaDesde . ' a ' . $fechaHasta));
                array_push($variable, array('Total: '.$n++));
                array_push($variable, array(""));
                
				$cabecera = array();
				$n = 0;
				$cabecera[] = "Cod";
				$cabecera[] = "Servicios";
				$cabecera[] = "Fecha Cita";
				$cabecera[] = "Hora Cita";
				$cabecera[] = "Fecha Registro";
				$cabecera[] = "Nro Doc Paciente";
				$cabecera[] = "Beneficiario";
				$cabecera[] = "Nro Doc Responsable Cita";
				$cabecera[] = "Nombres Responsable Cita";
				$cabecera[] = "Nro Doc Médico";
				$cabecera[] = "Nombres Médico";
				$cabecera[] = "Modificado Por";
                $cabecera[] = "Estado";
				array_push($variable, $cabecera);

                foreach ($estados_atenciones as $ea) {
					$datos = array();
					$n++;
					$datos[] = $ea->id;
					$datos[] = $ea->nombre;
					$datos[] = $ea->fecha_cita;
                    $datos[] = $ea->hora_cita;
                    $datos[] = $ea->fecha_registro;
                    $datos[] = $ea->nro_doc_paciente;
                    $datos[] = $ea->nombre_paciente;
                    $datos[] = $ea->nro_doc_respo_cita;
                    $datos[] = $ea->nombre_responsable_cita;
                    $datos[] = $ea->nro_doc_medico;
                    $datos[] = $ea->nombre_medico;
                    $datos[] = $ea->nombre_modificacion;
                    $datos[] = $ea->descripcion;
					array_push($variable, $datos);
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }
    public function exportar_emergencia_triaje($id_user, $fecha_ini, $fecha_fin, $dni_beneficiario="", $nombre_beneficiario="", $estado=""){
 
        $modelusuario = new Farmacia();
        $usuario = $modelusuario->GetNombreUsuarioByIdUser($id_user);
        $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;
        $nombre_usuario= strtoupper($nombre_usuario);

        if ($dni_beneficiario==0) {
            $dni_beneficiario="";
        }

        if ($nombre_beneficiario=="-") {
            $nombre_beneficiario="";
        }      

        Excel::create('Exportar Reportes de Triajes atendidos por Emergencia', function($excel) use($fecha_ini, $fecha_fin, $nombre_usuario, $id_user, $dni_beneficiario, $nombre_beneficiario, $estado) {
                $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $nombre_usuario, $id_user, $dni_beneficiario, $nombre_beneficiario, $estado) {

                $modelfarma = new Farmacia;
                $model_est = new Establecimiento;

                $model_emergencias = new \App\Models\Emergencia();
                $farmacia = $modelfarma->GetFarmaByUser($id_user);
                $id_farmacia = $farmacia->id;
                $modo_validacion = $farmacia->modo_validacion;

                $id_establecimiento = Auth::user()->id_establecimiento;
                //----------------------------------------------------------------------
                $data = $model_emergencias->ListarTriajesAtendidos($id_establecimiento, $fecha_ini, $fecha_fin, $dni_beneficiario, 
                $nombre_beneficiario, $estado,0,0);
                $nro_atendidas = isset($data['totalrows']) ? $data['totalrows'] : 0; 
                //--------------------------------------------------------------
                $variable = [];
                $n = 1;

                $usuario = $modelfarma->GetNombreUsuarioByIdUser($id_user);
                $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;

                $establecimiento = $model_est->GetById(Auth::user()->id_establecimiento);
                $nombre_establecimiento = $establecimiento[0]->nombre;

                array_push($variable, array($nombre_establecimiento));
                array_push($variable, array("Reportes de Triajes atendidos por Emergencia"));
                array_push($variable, array("Fecha Desde: " . $fecha_ini));
                array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                array_push($variable, array("Total: " . $nro_atendidas . " triajes realizados"));
                array_push($variable, array("Usuario : " . $nombre_usuario ));
                array_push($variable, array(""));
                
                array_push($variable, array( "N",
                "FECHA/HORA TOTEM",
                "FECHA/HORA LLAMADO",
                "PROFESIONAL DE LLAMADO",
                "FECHA/HORA TRIAJE", 
                "MÉDICO TRIAJE",
                "TIPO DOC ",
                "NÚMERO DOC",
                "PACIENTE",
                "PARENTESCO",
                "SEXO",
                "FECHA NACIMIENTO",
                "EDAD",
                "PRIORIDAD",
                ($estado == 0 || $estado == 3) ? "" : "TÓPICO",
                "ESTADO",
                "MOTIVO DE CONSULTA"
                ));   



                foreach ($data['data'] as $r) {     

                    if ($r->estado == 1) {
                        $r->estado = 'PENDIENTE';

                    } else if ($r->estado == 2){
                        $r->estado = 'ATENDIDO';

                    } else if ($r->estado == 3){
                        $r->estado = 'NO NECESITA ADMISIONAR';
                        $r->topico = 'TRIAJE FINALIZADO';
                    } else if ($r->estado == 0){
                        $r->estado = 'ANULADO';
                        $r->topico = 'TRIAJE ANULADO';

                    } 

                    array_push( $variable, array(
                                                    $n++,
                                                    ($r->hora_totem == '') ? $r->fecha_totem : $r->fecha_totem.' - '.$r->hora_totem,  
                                                    ($r->hora_llamado == '') ? $r->fecha_llamado : $r->fecha_llamado.' - '.$r->hora_llamado, 
                                                    $r->apepaterno_llamado . ' ' . $r->apematerno_llamado. ' ' . $r->nombre_llamado,
                                                    ($r->hora_triaje == '') ? $r->fecha_triaje : $r->fecha_triaje.' - '.$r->hora_triaje, 
                                                    $r->apepaterno_profesional.' '.$r->apematerno_profesional.', '.$r->nombre_profesional,
                                                    $r->tipo_doc_ident,
                                                    $r->nro_doc_ident,
                                                    $r->paterno.' '.$r->materno.', '.$r->nombre, 
                                                    $r->parentesco,
                                                    $r->sexo_asegurado,
                                                    $r->fecha_nac,
                                                    $r->edad_asegurado,
                                                    $r->prioridad,
                                                    $r->topico,
                                                    $r->estado,
                                                    $r->observacion_triaje
                                                )
                                );
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6')->mergeCells('A7:D7');
            });
        })->export('xls');
    }
     

 
    public function exportar_emergencia_atenciones_repo($id_user, $fecha_ini, $fecha_fin, $dni_beneficiario = "", $nombre_beneficiario = "",
     $estado = "", $ubicacion = "", $id_prioridad = "", $id_topico = "", $id_motivo_ingreso = "",$id_tipo_violencia = "", $edad_desde = "", $edad_hasta = "", $tipo_consulta = ""){
