        if ($edad_hasta == 0) { $edad_hasta = "";}
        $descripUbicacion='';
        
        Excel::create('Exportar Reportes de Triajes atendidos por Emergencia', function ($excel) use 
        ($fecha_ini, $fecha_fin, $nombre_usuario, $id_user, $dni_beneficiario, $nombre_beneficiario, $estado, $ubicacion, $id_prioridad, $id_topico,$id_motivo_ingreso,$id_tipo_violencia,
         $edad_desde, $edad_hasta, $tipo_consulta) {
            $excel->sheet('GENERAL', function ($sheet) use ($fecha_ini, $fecha_fin, $nombre_usuario, $id_user, $dni_beneficiario, $nombre_beneficiario,
             $estado, $ubicacion, $id_prioridad, $id_topico, $id_motivo_ingreso, $id_tipo_violencia, $edad_desde, $edad_hasta, $tipo_consulta) {

                $modelfarma = new Farmacia;
                $model_est = new Establecimiento;

                $model_emergencias = new \App\Models\Emergencia();
                $farmacia = $modelfarma->GetFarmaByUser($id_user);
                $id_farmacia = $farmacia->id;
                $modo_validacion = $farmacia->modo_validacion;

                $id_establecimiento = Auth::user()->id_establecimiento;
                //----------------------------------------------------------------------
                $data = $model_emergencias->ListarTriajesAtendidosRepo($id_establecimiento, $fecha_ini, $fecha_fin, $dni_beneficiario, 
                $nombre_beneficiario, $estado, $ubicacion, $id_prioridad, $id_topico,$id_motivo_ingreso,$id_tipo_violencia, $edad_desde, $edad_hasta, $tipo_consulta ,0,0);
