                    }
                    array_push($variable, array("Ubicación: " . $descripUbicacion));
                } 
 

                if ($id_prioridad != 0) {  
                    array_push($variable, array("Prioridad: " . $model_emergencias->getDescripcionPrioridad($id_prioridad)));
                }
                if ($id_topico != 0) {
