                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array("")); 

                array_push($variable, array(
                    "N",
                    "N° DE ORDEN",
                    "DOC PACIENTE", 
                    "PACIENTE",
                    "SEXO",
                    "EDAD",
                    "TELEFONO",  
                    "DIRECCION",
                    "PARENTESCO",
                    "TIPO DE ATENCION",
                    "ESTABLECIMIENTO",
                    "UBICACIÓN DE PACIENTE",
                    "FECHA/HORA TOTEM",
                    "FECHA/HORA LLAMADO",
                    "PROFESIONAL DE LLAMADO",
                    //"TRIAJE DESCRIPCION",
                    "FECHA/HORA TRIAJE",
                    "PROFESIONAL DE SALUD - TRIAJE",
                    "PRIORIDAD TRIAJE",
                    "AREA/SERVICIO TRIAJE",
                    "FORMA DE INGRESO",
                    "ESTADO DE INGRESO",
                    "MOTIVO DE INGRESO",
                    "MOTIVO DE LA CONSULTA",
                    "FECHA/HORA ADMISION",
                    "COD. SITEDS",
                    "RESPONSABLE DE ADMISION",

                    "DOC ACOMPAÑANTE", 
                    "ACOMPAÑANTE",
                    "ÚLTIMO FECHA/HORA EVALUACIÓN",
                    "ÚLTIMO PERSONAL EVALUACIÓN",

                    "FECHA/HORA ATENCION MEDICA",
                    "MEDICO RESPONSABLE DE ATENCIÓN",
                    "PROCEDIMIENTOS-ATENCION MEDICA", 
                    "DIAGNOSTICO-ATENCION MEDICA",  

                    "VIOLENCIA",
                    "TIPO DE VIOLENCIA",
                    "COMISARIA",
                    "LUGAR DE ACCIDENTE",

                    "FECHA/HORA ALTA MEDICA",  
                    "TIPO DE EGRESO", 
                    "CONDICION DE ALTA", 
                    "SERVICIO(EN EL CASO DE SER HOSPITALIZADO)", 
                    "RESPONSABLE DE ALTA MEDICA", 
                    "DIAGNOSTICO EGRESO", 
                    "PROCEDIMEINTOS DE EGRESO", 
                    "FECHA/HORA ALTA ADMINISTRATIVA", 
                    "RESPONSABLE DE ALTA ADMINISTRATIVA", 
                ));  


                
                foreach ($data['data'] as $r) {
    
                        if ($r->id_tipo_egres_med == 1) {
                            $r->id_tipo_egres_med = 'ALTA';
                        } else if ($r->id_tipo_egres_med == 2) {
                            $r->id_tipo_egres_med = 'HOSPITALIZADO';
                        } else if ($r->id_tipo_egres_med == 3) {
                            $r->id_tipo_egres_med = 'TRASLADO'; 
                        } else if ($r->id_tipo_egres_med == 4) {
                            $r->id_tipo_egres_med = 'FALLECIDO'; 
                        } else if ($r->id_tipo_egres_med == 6) {
                            $r->id_tipo_egres_med = 'FUGA'; 
                        } else if ($r->id_tipo_egres_med == 7) {
                            $r->id_tipo_egres_med = 'RETIRO VOLUNTARIO'; 
                        } 
    
                        if ($r->id_condi_egres_med == 1) {
                            $r->id_condi_egres_med = 'MEJORADO';
                        } else if ($r->id_condi_egres_med == 2) {
                            $r->id_condi_egres_med = 'CURADO';
                        } else if ($r->id_condi_egres_med == 3) {
                            $r->id_condi_egres_med = 'TRASLADO'; 
                        } else if ($r->id_condi_egres_med == 4) {
                            $r->id_condi_egres_med = 'RETIRO VOLUNTARIO'; 
                        } else if ($r->id_condi_egres_med == 5) {
                            $r->id_condi_egres_med = 'FUGADO'; 
                        } else if ($r->id_condi_egres_med == 6) {
                            $r->id_condi_egres_med = 'FALLECIDO'; 
                        } 
                             
                        if ( $ubicacion == '') {
                            if ($r->fecha_registro_ingreso_triaje != null && 
                                $r->fecha_registro_admision == null && 
                                $r->fecha_atencion == null && 
                                $r->fecha_alta_medica == null && 
                                $r->fecha_egreso_administrativa == null) {
                                    $descripUbicacion='TRIAJE';
                            }else if ($r->fecha_registro_ingreso_triaje != null && 
                                $r->fecha_registro_admision != null && 
                                $r->fecha_atencion == null && 
