                                $r->fecha_egreso_administrativa == null) {
                                    $descripUbicacion='ATENCIÓN MÉDICA';
                            }else if ($r->fecha_registro_ingreso_triaje != null && 
                                $r->fecha_registro_admision != null && 
                                $r->fecha_atencion != null && 
                                $r->fecha_alta_medica != null && 
                                $r->fecha_egreso_administrativa == null) {
                                    $descripUbicacion='ALTA MÉDICA';
                            }else if ($r->fecha_registro_ingreso_triaje != null && 
                                $r->fecha_registro_admision != null && 
                                $r->fecha_atencion != null && 
