                        }else if($r->diagnostico_cab != null && $r->diagnostico_cab1 != null && $r->diagnostico_cab2 == null){
                            $emergencias_diagnostico='1.'.$r->diagnostico_cab. ' 2.' . $r->diagnostico_cab1;
                        }else if($r->diagnostico_cab != null && $r->diagnostico_cab1 != null && $r->diagnostico_cab2 != null){
                            $emergencias_diagnostico='1.'.$r->diagnostico_cab. ' 2.' . $r->diagnostico_cab1. ' 3.' . $r->diagnostico_cab2;
                        }  
                        $docu_conducido='';
                        if($r->dni_conducido != ''){
                            $docu_conducido='DNI'.$r->dni_conducido;
                        }

                        array_push(
                            $variable,
                            array( 
                                $n++,
                                //$r->cod_emergencia,
                                $r->secuencia,
                                $r->tipo_doc_ident.' '. $r->nro_doc_ident, 
                                $r->paterno . ' ' . $r->materno . ' ' . $r->nombre, 
                                $r->sexo_asegurado,
                                $r->edad_asegurado,
                                ($r->telefono2 == '') ? $r->telefono : $r->telefono.' / '.$r->telefono2,
                                $r->domicilio,
                                $r->parentesco,
                                'EMERGENCIA',
                                $r->establecimiento,
                                $descripUbicacion,
                                ($r->hora_totem == '') ? $r->fecha_totem : $r->fecha_totem.' - '.$r->hora_totem,  
                                ($r->hora_llamado == '') ? $r->fecha_llamado : $r->fecha_llamado.' - '.$r->hora_llamado, 
                                $r->apepaterno_llamado . ' ' . $r->apematerno_llamado. ' ' . $r->nombre_llamado,
                                //$r->topico,
                                ($r->hora_triaje == '') ? $r->fecha_triaje : $r->fecha_triaje.' - '.$r->hora_triaje, 
                                $r->apepaterno_profesional . ' ' . $r->apematerno_profesional . ' ' . $r->nombre_profesional,
                                $r->prioridad,
                                $r->topico,
                                $r->forma_ingreso,
                                $r->estado_ingreso,
                                $r->motivo_ingreso,
                                $r->observacion_admision,
                                ($r->hora_admision == '') ? $r->fecha_admision : $r->fecha_admision.' - '.$r->hora_admision,   
                                $r->cod_siteds_susalud,
                                $r->apepaterno_user_adm . ' ' . $r->apematerno_user_adm . ' ' . $r->nombre_user_adm,
                                $docu_conducido, 
                                $r->nombre_conducido,
                                ($r->ultimo_personal_evaluacion != "" ? $r->ultima_fecha_atencion_evaluacion . " - " . $r->ultima_hora_atencion_evaluacion : ""),
                                $r->ultimo_personal_evaluacion,

                                ($r->hora_procedimiento == '') ? $r->fecha_procedimiento : $r->fecha_procedimiento.' - '.$r->hora_procedimiento,  
                                $r->medico_responsable,
                                $r->procedimiento,
                                $r->diagnostico, 

                                $r->violencia,
                                $r->tipo_violencia,
                                $r->comisaria,
                                $r->lugar_accidente,

                                ($r->hora_alta_medica == '') ? $r->fecha_alta_medica : $r->fecha_alta_medica.' - '.$r->hora_alta_medica,   
                                $r->id_tipo_egres_med,
                                $r->id_condi_egres_med,
                                $r->servicio_destino,
                                $r->apepaterno_user_alta . ' ' . $r->apematerno_user_alta . ' ' . $r->nombre_user_alta,
                                $emergencias_diagnostico,
                                $r->procedimiento,
                                ($r->hora_egreso_administrativa == '') ? $r->fecha_egreso_administrativa : $r->fecha_egreso_administrativa.' - '.$r->hora_egreso_administrativa,
                                $r->apepaterno_user_admins . ' ' . $r->apematerno_user_admins . ' ' . $r->nombre_user_admins
                            )
                        );  
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6')->mergeCells('A7:D7')->mergeCells('A8:D8')->mergeCells('A9:D9');
            });
        })->export('xls');
    }


