    public function ver_emergencia_triaje_imprimir($id) { 
		
		$path = public_path('tmp/pdf');
		if (!is_dir($path)) {
			mkdir($path);
		}
		
		$path = public_path('tmp/pdf/sin_firma/');
		if (!is_dir($path)) {
			mkdir($path);
		}
		
		$triaje = DB::select('select * from emergencias e where e.id = '.$id);

		$carpeta = date("Y")."/".date("m")."/".date("d");
		$url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_emergencia-triaje_".$id.".pdf";
		$codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_emergencia-triaje_".$id.".pdf");

        $model_emergencia_triaje = new Emergencia();
        $WsReniec = new \App\Ws\Reniec;
        $apersonal = array();
        $emergencia_triaje = $model_emergencia_triaje->obtenerRegistroEmergencia($id);
        $dni = $emergencia_triaje->dni_beneficiario;
 
        //===================WS Reniec===================
        $datos_reniec = $WsReniec->BuscarDNI($dni);
        $personal = json_decode($datos_reniec, true); 
        if($personal){ 
            try {
                $apersonal['estado_civil'] = empty($personal['estado_civil']) ? '-' : $personal['estado_civil'];
                if($emergencia_triaje->domicilio_aseg !=null && $emergencia_triaje->departamento_descripcion !=null && 
                    $emergencia_triaje->provincia_descripcion !=null && $emergencia_triaje->distrito_descripcion !=null){ 
                        $apersonal['direccionDomicilio'] = $emergencia_triaje->domicilio_aseg;
                        $apersonal['departamentoDomicilio'] = $emergencia_triaje->departamento_descripcion;
                        $apersonal['provinciaDomicilio'] = $emergencia_triaje->provincia_descripcion;
                        $apersonal['distritoDomicilio'] = $emergencia_triaje->distrito_descripcion;
                }else{
                    $apersonal['direccionDomicilio'] = empty($personal['direccionDomicilio']) ? '-' : $personal['direccionDomicilio'];
                    if($personal['distritoDomicilio']=='CALLAO'){
                        $apersonal['departamentoDomicilio'] ='CALLAO';
                    }else{
                        $apersonal['departamentoDomicilio'] = empty($personal['departamentoDomicilio']) ? 'CALLAO' : $personal['departamentoDomicilio'];
                    }
                    $apersonal['provinciaDomicilio'] = empty($personal['provinciaDomicilio']) ? '-' : $personal['provinciaDomicilio'];
                    $apersonal['distritoDomicilio'] = empty($personal['distritoDomicilio']) ? '-' : $personal['distritoDomicilio'];
                }
            } catch (Exception $e) {
                if($emergencia_triaje->domicilio_aseg !=null && $emergencia_triaje->departamento_descripcion !=null && 
                    $emergencia_triaje->provincia_descripcion !=null && $emergencia_triaje->distrito_descripcion !=null){ 
                        $apersonal['direccionDomicilio'] = $emergencia_triaje->domicilio_aseg;
                        $apersonal['departamentoDomicilio'] = $emergencia_triaje->departamento_descripcion;
                        $apersonal['provinciaDomicilio'] = $emergencia_triaje->provincia_descripcion;
                        $apersonal['distritoDomicilio'] = $emergencia_triaje->distrito_descripcion;
                }else{
                    $apersonal['estado_civil'] = '-';
                    $apersonal['direccionDomicilio'] = '-';
                    $apersonal['departamentoDomicilio'] = '-';
                    $apersonal['provinciaDomicilio'] = '-';
                    $apersonal['distritoDomicilio'] = '-';
                }
            }
        } else{ 
            if($emergencia_triaje->domicilio_aseg !=null && $emergencia_triaje->departamento_descripcion !=null && 
                $emergencia_triaje->provincia_descripcion !=null && $emergencia_triaje->distrito_descripcion !=null){ 
                $apersonal['direccionDomicilio'] = $emergencia_triaje->domicilio_aseg;
                $apersonal['departamentoDomicilio'] = $emergencia_triaje->departamento_descripcion;
                $apersonal['provinciaDomicilio'] = $emergencia_triaje->provincia_descripcion;
                $apersonal['distritoDomicilio'] = $emergencia_triaje->distrito_descripcion;
            }else{
                $apersonal['estado_civil'] = '-';
                $apersonal['direccionDomicilio'] = '-';
                $apersonal['departamentoDomicilio'] = '-';
                $apersonal['provinciaDomicilio'] = '-';
                $apersonal['distritoDomicilio'] = '-';
            }
        }
        
        $date = Carbon::now();
        $fechaActual = $date->format('d/m/Y');
        $horaActual = $date->format('H:i:s');

        //--- ESTABLECIMIENTO
        $id_establecimiento=Auth::user()->id_establecimiento;// id_establecimiento = 76 - 1 mdico  
        $model_establecimiento = new Establecimiento();
        $establecimiento=  $model_establecimiento->GetById($id_establecimiento);
        $nombre_establecimiento = $establecimiento[0]->nombre;
        //--- -----------
		
        $pdf = \PDF::loadView('pdf.firmar_digital_triaje_emergencia',compact('triaje','codigo_qr','url_descarga','emergencia_triaje', 'fecha_ingreso', 'hora_ingreso', 'apersonal','nombre_establecimiento','fechaActual','horaActual'));

        

        $pdf->getDomPDF()->set_option("enable_php", true);

        file_put_contents($path."triaje_emergencia_".$id.".pdf", $pdf->output());

    }

    public function exportar_reporte_atencion_emergencia($id_user, $fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_prioridad, $id_topico) {
		
      if($dni==0)$dni="";
      if($paciente==0)$paciente="";
      
      $modelusuario = new Farmacia();
          $usuario = $modelusuario->GetNombreUsuarioByIdUser($id_user);
          $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;
      $paciente= strtoupper($paciente);
          Excel::create('Exportar Reportes de Atenciones en Emergencia', function($excel) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_prioridad, $id_topico, $nombre_usuario, $id_user) {
              $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_prioridad, $id_topico, $nombre_usuario, $id_user) {
          
          $modelfarma = new Farmacia;
          $model_usuario = new User;
          $model_medico = new \App\Models\Medico();
          $model_emergencias = new \App\Models\Emergencia();
          $farmacia = $modelfarma->GetFarmaByUser($id_user);
          $id_farmacia = $farmacia->id;
                  $establecimiento = $modelfarma->GetEstablecimientoPNP($id_farmacia);
          $modo_validacion = $farmacia->modo_validacion;
          //----------------------------------------------------------------------
          $usuario_actual = $model_usuario->GetById($id_user);
          $flagemergenciareferencia = $usuario_actual->flaghistoria;
          $medico = 0;
          if($flagemergenciareferencia!=1){
            $medico_actual = $model_medico->GetMedicoByDniAndEstablecimiento($usuario_actual->dni,$farmacia->id_establecimiento);
            $medico = $medico_actual->id;
          }
          
          $p[]=$fecha_ini;
          $p[]=$fecha_fin;
          $p[]=$dni;
          $p[]=$paciente;
          $p[]=$id_prioridad;
          $p[]=$id_topico;
          $p[]=$estado;
          $p[]=Auth::user()->id_establecimiento;
          $p[]=1;
          $p[]=10000;
          $prestaciones_atendidas = $model_emergencias->listar_prestacion_ajax_emergencia($p);
          $nro_atendidas = isset($prestaciones_atendidas[0]->totalrows)?$prestaciones_atendidas[0]->totalrows:0;
                  //--------------------------------------------------------------
                  $variable = [];
                  $n = 1;
                  array_push($variable, array($establecimiento->nombre));
                  array_push($variable, array("Reporte de Atenciones Medicas"));
                  array_push($variable, array("Fecha Desde: " . $fecha_ini));
                  array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                  array_push($variable, array("Total: " . $nro_atendidas . " atenciones"));
                  array_push($variable, array("Usuario : " . $nombre_usuario));
                  array_push($variable, array(""));
                  array_push($variable, array("N","FECHA", "HORA", "TIPO DOC", "NUMERO DOC", "NUMERO HISTORIA", "PACIENTE","PARENTESCO","SEXO", "FECHA DE NACIMIENTO", "EDAD","PRIORIDAD", "AREA", "RESPONSABLE ATENCION"));
                  foreach ($prestaciones_atendidas as $r) {
                    array_push($variable, array($n++,$r->fecha_atencion,$r->horario, $r->tipo_doc_ident, $r->nro_doc_ident,$r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,$r->parentesco,$r->sexo,$r->fecha_nac, $r->edadpaciente,$r->prioridad, $r->descripcion, $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre));
                  }
                  $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
              });
          })->export('xls');
      }


