    public function exportar_reporte_laboratorio(Request $request)
    {   
        if (!Auth::check()):
            return redirect('/all_laboratorio_prescritos_by_ipress');
        endif;

        $model_user = new User();
        $id_user = $request->id_user;
        $user = $model_user->getByID($id_user);
        $user = $user->paterno . " " . $user->materno . ", " . $user->name;

        $fechaDesde = $request->fechaDesde;
        $fechaHasta = $request->fechaHasta;
        $id_tipo_atencion = (int) $request->tipo_atencion;

        switch ($id_tipo_atencion){
            case 1:

                $model_laboratorio = new Laboratorio();
                $listados = $model_laboratorio->AllExamenLaboratorioConsultaExternaList($request->id_establecimiento, $request->fechaDesde, $request->fechaHasta, $request->dni_beneficiario, $request->nro_examen, $request->tipo_atencion, $request->id_servicio, $request->referido, $request->id_prioridad,$request->estado, $request->id_farmacia, $request->apellido_nombres, true);
                $cantidad = count($listados);
                break;

            case 2:
                $laboratorio_controller = new App\Http\Controllers\LaboratorioController();
                $listados = $laboratorio_controller->GetAllOrdenesEmergencia($request->id_establecimiento, $request->fechaDesde, $request->fechaHasta, $request->dni_beneficiario, $request->nro_examen, $request->tipo_atencion, $request->id_servicio, $request->referido, $request->id_prioridad,$request->estado, $request->id_farmacia, $request->apellido_nombres, true);
                break;

            case 3:
                $model_laboratorio = new Laboratorio();
                $listados = $model_laboratorio->AllExamenLaboratorioHospitalizacionList_v2($request->id_establecimiento, $request->fechaDesde, $request->fechaHasta, $request->dni_beneficiario, $request->nro_examen, $request->tipo_atencion, $request->id_servicio, $request->referido, $request->id_prioridad,$request->estado, $request->id_farmacia, $request->id_hora_toma_muestra, $request->id_ubicacion_hospital, true);
                $cantidad = count($listados);
                foreach ($listados as $key) {
                    $model_emergencia = new \App\Models\Emergencia;
                    $key->ubicacion_cama = (!is_null($key->id_cama) && intval($key->id_cama) > 0 ? $model_emergencia->GetObtenerCama($key->id_cama): 0);
                }
                break;
        }
        

        $fecha_hora_actual = Carbon::now()->format('Ymd_His');
        $excelName = 'Exportar_Reporte_de_laboratorio_' . $request->id_user . '_' . $fecha_hora_actual;
        $excelNameResponse = 'Exportar_Reporte_de_laboratorio_' . $request->id_user . '_' . $fecha_hora_actual . '.xlsx';
        $excel = Excel::create($excelName, function ($excel) use ($fechaDesde, $fechaHasta, $user, $listados, $id_tipo_atencion) {
            $excel->sheet('GENERAL', function ($sheet) use ($fechaDesde, $fechaHasta, $user, $listados, $id_tipo_atencion) {
                $variable = [];
                $n = 1;
                $cantidad = is_array($listados) ? count($listados) : 0;

                array_push($variable, array("Reporte de Laboratorio"));
                array_push($variable, array("Fecha Desde: " . $fechaDesde));
                array_push($variable, array("Fecha Hasta: " . $fechaHasta));
                array_push($variable, array("Total: " . $cantidad . " registros"));
                array_push($variable, array("Usuario : " . $user));
                array_push($variable, array(""));
                array_push($variable, array(
                    "#",
                    "NOMBRES Y APELLIDOS DEL PACIENTE",
                    "DOCUMENTO DEL PACIENTE",
                    "N° DOCUMENTO DEL PACIENTE",
                    "SEXO DEL PACIENTE",
                    "FECHA DE NACIMIENTO DEL PACIENTE",
                    "EDAD DEL PACIENTE",
                    "CONDICIÓN DEL PACIENTE",
                    "N° IDENTIFICADOR DE LA ORDEN",
                    "ORIGEN",
                    "ESPECIALIDAD",
                    "UBICACIÓN",
                    "PISO",
                    "CUARTO",
                    "CAMA",
                    "PRIORIDAD",
                    "FECHA FIRMA DE LA ORDEN",
                    "ESTADO",
                    "FECHA TOMA DE LA MUESTRA",
                    "ESTADO DE TOMA DE LA MUESTRA",
                    "ULTIMA FECHA DE TOMA DE MUESTRA",
                    "MOTIVO DE ANULACION DE LA ORDEN"
                ));
                // try {
                switch($id_tipo_atencion) {
                    case 1:
                        foreach ($listados as $r) {
                            $is_orden_anulada = intval($r->flag_observado) === 1;
                            $is_orden_observada = intval($r->flag_observado) === 2;
                            $estado_texto_anulacion = $is_orden_anulada ? "Anulado" : ($is_orden_observada ? "Observado" : "");

                            array_push($variable, array(
                                $n++,
                                $r->paciente,
                                $r->tipo_doc_ident,
                                $r->nro_doc_ident,
                                $r->sexo == "F" ? "FEMENINO" : "MASCULINO",
                                $r->fecha_nac,
                                $r->edad,
                                $r->referido == "1" ? "REFERIDO":"NO REFERIDO",
                                $r->id_orden_lab . " - " . $r->cod_orden_lab,
                                $r->nom_tipo_atencion,
                                $r->servicio,
                                "",
                                "",
                                "",
                                "",
                                "",
                                $r->fecha_firma,
                                $r->fecha_firma == null ? "Pendiente" : "Atendido",
                                (!$is_orden_anulada && !$is_orden_observada) ? $r->fecha_toma_muestra == null ? "Pendiente": $r->fecha_toma_muestra : "",
                                (!$is_orden_anulada && !$is_orden_observada) ? $r->fecha_toma_muestra == null ? "Pendiente": "Atendido" : $estado_texto_anulacion,
                                (!$is_orden_anulada && !$is_orden_observada) ? $r->fecha_last_toma_muestra != null ? $r->fecha_toma_muestra : "" : "",
                                ($is_orden_anulada || $is_orden_observada) ? $r->motivo_observado : ""
                            ));
                        }
                        break;
                    case 2:
                        foreach ($listados as $r) {
                            $is_orden_anulada = intval($r->estado_asistencia_paciente) === 1;
                            $is_orden_observada = intval($r->estado_asistencia_paciente) === 2;
                            $estado_texto_anulacion = $is_orden_anulada ? "Anulado" : ($is_orden_observada ? "Observado" : "");

                            array_push($variable, array(
                                $n++,
                                $r->nombre_beneficiario . ", ". $r->paterno_beneficiario . " " . $r->materno_beneficiario,
                                $r->tipo_doc_ident,
                                $r->nro_doc_ident,
                                $r->sexo_beneficiario == "F" ? "FEMENINO" : "MASCULINO",
                                $r->fecha_nac_beneficiario,
                                $r->edad_texto,
                                $r->referido == "1" ? "REFERIDO":"NO REFERIDO",
                                $r->id_lab . " - " . $r->cod_orden_lab,
                                $r->id_evaluacion > 0 ? "EMERGENCIA - EVALUACIÓN" : $r->nom_tipo_atencion,
                                $r->nom_especialidad_emergencia,
                                $r->pabellon,
                                $r->piso,
                                $r->cuarto,
                                $r->cama,
                                $r->nom_prioridad,
                                $r->fecha_firma,
                                $r->fecha_firma == null ? "Pendiente" : "Atendido",
                                (!$is_orden_anulada && !$is_orden_observada) ? $r->fecha_registro_toma_muestra == null ? "Pendiente": $r->fecha_registro_toma_muestra : "",
                                (!$is_orden_anulada && !$is_orden_observada) ? $r->fecha_registro_toma_muestra == null ? "Pendiente": "Atendido" : $estado_texto_anulacion,
                                (!$is_orden_anulada && !$is_orden_observada) ? $r->fecha_lastupdate_tomamuestra != null ? $r->fecha_registro_toma_muestra : "" : "",
                                ($is_orden_anulada || $is_orden_observada) ? $r->motivo_anulacion : ""
                            ));
                        }
                        break;
                    case 3:
                        foreach ($listados as $r) {
                            $is_orden_anulada = intval($r->estado_asistencia_paciente) === 1;
                            $is_orden_observada = intval($r->estado_asistencia_paciente) === 2;
                            $estado_texto_anulacion = $is_orden_anulada ? "Anulado" : ($is_orden_observada ? "Observado" : "");

                            array_push($variable, array(
                                $n++,
                                $r->nombre_beneficiario . ", ". $r->paterno_beneficiario . " " . $r->materno_beneficiario,
                                $r->tipo_doc_ident,
                                $r->nro_doc_ident,
                                $r->sexo_beneficiario == "F" ? "FEMENINO" : "MASCULINO",
                                $r->fecha_nac_beneficiario,
                                $r->edad_texto,
                                $r->referido == "1" ? "REFERIDO":"NO REFERIDO",
                                $r->id_lab . " - " . $r->cod_orden_lab,
                                $r->id_evaluacion > 0 ? "HOSPITALIZACIÓN - EVOLUCIÓN" : "HOSPITALIZACIÓN",
                                $r->servicio_hospitalizacion,
                                isset($r->ubicacion_cama) ? $r->ubicacion_cama->pabellon : "",
                                isset($r->ubicacion_cama) ? $r->ubicacion_cama->piso : "",
                                isset($r->ubicacion_cama) ? $r->ubicacion_cama->cuarto : "",
                                isset($r->ubicacion_cama) ? $r->ubicacion_cama->cama : "",
                                "",
                                $r->fecha_firma,
                                $r->fecha_firma == null ? "Pendiente" : "Atendido",
                                (!$is_orden_anulada && !$is_orden_observada) ? $r->fecha_registro_toma_muestra == null ? "Pendiente": $r->fecha_registro_toma_muestra : "",
                                (!$is_orden_anulada && !$is_orden_observada) ? $r->fecha_registro_toma_muestra == null ? "Pendiente": "Atendido" : $estado_texto_anulacion,
                                (!$is_orden_anulada && !$is_orden_observada) ? $r->fecha_lastupdate_tomamuestra != null ? $r->fecha_registro_toma_muestra : "" : "",
                                ($is_orden_anulada || $is_orden_observada) ? $r->motivo_anulacion : ""
                            ));
                        }
                        break;
                }

                $sheet->with($variable)->mergeCells('A2:B2')->mergeCells('A3:B3')->mergeCells('A4:B4')->mergeCells('A5:B5')->mergeCells('A6:B6');
            });
        });
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

    public function reporteChecklistLaboratorio($id_laboratorio)
    {
        if (!Auth::check()) {
            return redirect('/auth/login');
        }

        //$data=explode("_",$nro_receta);
        // $path = public_path('tmp/pdf');
        // if (!is_dir($path)) {
