            $id_prestacion=$laboratorio->id_prestacion;
            $prestacion = $model_prestacion->GetPrestacionById($id_prestacion);
            if($prestacion->id_tipo_atencion==3){
              $model_hospitalizacion = new \App\Models\Hospitalizacione();
              $hospitalizacion = $model_hospitalizacion::find($prestacion->id_ext);
              
              $consultorio = $model_consultorio->GetNombreById($hospitalizacion->id_consultorio);
            }else{
              $consultorio = $model_consultorio->GetNombreById($prestacion->id_consultorio);
            }
            // $consultorio = $model_consultorio->GetNombreById($prestacion->id_consultorio);
            $diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacionEvaluacion($id_prestacion, $laboratorio->id_evaluacion);
            //$diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacion($id_prestacion);
            
            //$proclaboratorio = $model_prestacion->GetProcedimientosByIdPrestacionAndIdLaboratorio($id_prestacion, $id_laboratorio,2);
            //$proclaboratorio = $model_prestacion->GetProcedimientosByIdPrestacionLab($id_prestacion);
            $proclaboratorio = $model_prestacion->GetPrestacionLaboratorio($id_prestacion, $id_laboratorio);
            if ($prestacion->id_tipo_atencion==1) {
                $model_laboratorio = new \App\Models\Laboratorio;
                $lista_rua = $model_laboratorio->getVerRuaConItemPorIdPrestacion($prestacion->nivel_estable, $prestacion->id_tipo_atencion, $prestacion->id_consultorio, $prestacion->id, $id_laboratorio);
                $total_categoria = $model_laboratorio->getNumCategoria($prestacion->nivel_estable, $prestacion->id_tipo_atencion, $prestacion->id_consultorio);
                $prestacion_procedimiento = $model_laboratorio->obtenerPrestacionProcedimientoPorIdPrestacion($laboratorio->id_prestacion);
                $laboratorio_prestacion = $model_laboratorio->GetLaboratorioByIdPrestacion($prestacion->id);
                $cant_procesados = 0;
                try {
                    foreach ($prestacion_procedimiento as $key => $value) {
                        if ($value->confirmar_toma == "0" || $value->confirmar_toma == "3") {
                            $cant_procesados++;
                        }
                    }
                } catch (\Throwable $th) {
                    $th->getMessage();
                }
                $cant_sin_reactivo = 0;
                try {
                    foreach ($prestacion_procedimiento as $key => $value) {
                        if ($value->confirmar_toma == "1" || $value->confirmar_toma == "4") {
                            $cant_sin_reactivo++;
                        }
                    }
                } catch (\Throwable $th) {
                    $th->getMessage();
                }
                $total_examenes_prestacion_procedimientos = [
                    "total_procesados"=>$cant_procesados,
                    "total_sin_reactivo"=>$cant_sin_reactivo
                ];

                $nivel =$prestacion->nivel_estable;
                $tipo_atencion = $prestacion->tipo_atencion;
               
                $num_categoria = $total_categoria->total;
                $total_examenes = count($lista_rua) + $num_categoria;
                $num_columna=$consultorio->reporte_columnas_lab;
                if($num_columna==0 ||$num_columna == null || $num_columna ==""){
                  return response()->json(["Object"=> "Error","message"=> "No hay columnas configuradas para este servicio. Por favor agrega Columnas"]);
                }
                $filas_por_columnas = ceil($total_examenes / $num_columna);
                $filas_por_columnas = intval($filas_por_columnas);
                
                $proxima_cita = $model_cita->GetCitasById($prestacion->id_cita_lab);
                // dd([
                //     "lista_rua"=>$lista_rua,
                //     "total_categoria"=>$total_categoria,
                //     "nivel"=>$nivel,
                //     "tipo_atencion"=>$tipo_atencion,
                //     "consultorio"=>$consultorio,
                //     "filas_por_columnas"=>$filas_por_columnas,
                //     "prestacion_procedimiento"=>$prestacion_procedimiento,
                //     "total_examenes_prestacion_procedimiento"=>$total_examenes_prestacion_procedimientos,
                //     "diagnosticos"=>$diagnostico,
                //     "prestacion"=>$prestacion,
                    
                // ]);

                try {
                    //Generar código de orden del examen
                    foreach ($laboratorio_prestacion as $lp) {
                        if (is_null($lp->fecha_toma_muestra)) {
                            $lp->cod_orden_lab = null;
                        } else {
                            $fecha = $lp->fecha_toma_muestra;
                            $numero = $lp->secuencial;
                            // Convertir la fecha al formato deseado ("2023/11/16")
                            $fechaObjeto = DateTime::createFromFormat('d/m/Y', $fecha);
                            $fechaFormateada = $fechaObjeto->format('Y/m/d');
                            // Procesamiento de la fecha para obtener "231116"
                            $fechaProcesada = substr(str_replace('/', '', $fechaFormateada), 2, 6);
                            // Convertir el número a una cadena y agregar ceros a la izquierda si es necesario
                            $numeroFormateado = str_pad($numero, 4, '0', STR_PAD_LEFT);
                            // Combinar ambas partes para obtener el resultado final
                            $lp->cod_orden_lab = $fechaProcesada . $numeroFormateado;
                        }
                    }
                } catch (\Throwable $th) {
                    $th->getMessage();
                }
                //cargar pdf Ambulatorio
                $carpeta = date("Y")."/".date("m")."/".date("d");
                $model_establecimiento = new App\Models\Establecimiento;
                $establecimiento = $model_establecimiento->GetById( auth()->user()->id_establecimiento );
                $Provincia = $model_establecimiento->GetProvinciaForUbego($establecimiento[0]->ubigeo);
                $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_laboratorio_".$id_laboratorio.".pdf";
                $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_laboratorio_".$id_laboratorio.".pdf");
                $pdf = \PDF::loadView('pdf.firmar_laboratorio_ambulatorio_checklist',compact('nivel','tipo_atencion','lista_rua','total_examenes','filas_por_columnas','consultorio','prestacion','diagnostico','total_examenes_prestacion_procedimientos','num_columna','proxima_cita','laboratorio_prestacion','laboratorio'));
            } elseif ($prestacion->id_tipo_atencion==2) {
                $model_laboratorio = new \App\Models\Laboratorio;
                $prestacion_procedimiento = $model_laboratorio->obtenerPrestacionProcedimientoPorIdPrestacionEmergencia($laboratorio->id_prestacion,$id_laboratorio);
                $proclaboratoriocabecera = $model_prestacion->GetPrestacionLaboratoriocabecera($id_prestacion, $id_laboratorio);
                $laboratorio_prestacion = $model_laboratorio->GetLaboratorioByIdCO($id_laboratorio);
                $p[] = $laboratorio->id_prestacion;
                $prestacion_emergencia = $model_prestacion->GetPrestacionEmergenciaById($p);
                $referencia = $prestacion_emergencia->id_motivo_ingreso;
                $cant_procesados = 0;
                
                try {
                    foreach ($prestacion_procedimiento as $key => $value) {
                        if ($value->confirmar_toma == "0" || $value->confirmar_toma == "3") {
                            $cant_procesados++;
                        }
                    }
                } catch (\Throwable $th) {
                    $th->getMessage();
                }
                $cant_sin_reactivo = 0;
                try {
                    foreach ($prestacion_procedimiento as $key => $value) {
                        if ($value->confirmar_toma == "1" || $value->confirmar_toma == "4") {
                            $cant_sin_reactivo++;
                        }
                    }
                } catch (\Throwable $th) {
                    $th->getMessage();
                }
                $total_examenes_prestacion_procedimientos = [
                    "total_procesados"=>$cant_procesados,
                    "total_sin_reactivo"=>$cant_sin_reactivo
                ];
                $model_emergencia = new \App\Models\Emergencia;
                $obtenerdato = $model_emergencia->GetObtenerServicio($prestacion->id_ext);
                $prestacion->servicio= $obtenerdato->servicio;
                $prestacion->consultorio= $obtenerdato->consultorio;

                $total_categoria = $model_prestacion->getNumCategoriaTotal();
                
                $num_categoria = $total_categoria->total;
                $total_examenes = count($proclaboratoriocabecera) + $num_categoria;

                // Definir el número de filas por columna
                $filas_por_columnas = 24;

                // Calcular la cantidad de columnas necesarias
                $columnas = ceil($total_examenes / $filas_por_columnas);

                // Calcular la cantidad de filas adicionales
                $filas_adicionales = $columnas * $filas_por_columnas - $total_examenes;

                // Distribuir las filas en las columnas
                $columna_actual = 1;
                $filas_en_columna_actual = 0;

                foreach ($proclaboratoriocabecera as $examen) {
                    // Agregar lógica para distribuir los exámenes en las columnas
                    // Puedes llevar un conteo de las filas en cada columna y asignar los exámenes en consecuencia.

                    // Verificar si es necesario agregar una fila adicional a esta columna
                    if ($filas_en_columna_actual >= $filas_por_columnas) {
                        if ($filas_adicionales > 0) {
                            // Agregar una fila adicional
                            $filas_adicionales--;
                        }
                    }

                    // Actualizar la columna actual y las filas en la columna actual
                    $columna_actual++;
                    if ($columna_actual > $columnas) {
                        $columna_actual = 1;
                        $filas_en_columna_actual = 0;
                    }
                }

                try {
                    //Generar código de orden del examen
                    foreach ($laboratorio_prestacion as $lp) {
