      public function exportar_reporte_alta_emergencia($fechaDesde ,$fechaHasta, $dni="", $paciente, $estado,$id_tipo_egreso, $id_prioridad, $id_topico) {

        //====================
        Excel::create('Reporte_Emergencia_Altas ', function($excel) use($fechaDesde, $fechaHasta,$estado,$id_tipo_egreso,$dni, $paciente, $id_prioridad, $id_topico ) {
            $excel->sheet('GENERAL', function($sheet) use($fechaDesde, $fechaHasta, $estado,$id_tipo_egreso, $dni, $paciente, $id_prioridad, $id_topico ) {
                $dni = strval($dni);
                $variable = []; 
                $n = 1;
                $rol=Auth::user()->flagresponsablefarmacia; //admin
  
                $fechaHasta = date('d-m-Y', strtotime($fechaHasta));
                $fechaDesde = date('d-m-Y', strtotime($fechaDesde));
            
                   $model_fema = new Emergencia();
                    $femas = $model_fema->GetReporteEmergenciaalta($fechaDesde, $fechaHasta,Auth::user()->id_establecimiento,$estado,$id_tipo_egreso,$dni,$paciente, $id_prioridad, $id_topico);
            
                $sheet->mergeCells('A1:M1');
                $sheet->cell('A1', function($cell) {$cell->setValue('Reporte Emergencia - Altas');  $cell->setFontSize(15); $cell->setFontWeight('bold'); $cell->setAlignment('center'); $cell->setValignment('middle'); });
                array_push($variable, array(' desde ' . $fechaDesde . ' a ' . $fechaHasta));
                array_push($variable, array(""));
                array_push($variable, array("N","Nro Doc","Nombre", "Apellido Paterno", "Apellido Materno","Grado","Parentesco","Sexo","Edad","Telefono","Prioridad","Area","Fecha Ingreso","Fecha Alta","Condición de Egreso", "CIE10-1","Diagnostico-1","CIE10-2","Diagnostico-2","CIE10-3","Diagnostico-3"));
                foreach ($femas as $u) {
                    if($u->grado!= null){ 
                        $grado = $u->grado;
                    }
                    else{
                        if ($u->parentesco!='TITULAR'){
                            $grado = $u->grado2;
                        }
                    }
                  
                    array_push($variable, array($n++, $u->dni_beneficiario,$u->nombre, $u->paterno, $u->materno,$grado,$u->parentesco,$u->sexo,$u->edadpaciente,$u->telefono_paciente, $u->prioridad, $u->servicio, $u->fecha_registro_ingreso,$u->fecha_alta_medica,$u->condicon_egreso,  $u->cie101,$u->diagnostico1,$u->cie102,$u->diagnostico2,$u->cie103,$u->diagnostico3 )); 
                }
  
                $sheet->with($variable)->mergeCells('A2:W2'); 
            });
        })->export('xlsx');
      }

