    public function exportar_reporte_emergencia_5($fechaDesde ,$fechaHasta) {
        //====================
        Excel::create('Reporte_Emergencia_Morbilidad_Urgencia_Mayores ', function($excel) use($fechaDesde, $fechaHasta ) {
            $excel->sheet('GENERAL', function($sheet) use($fechaDesde, $fechaHasta ) {
              
                $variable = [];
                $n = 1;
                $rol=Auth::user()->flagresponsablefarmacia; //admin
  
                $fechaHasta = date('d-m-Y', strtotime($fechaHasta));
                $fechaDesde = date('d-m-Y', strtotime($fechaDesde));
            
                $model_fema = new EmergenciaReporte();
                $femas = $model_fema->GetReporteEmergencia5($fechaDesde, $fechaHasta,Auth::user()->id_establecimiento);
            
                $sheet->mergeCells('A1:F1');
                $sheet->cell('A1', function($cell) {$cell->setValue('Reporte Emergencia : Morbilidad Urgencia Mayores ');  $cell->setFontSize(15); $cell->setFontWeight('bold'); $cell->setAlignment('center'); $cell->setValignment('middle'); });
                
                $sheet->mergeCells('A3:A3');
                $sheet->cell('A3', function($cell) {$cell->setValue('#');   $cell->setFontSize(13); $cell->setFontWeight('bold'); $cell->setAlignment('center'); $cell->setValignment('middle'); $cell->setBackground('#3809F7'); });
                $sheet->mergeCells('B3:F3');
                $sheet->cell('B3', function($cell) {$cell->setValue('DATOS ');   $cell->setFontSize(13); $cell->setFontWeight('bold'); $cell->setAlignment('center'); $cell->setValignment('middle'); $cell->setBackground('#09BB62');});

                array_push($variable, array(' desde ' . $fechaDesde . ' a ' . $fechaHasta));
                array_push($variable, array(""));
                array_push($variable, array("N","Diagnostico principal","Datos Beneficiario","Nombre Diagnostico","Diagnostico Secundario1","Nombre Diagnostico 1","Diagnostico Secundario2","Nombre Diagnostico 2","prioridad","beneficiario","situacion","Edad","Sexo"));
                foreach ($femas as $u) {
                  
                    array_push($variable, array($n++, $u->dx_principal,$u->nombre_completo,$u->dx_nomb_1,$u->dx_secundario_1,$u->dx_nomb_2, $u->dx_secundario_2,$u->dx_nomb_3,$u->prioridad,$u->beneficiario,$u->situacion,$u->edad,$u->sexo)); 
                }
  
