    public function exportar_reporte_movimiento_producto_receta($fecha_inicio, $fecha_fin, $id_producto, $id_user) {
    
        Excel::create('Exportar Reporte de Movimiento Producto Receta', function($excel) use($fecha_inicio, $fecha_fin, $id_producto, $id_user) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_inicio, $fecha_fin, $id_producto, $id_user) {
                $model_farma = new Farmacia;
                $farma = $model_farma->GetFarmaByUser($id_user);
                $id_farmacia = $farma->id;
                $farma = $model_farma->GetFarmaByIdfarma($id_farmacia);
                $nombre_farmacia = $farma->nombre;
                //------------------------------------------------------                        
                $model_receta = new \App\Models\Receta_vale;
                $kardex = $model_receta->AllRecetaKardexByFarmaAndProducto($id_farmacia,$nombre_farmacia, $id_producto, $fecha_inicio, $fecha_fin);
                $variable = [];
                $n = 0;
                foreach ($kardex as $c) {
                    $n++;
                }
                array_push($variable, array("Reporte de Movimiento del Producto por Receta del " . $nombre_farmacia));
                array_push($variable, array('De ' . $fecha_inicio . ' a ' . $fecha_fin));
                array_push($variable, array(""));
                array_push($variable, array("N", "ID","Fecha Registro", "Fecha Expedición","Fecha Firma", "Num Receta","DNI Paciente", "Codigo","Producto","Dispensado","Cantidad Prescrita","Cantidad Dispensada", "Saldo", "Medico"));
                $m = 1;
                $fecha_inicio = strtotime('-1 day', strtotime($fecha_inicio));
                $fecha_inicio = date('j-m-Y', $fecha_inicio);

                foreach ($kardex as $c) {
                    if($id_producto==11045 || $id_producto==15938 || $id_producto==14607 || $id_producto==14608){
                        $cantidad_kardex_prescrita = $c->cantidad_prescrita/1000;
                        $cantidad_kardex_dispensada = $c->cantidad_dispensada/1000;
                    }
                    else{
                        $cantidad_kardex_prescrita =$c->cantidad_prescrita;
                        if($cantidad_kardex_prescrita==0):$cantidad_kardex_prescrita='0'; endif;
                        $cantidad_kardex_dispensada =$c->cantidad_dispensada;
                        if($cantidad_kardex_dispensada==0):$cantidad_kardex_dispensada='0'; endif;
                    }

                    if($c->saldo==0):$saldo='0'; else: $saldo=$c->saldo; endif;

                    if($c->estado == 1):  $fecha_expedicion = $c->fecha_expedicion; $dispensado = 'SI'; else: $fecha_expedicion =''; $dispensado = 'NO'; endif;
                    $medico = $c->dni_medico.' - '.$c->nombre_medico.', '.$c->paterno_medico.' '.$c->materno_medico;
                    array_push($variable, array($m++, $c->id,$c->fecha_registro,$fecha_expedicion,$c->fecha_firma, $c->nro_receta,$c->dni_beneficiario,$c->codigo_producto,$c->nombre_producto,$dispensado,$cantidad_kardex_prescrita,$cantidad_kardex_dispensada,$saldo,$medico));
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:C3')->mergeCells('A4:C4');
            });
        })->export('xlsx');
    }

    public function exportar_reporte_cita2(Request $request) {

		if($request->dni==0)$request->dni="";
		if($request->paciente==0)$request->paciente="";
		
		if($request->fecha_ini==0)$request->fecha_ini="";
		if($request->fecha_fin==0)$request->fecha_fin="";
		if($request->fecha_reg_ini==0)$request->fecha_reg_ini="";
		if($request->fecha_reg_fin==0)$request->fecha_reg_fin="";
		
		$modelusuario = new Farmacia();
        $usuario = $modelusuario->GetNombreUsuarioByIdUser($request->idUser);
		$nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;
		$paciente= strtoupper($request->paciente);
        //================================================================
        $modelfarma = new Farmacia;
        $model_usuario = new User;
        $model_medico = new \App\Models\Medico();
        $model_citas = new \App\Models\Cita();
        $farmacia = $modelfarma->GetFarmaByUser($request->idUser);
        $id_farmacia = $farmacia->id;
        $establecimiento = $modelfarma->GetEstablecimientoPNP($id_farmacia);
        $modo_validacion = $farmacia->modo_validacion;
        //----------------------------------------------------------------------
        $usuario_actual = $model_usuario->GetById($request->idUser);
        $flagemergenciareferencia = $usuario_actual->flaghistoria;
        $medico = 0;
        if($flagemergenciareferencia!=1){
            if(Auth::user()->tipo_registro==1):
                $medico_actual = $model_medico->GetMedicoByDniAndEstablecimiento($usuario_actual->dni,$farmacia->id_establecimiento);
                $medico = $medico_actual->id;
            endif;
        }
        $p[]=$request->fecha_ini;
        $p[]=$request->fecha_fin;
        $p[]=$request->fecha_reg_ini;
        $p[]=$request->fecha_reg_fin;
        $p[]=$request->dni;
        $p[]=$request->paciente;
        //$p[]=$id_servicio;
        $p[]=(isset($request->id_servicio) && $request->id_servicio!="")?$request->id_servicio:0;
        //$p[]=$id_consultorio;
        $p[]=(isset($request->id_consultorio) && $request->id_consultorio!="")?$request->id_consultorio:0;
        $p[]=$request->id_medico;
        $p[]=Auth::user()->id_establecimiento;
        $p[] = $request->id_condicion_establecimiento;
        $p[] = $request->id_condicion_servicio;
        $p[]=$request->estado;
        $p[]=1;
        $p[]=10000;
        $citas = $model_citas->listar_cita_ajax($p);
        $nro_atendidas = isset($citas[0]->totalrows)?$citas[0]->totalrows:0;  
        //$citas = $model_citas->AllCitaConfirmaPacienteFecha($fecha, $dni, $paciente, $medico, $estado);
        //$nro_atendidas = $model_citas->GetCountCitaConfirmaPacienteFecha($fecha, $dni, $paciente, $medico, $estado);
        //--------------------------------------------------------------
        $excelName = 'Exportar_Reportes_de_Cita_' . $request->idUser . '_' . Carbon::now()->format('Y-m-d_H-i-s');
        $excelNameResponse = 'Exportar_Reportes_de_Cita_' . $request->idUser . '_' . Carbon::now()->format('Y-m-d_H-i-s') . '.xlsx';
        $excel = Excel::create($excelName, function($excel) use($establecimiento, $nombre_usuario, $nro_atendidas, $citas, $request) {
            $excel->sheet('GENERAL', function($sheet) use($establecimiento, $nombre_usuario, $nro_atendidas, $citas, $request) {
				
                $variable = [];
                $n = 1;
                array_push($variable, array($establecimiento->nombre));
                array_push($variable, array("Reporte de Citas"));
                array_push($variable, array("Fecha Cita Desde: " . $request->fecha_ini));
				array_push($variable, array("Fecha Cita Hasta: " . $request->fecha_fin));
				array_push($variable, array("Fecha Registro Desde: " . $request->fecha_reg_ini));
				array_push($variable, array("Fecha Registro Hasta: " . $request->fecha_reg_fin));
                array_push($variable, array("Total: " . $nro_atendidas . " citas"));
                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array(""));
                array_push($variable, array("N","FECHA CITA", "HORA CITA","FECHA REGISTRO","HORA REGISTRO", "TIPO DOC", "NUMERO DOC", "NUMERO HISTORIA", "PACIENTE","PARENTESCO","SEXO","FECHA DE NACIMIENTO", "EDAD", "TELEFONO", "TELEFONO 2",
                    "RESPONSABLE CITA","TIPO DE CITA","SERVICIO", "CONSULTORIO", "MEDICO", "ESTADO","CONDICION IPRESS","CONDICION UPSS","REFERIDO","ESTABLECIMIENTO REFERENCIA","OBSERVACION","CONSULTORIO REFERENCIA"));
                foreach ($citas as $r) {
                    if($r->establecimiento_referencia == "0"){
                        $r->establecimiento_referencia = "";
                    }
					$medico = "";
					if($r->medico_paterno!="")$medico = $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre;
					
                  array_push($variable, array($n++,$r->dia,$r->hora,$r->dia_registro,$r->hora_registro, $r->tipo_doc_ident, $r->nro_doc_ident,$r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre ,$r->parentesco,$r->sexo,$r->fecha_nac, $r->edadafiliado, $r->telefono, $r->telefono2,$r->usuario_cita,$r->tipo_cita,$r->servicio, $r->consultorio, $medico, $r->estado_cita, $r->condicion_establecimiento,$r->condicion_servicio,$r->referido,$r->establecimiento_referencia,$r->comentario_estado_observado,$r->servicio_referencia));
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
            });
        });
        // Devuelve la URL del archivo Excel generado
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

    public function descargarReporteDelStorage($name_reporte) 
    {
        // Nombre del archivo en el almacenamiento
        $nombreArchivo = $name_reporte;
        
        // Ruta completa del archivo en el almacenamiento
        $rutaArchivo = 'exports' . DIRECTORY_SEPARATOR . $nombreArchivo;

        $rutaCompleta = storage_path($rutaArchivo);

        return response()->download($rutaCompleta, $nombreArchivo, [
            'Content-Type' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        ]);
    }

    public function exportar_reporte_atencion_detallado(Request $request) {

		//$id_user, $fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_servicio, $id_consultorio, $id_medico,$id_atencione
        $id_user = $request->id_user;
        $fecha_ini = $request->fecha_ini;
        $fecha_fin = $request->fecha_fin;
        $dni = $request->dni;
        $paciente = $request->paciente;
        $estado = $request->estado;
        $id_servicio = $request->id_servicio;
        $id_consultorio = $request->id_consultorio;
        $id_medico = $request->id_medico;
        $id_atencione = $request->id_atencione;
        
		if($dni==0)$dni="";
		if($paciente==0)$paciente="";
		
		$modelusuario = new Farmacia();
        $usuario = $modelusuario->GetNombreUsuarioByIdUser($id_user);
        $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;
		$paciente= strtoupper($paciente);
        $excelName = 'Exportar Reportes de Atenciones Detallado';
        $excelNameResponse = 'Exportar Reportes de Atenciones Detallado.xlsx';
        $excel = Excel::create($excelName, function($excel) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_servicio, $id_consultorio, $id_medico, $nombre_usuario, $id_user,$id_atencione) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $id_servicio, $id_consultorio, $id_medico, $nombre_usuario, $id_user,$id_atencione) {
				
				$modelfarma = new Farmacia;
				$model_usuario = new User;
				$model_medico = new \App\Models\Medico();
				$model_citas = new \App\Models\Cita();
				$model_prestaciones = new \App\Models\Prestaciones();
				$farmacia = $modelfarma->GetFarmaByUser($id_user);
				$id_farmacia = $farmacia->id;
                $establecimiento = $modelfarma->GetEstablecimientoPNP($id_farmacia);
				$modo_validacion = $farmacia->modo_validacion;
				//----------------------------------------------------------------------
				$usuario_actual = $model_usuario->GetById($id_user);
				$flagemergenciareferencia = $usuario_actual->flaghistoria;
				$medico = 0;
				if($flagemergenciareferencia!=1){
					$medico_actual = $model_medico->GetMedicoByDniAndEstablecimiento($usuario_actual->dni,$farmacia->id_establecimiento);
					$medico = $medico_actual->id;
				}
				
				$p[]=$fecha_ini;
				$p[]=$fecha_fin;
				$p[]=$dni;
				$p[]=$paciente;
                $p[]=$id_servicio;
				if(Auth::user()->flaghospitalizacion==1):
                  //$p[]=0;
                  $p[]=0;
                else:
                  //$p[]=$id_servicio;
                  $p[]=$id_consultorio;
                endif;
                $p[]=$id_medico;
                $p[]=$estado;
                $p[]=$id_atencione;
                $p[]=Auth::user()->id_establecimiento;
                $p[]=1;
				$p[]=10000;
                
				$citas = $model_citas->listar_prestacion_ajax_nuevo($p);
                $procedimientos = $model_citas->listar_procedimiento_atenciones_detallado($p);           
                $nro_atendidas = isset($citas[0]->totalrows)?$citas[0]->totalrows:0;
                //--------------------------------------------------------------
                $variable = [];
                array_push($variable, array($establecimiento->nombre));
                array_push($variable, array("Reporte de Atenciones Medicas"));
                array_push($variable, array("Fecha Desde: " . $fecha_ini));
				array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                array_push($variable, array("Total: " . $nro_atendidas . " atenciones"));
                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array(""));
                array_push($variable, array("N","FECHA", "HORA", "TIPO DOC", "NUMERO DOC", "NUMERO HISTORIA", "PACIENTE","PARENTESCO","SEXO", "FECHA DE NACIMIENTO", "EDAD",
                    "RESPONSABLE CITA","TIPO DE CITA","SERVICIO", "CONSULTORIO", "TIPO ATENCION", "RESPONSABLE ATENCION", "CONDICION IPRESS","CONDICION UPSS", "CÓDIGO DIAGNÓSTICO (CIE)", "DESCRIPCION DIAGNÓSTICO", "TIPO DIAGNÓSTICO", "PROCEDIMIENTOS", "CANTIDAD"));
                
                $contador = 0;
                $encontrado = false;
                $i_quedado = 0;
                $aux_r = null;
                $hay_procedimientos = false;
              
                foreach ($citas as $r) {
                    $hay_procedimientos = false;

                    for($i = $i_quedado; $i < count($procedimientos); $i++) {
                        $hay_procedimientos = true;

                        // Validacion del primer registro de prestacion con procedimientos
                        if ($r->id == $procedimientos[$i]->id):

                            array_push($variable, array(
                                $r->orden, $r->fecha_atencion, $r->horario, $r->tipo_doc_ident, $r->nro_doc_ident, $r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,
                                $r->parentesco, $r->sexo, $r->fecha_nac, $r->edadafiliado, $r->usuario_cita, $r->tipo_cita, $r->servicio, $r->consultorio, $r->atencion, 
                                $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre, $r->condicion_establecimiento, $r->condicion_servicio, $r->codigo_dx, $r->nombre_dx, $r->tipo_dx,
                                $procedimientos[$i]->codigo_procedimiento." - ".$procedimientos[$i]->nombre_procedimiento,$procedimientos[$i]->cant_procedimiento)
                            );

                            // Guardamos la ultima data en variable auxiliar
                            $aux_r = $r;
                            $i_quedado = $i_quedado+1;
                            break;
                        else:
                            // Validacion del procedimiento con la variable auxiliar.
                            // Esto es en el caso que hayga mas procedimientos que registros de prestaciones (que ya incluyen diagnosticos)
                            if ($aux_r->id == $procedimientos[$i]->id) {
                                
                                array_push($variable, array(
                                    $aux_r->orden, $aux_r->fecha_atencion, $aux_r->horario, $aux_r->tipo_doc_ident, $aux_r->nro_doc_ident, $aux_r->nro_historia, 
                                    $aux_r->asegurado_paterno.' '.$aux_r->asegurado_materno.', '.$aux_r->asegurado_nombre, $aux_r->parentesco, $aux_r->sexo, $aux_r->fecha_nac, $aux_r->edadafiliado,
                                    $aux_r->usuario_cita, $aux_r->tipo_cita, $aux_r->servicio, $aux_r->consultorio, $aux_r->atencion, $aux_r->medico_paterno.' '.$aux_r->medico_materno.', '.$aux_r->medico_nombre,
                                    $aux_r->condicion_establecimiento, $aux_r->condicion_servicio, '', '', '', $procedimientos[$i]->codigo_procedimiento." - ".$procedimientos[$i]->nombre_procedimiento,$procedimientos[$i]->cant_procedimiento)
                                );
                                
                                $i_quedado = $i_quedado+1;

                            } else {
                                // Si no es el caso que hayga mas procedimientos que prestaciones
                                // Se procede a registrar la prestacion sin procedimiento (quiere decir que hay mas prestaciones que diagnosticos)
                                array_push($variable, array(
                                    $r->orden, $r->fecha_atencion, $r->horario, $r->tipo_doc_ident, $r->nro_doc_ident, $r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre ,
                                    $r->parentesco, $r->sexo, $r->fecha_nac, $r->edadafiliado, $r->usuario_cita, $r->tipo_cita, $r->servicio, $r->consultorio, $r->atencion, 
                                    $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre, $r->condicion_establecimiento, $r->condicion_servicio, $r->codigo_dx, $r->nombre_dx, $r->tipo_dx, '', '')
                                );
                                break;
                            }
                        endif;
                    }
					
                    $contador++;
                    
                    // Validacion que es el ultimo registro de prestaciones
                    // Y como no hay mas procedimientos se procede a registrar la prestacion sin procedimiento
                    if ($hay_procedimientos == false) {
                        if ($contador == count($citas)) {
                            array_push($variable, array(
                                $r->orden, $r->fecha_atencion, $r->horario, $r->tipo_doc_ident, $r->nro_doc_ident, $r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,
                                $r->parentesco, $r->sexo, $r->fecha_nac, $r->edadafiliado, $r->usuario_cita, $r->tipo_cita, $r->servicio, $r->consultorio, $r->atencion, 
                                $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre, $r->condicion_establecimiento, $r->condicion_servicio, $r->codigo_dx, $r->nombre_dx, $r->tipo_dx, '', '')
                            );
                        }
                    }
					
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
                $sheet->cells('X8:X' . (count($variable) + 7), function($cells) {
                    $cells->setAlignment('center');  
                    $cells->setValignment('center');
                });
            });
        });
        // Devuelve la URL del archivo Excel generado
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

