                                );
                            }
                        }
                    } else if ($count_diagnostico < $count_procedimiento) {
                        for ($i = 0; $i < $count_procedimiento; $i++) {
                            if (isset($diagnostico_filter[$i]->codigo_dx)) {
                                array_push($variable, array(
