    public function genera_csv_ordenes_laboratorio(Request $request) {
        
        $path = public_path('tmp'.DIRECTORY_SEPARATOR.'csv');
        $path_zip = public_path('tmp'.DIRECTORY_SEPARATOR.'zip');
    
        if (!is_dir($path)) {
            mkdir($path);
        }

        if (!is_dir($path_zip)) {
            mkdir($path_zip);
            mkdir(public_path('tmp'.DIRECTORY_SEPARATOR.'zip'.DIRECTORY_SEPARATOR.'firmados'));
            mkdir(public_path('tmp'.DIRECTORY_SEPARATOR.'zip'.DIRECTORY_SEPARATOR.'sin_firma'));
        }
        
        $csv = "";
        if (Auth::check()):
            $csv .= Auth::user()->id;
        endif;
        //$csv = Auth::user()->id;
        $csv .= "_".date("YmdHis");

        $model_farma = new Farmacia();
        $farmacia = $model_farma->GetIpressByIduser($request->id_user);
        $id_establecimiento = $farmacia->id;
        $dni_beneficiario = strtoupper($request->dni_beneficiario);
        if ($request->referido == 1) {
            $referido = "SI";
        } elseif ($request->referido == 2) {
            $referido = "NO";
        } else {
            $referido = "";
        }

        //Lista de ordenes o cod_orden_lab
        $model_laboratorio = new Laboratorio();
        $lista_ordenes = $model_laboratorio->AllValidadosParaFirmaExLabByEstaAndFechaDesdeHasta($id_establecimiento, $request->fechaDesde, $request->fechaHasta, $dni_beneficiario, $request->nro_examen, $request->tipo_atencion, $request->id_servicio, $referido, $request->id_prioridad,$request->estado);
        $cantidad = $model_laboratorio->GetCountExamenLaboratorioByFechaDesdeHasta($id_establecimiento, $request->fechaDesde, $request->fechaHasta, $dni_beneficiario, $request->nro_examen, $request->tipo_atencion, $request->id_servicio, $referido, $request->id_prioridad,$request->estado);

        //Array de ordenes
        foreach ($lista_ordenes as $laboratorio) {
            $lista_ordenes_laboratorio[] = $model_laboratorio->GetLaboratorioById($laboratorio->id_laboratorio);
        }

        // dd($lista_ordenes_laboratorio);
        //generación de csv
        Excel::create($csv, function($excel) use($lista_ordenes_laboratorio){
            $excel->sheet('GENERAL', function($sheet) use($lista_ordenes_laboratorio) {
                
                $variable = [];
                //genera pdf laboratorios
                if(isset($lista_ordenes_laboratorio)){
                    foreach($lista_ordenes_laboratorio as $orden_laboratorio) {
                        if ($orden_laboratorio->fecha_firma == ""){

                            //el pdf debe ser del FUPS
                            $this->ver_laboratorio_imprimir($orden_laboratorio->id);

                            //cambiar el directorio correcto
                            array_push($variable, array(url().DIRECTORY_SEPARATOR.'tmp'.DIRECTORY_SEPARATOR.'pdf'.DIRECTORY_SEPARATOR.'sin_firma'.DIRECTORY_SEPARATOR.'laboratorio_'.$orden_laboratorio->id.'.pdf', url().DIRECTORY_SEPARATOR.'upload_firma'.DIRECTORY_SEPARATOR.'?name=cf_laboratorio_'.$orden_laboratorio->id.'.pdf&id_tipo=laboratorio&id_resol='.$orden_laboratorio->id, 'cf_laboratorio_'.$orden_laboratorio->id.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().DIRECTORY_SEPARATOR.'images'.DIRECTORY_SEPARATOR.'escudo.jpg','1','7'));                             
                        }
                    }
                }
                
                $sheet->fromArray($variable, null, '', false, false);
            });
        })->store('csv',public_path('tmp'.DIRECTORY_SEPARATOR.'csv'));

        $obj = new Archive7z(public_path('tmp'.DIRECTORY_SEPARATOR.'zip'.DIRECTORY_SEPARATOR.'sin_firma'.DIRECTORY_SEPARATOR.$csv.'.7z'));

        $model_laboratorio = new \App\Models\Laboratorio;
        
        $laboratorios = $model_laboratorio->GetLaboratorioByIdPrestacion($request->id_prestacion);
            
        if(isset($laboratorios)){
            foreach($laboratorios as $laboratorio) {
                if ($laboratorio->fecha_firma == ""){
                    $obj->addEntry(public_path(DIRECTORY_SEPARATOR.'tmp'.DIRECTORY_SEPARATOR.'pdf'.DIRECTORY_SEPARATOR.'sin_firma'.DIRECTORY_SEPARATOR.'laboratorio_'.$laboratorio->id.'.pdf')); 
                }
            }
        }

	    $resultado["csv"]=$csv;
        $resultado["sw"]=true;
        echo json_encode($resultado);
    }

    /*
    EXPORTE PARA REPORTES EXCEL DE HOSPITALIZACION EVALUACIONES
    */
    public function exportar_reporte_hospitalizacion_evaluaciones(Request $request) {
		 
        $id_user = Auth::user()->id;
        $fecha_ini = $request->fecha_ini;
        $fecha_fin = $request->fecha_fin;

		$modelusuario = new Farmacia();
        $usuario = $modelusuario->GetNombreUsuarioByIdUser($id_user);
        $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;
        
        $modelfarma = new Farmacia;
        $model_evaluacion = new \App\Models\Evaluacione();
        $farmacia = $modelfarma->GetFarmaByUser($id_user);
        $id_farmacia = $farmacia->id;
        $establecimiento = $modelfarma->GetEstablecimientoPNP($id_farmacia);
        
        $p[]=$request->id_establecimiento;
        $p[]=$request->fecha_ini;
        $p[]=$request->fecha_fin;
        $p[]=$request->paciente_ndocumento;
        $p[]=$request->paciente_nombre;
        $p[]=$request->estado;
        $p[]=1;
        $p[]=100000;
        $p[]=$request->id_servicio;
        
        $evoluciones = $model_evaluacion->listar_evolucion_hospitalizacion($p);
        $cant_registros = isset($evoluciones[0]->totalrows)?$evoluciones[0]->totalrows:0;
                
        $excelName = 'Exportar_Reportes_de_Evaluacion_' . $id_user . '_' . Carbon::now()->format('Y-m-d_H-i-s');
        $excelNameResponse = 'Exportar_Reportes_de_Evaluacion_' . $id_user . '_' . Carbon::now()->format('Y-m-d_H-i-s') . '.xlsx';
        $excel = Excel::create($excelName, function($excel) use($fecha_ini, $fecha_fin, $nombre_usuario, $establecimiento, $cant_registros, $evoluciones) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $nombre_usuario, $establecimiento, $cant_registros, $evoluciones) {
				
                $variable = [];
                $n = 1;
                array_push($variable, array($establecimiento->nombre));
                array_push($variable, array("Reporte de Evoluciones - Hospitalización"));
                array_push($variable, array("Fecha Desde: " . $fecha_ini));
				array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                array_push($variable, array("Cantidad de registros: " . $cant_registros));
                array_push($variable, array("Usuario: " . $nombre_usuario));
                array_push($variable, array(""));
                array_push($variable, array("#", "N", "Fecha Última Atención", "Hora Última Atención", "N° Documento", "Paciente", "Grado", "Parentesco", "Sexo", "Edad", "Servicio A Cargo", "Ubicación (Servicio)", "Ubicación (Cama)", "SITEDS"));
                    
                foreach ($evoluciones as $r) {
                    array_push($variable, array($n++, $r->id, $r->fecha_primera_atencion, $r->hora_primera_atencion, $r->dni_beneficiario, $r->paterno.' '.$r->materno.', '.$r->nombre, $r->grado, $r->parentesco, $r->sexo, $r->edadpaciente, $r->servicio_encargado, $r->cama_servicio_nombre, $r->cama_nombre, $r->cod_siteds_susalud));
                }
                $sheet->with($variable)->mergeCells('A2:D2')->mergeCells('A3:D3')->mergeCells('A4:D4')->mergeCells('A5:D5')->mergeCells('A6:D6')->mergeCells('A7:D7');
            });
        });

        // Devuelve la URL del archivo Excel generado
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

/*
 CONTROLADOR PARA ALTAS REPORTES HOSPITALIZACION EXCEL

 */
    public function exportar_reporte_alta_hospitalizacion(Request $request) {
            
        $usuario_id = Auth::user()->id;
        $establecimiento_id = Auth::user()->id_establecimiento;
        $fecha_ini = $request->fecha_ini;
        $fecha_fin = $request->fecha_fin;
        $nro_documento = $request->dni_beneficiario;
        $paciente_nombre = strtoupper(trim($request->nombre_beneficiario));
        $estado = $request->estado;
        $servicio_id = $request->id_servicio;
        
        $usuario_model = new User();
        $usuario = $usuario_model->GetById($usuario_id);
        $usuario_nombre_completo = $usuario->paterno . ' ' . $usuario->paterno . ', ' . $usuario->name;

        $establecimiento_model = new Establecimiento();
        $establecimiento = $establecimiento_model->GetByIdEstablecimiento($establecimiento_id);
        $establecimiento_nombre = $establecimiento->nombre;
        
        $p[] = $establecimiento_id;
        $p[] = $fecha_ini;
        $p[] = $fecha_fin;
        $p[] = $nro_documento;
        $p[] = $paciente_nombre;
        $p[] = $estado;
        $p[] = 1;
        $p[] = 100000;
        $p[] = $servicio_id;
        
        $hospitalizacion_model = new Hospitalizacione();
        $data = null;
        if (intval($estado) === 4):
            $data = $hospitalizacion_model->listar_hospitalizacion_alta_pendiente($p);
        elseif (intval($estado) === 6):
            $p[] = $request->id_tipo_egreso;
            $data = $hospitalizacion_model->listar_atencion_hospitalizacion_ajax($p);
        endif;

        $fecha_hora_actual = Carbon::now()->format('Ymd_His');
        $excelName = 'Exportar_Hospitalizacion_Alta_' . $usuario_id . '_' . $fecha_hora_actual;
        $excelNameResponse = 'Exportar_Hospitalizacion_Alta_' . $usuario_id . '_' . $fecha_hora_actual . '.xlsx';

        $excel = Excel::create($excelName, function($excel) use($fecha_ini, $fecha_fin, $estado, $usuario_nombre_completo, $establecimiento_nombre, $data) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $estado, $usuario_nombre_completo, $establecimiento_nombre, $data) {
                
                $variable = [];
                $n = 1;
                array_push($variable, array($establecimiento_nombre));
                array_push($variable, array("Reporte de Altas Médicas Hospitalización"));
                array_push($variable, array("Fecha Desde: " . $fecha_ini));
                array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                array_push($variable, array("Usuario: " . $usuario_nombre_completo));
                array_push($variable, array(""));
                array_push($variable, array("#", "N", "Fecha Ingreso", "Fecha Alta", "Tipo Egreso", "Número de Documento del Paciente", "Paciente", "Parentesco", "Sexo", "Edad", "Teléfono", "Servicio a cargo", "Servicio (Ubicación)", "Cuarto (Ubicación)", "Cama (Ubicación)"));
                    
                foreach ($data as $r) {

                    $fecha_hora_egreso_medico = "";
                    $servicio_ubicacion = "";

                    if ($r->fecha_salida != null) $fecha_hora_egreso_medico = $r->fecha_salida;
                    if ($r->hora_salida != null) $fecha_hora_egreso_medico .= ' ' . $r->hora_salida;

                    if ($r->servicio_ubicacion_fisica != null) {
                        $servicio_ubicacion = $r->servicio_ubicacion_fisica;
                    } else if ($r->cama_servicio_nombre != null) {
                        $servicio_ubicacion = $r->cama_servicio_nombre;
                    }

                    array_push($variable,
                        array($n++,
                            $r->id,
                            $r->fecha_ingreso . ' ' . $r->hora_ingreso,
                            $fecha_hora_egreso_medico,
                            $r->tipo_egreso_paciente != null ? $r->tipo_egreso_paciente : '',
                            $r->paciente_nro_doc_ident,
                            $r->paciente_paterno . ' ' . $r->paciente_materno . ', ' . $r->paciente_nombre,
                            $r->paciente_parentesco,
                            $r->paciente_sexo,
                            $r->paciente_edad,
                            $r->paciente_telefono,
                            $r->servicio_encargado != null ? $r->servicio_encargado : 'No registrado',
                            $servicio_ubicacion,
                            $r->cuarto_nombre != null ? $r->cuarto_nombre : '',
                            $r->cama_nombre != null ? $r->cama_nombre : ''
                        )
                    );
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:E4')->mergeCells('A5:E5')->mergeCells('A6:E6');
            });
        });

        // Devuelve la URL del archivo Excel generado
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

