            if($flagemergenciareferencia!=1){
                $medico_actual = $model_medico->GetMedicoByDniAndEstablecimiento($usuario_actual->dni,$farmacia->id_establecimiento);
                $medico = $medico_actual->id;
            }
            
            $p[]=Auth::user()->id_establecimiento;
            $p[]=$fecha_ini;
            $p[]=$fecha_fin;
            $p[]=$dni;
            $p[]=$paciente;
            $p[]=$estado;
            
            $p[]=1;
            $p[]=10000;
            
            $evaluacion = $model_evaluacion->listar_altadAdministrativa_hospitalizacion($p);
            $nro_atendidas = isset($evaluacion[0]->totalrows)?$evaluacion[0]->totalrows:0;
                    
            $excelName = 'Exportar_Reportes_de_Altas_' . $id_user . '_' . Carbon::now()->format('Y-m-d_H-i-s');
    $excelNameResponse = 'Exportar_Reportes_de_Altas_' . $id_user . '_' . Carbon::now()->format('Y-m-d_H-i-s') . '.xlsx';
    $excel=Excel::create($excelName, function($excel) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $nombre_usuario, $establecimiento,$evaluacion) {
        $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $nombre_usuario, $establecimiento,$evaluacion) {
            
            //--------------------------------------------------------------
            $variable = [];
            $n = 1;
            array_push($variable, array($establecimiento->nombre));
            array_push($variable, array("Reporte de Altas Medicas"));
            array_push($variable, array("Fecha Desde: " . $fecha_ini));
            array_push($variable, array("Fecha Hasta: " . $fecha_fin));
            //array_push($variable, array("Total: " . $nro_atendidas . " evaluaciones"));
            array_push($variable, array("Usuario : " . $nombre_usuario));
            array_push($variable, array(""));
            array_push($variable, array("N","fecha_inicio","fecha_final","dni", "nombre", "Paterno","materno","Grado","Parentesco","Sexo","Edad","Telefono","Prioridad","Area","Fecha Ingreso","Fecha Alta","Condición de Egreso", "CIE10-1","Diagnostico-1","CIE10-2","Diagnostico-2","CIE10-3","Diagnostico-3"));
                
            foreach ($evaluacion as $r) {
                $grado = $r->grado;
                    array_push($variable, array($n++,$fecha_ini, $fecha_fin, $r->dni_beneficiario,$r->nombre, $r->paterno, $r->materno,$grado,$r->parentesco,$r->sexo,$r->edadpaciente,$r->telefono_paciente, $r->prioridad, $r->servicio, $r->fecha_registro_ingreso,$r->fecha_alta_medica,$r->condicon_egreso,  $r->cie101,$r->diagnostico1,$r->cie102,$r->diagnostico2,$r->cie103,$r->diagnostico3 )); 
                    
            }
            $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
        });
    });

// Devuelve la URL del archivo Excel generado
$excel->store('xlsx', false, true)['full'];
return response()->json(['excelNameResponse' => $excelNameResponse]);
}

