                                 //"", //$diagnosticos
                             ));
                         }
                     }
                 }
                 $sheet->with($variable)->mergeCells('A2:C2')->mergeCells('A3:C3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6')->mergeCells('A7:C7');
             });
         });

    //     // Devuelve la URL del archivo Excel generado
         $excel->store('xlsx', false, true)['full'];
