    }

    public function exportar_admision_hospitalizacion(Request $request) {
        
        $fecha_ini=$request->fecha_ini; 
        $fecha_fin=$request->fecha_fin;
        $dni=!empty($request->dni_beneficiario)?$request->dni_beneficiario:null;
        $paciente=!empty($request->nombre_beneficiario)?strtoupper($request->nombre_beneficiario):null;
        $estado=$request->estado;
        $id_servicio=$request->id_servicio;
        $id_tipo_atencion=$request->id_tipo_atencion;
        $fecha_ini_intervencion=$request->fecha_ini_intervencion;
        $fecha_fin_intervencion=$request->fecha_fin_intervencion;
        
        $id_user = Auth::user()->id;
		$modelfarma = new Farmacia();
        $farmacia = $modelfarma->GetFarmaByUser($id_user);
        $establecimiento = $modelfarma->GetEstablecimientoPNP($farmacia->id);
        $id_establecimiento=$establecimiento->id;

        $usuario = $modelfarma->GetNombreUsuarioByIdUser($id_user);
        $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;

        $fecha_ini_format = !empty($fecha_ini)?Carbon::createFromFormat('d-m-Y', $fecha_ini)->format('Y-m-d'):null;
        $fecha_fin_format = !empty($fecha_fin)?Carbon::createFromFormat('d-m-Y', $fecha_fin)->format('Y-m-d'):null;
        $id_estado_pendiente =!empty($request->id_estado_pendiente)?$request->id_estado_pendiente:null;
        
        $Cqxintervencion = new \App\Models\CqxIntervencion();
       //dd(array($id_tipo_atencion,$id_establecimiento,$fecha_ini_format,$fecha_fin_format,$fecha_ini_intervencion,$fecha_fin_intervencion,$dni,$paciente,isset($id_servicio) && !empty($id_servicio) ? intval($id_servicio) : null,isset($estado) && !empty($estado) ? $estado : null));
        $data = $Cqxintervencion->getReporteIntervenciones($id_tipo_atencion,$id_establecimiento,$fecha_ini_format,$fecha_fin_format,$fecha_ini_intervencion,$fecha_fin_intervencion,$dni,$paciente,isset($id_servicio) && !empty($id_servicio) ? intval($id_servicio) : null,isset($estado) && !empty($estado) ? $estado : null, $id_estado_pendiente);
        $cant_registros = count($data);
        $excelName = 'Exportar_Reportes_de_Lista_Pendientes_' . $id_user . '_' . Carbon::now()->format('Y-m-d H-i-s');
        $excelNameResponse = 'Exportar_Reportes_de_Lista_Pendientes_' . $id_user . '_' . Carbon::now()->format('Y-m-d H-i-s') . '.xlsx';
       
        $excel=Excel::create($excelName, function($excel) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $nombre_usuario, $id_user, $establecimiento, $data, $cant_registros) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $nombre_usuario, $id_user, $establecimiento, $data, $cant_registros) {

                //--------------------------------------------------------------
                $variable = [];
                $n = 1;
                array_push($variable, array($establecimiento->nombre));
                array_push($variable, array("Reporte de Lista Hospitalizacion"));
                array_push($variable, array("Fecha Desde: " . $fecha_ini));
				array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                array_push($variable, array("Total: " . $cant_registros . " registros"));
                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array(""));

                array_push($variable, array("N","ESTABLECIMIENTO", "RESPONSABLE" , "FECHA INGRESO" , "HORA INGRESO" ,"SERVICIO", "TIPO BENEFICIARIO", "DOCUMENTO" , "PACIENTE", "SEXO", "EDAD", "CUARTO","CAMA","DIAGNOSTICOS","PROCEDIMIENTOS PROGRAMADOS"));
                
                if (isset($data) && !empty($data) && count($data) > 0) {
                    foreach ($data as $r) {
                        $diagnosticos_str = '';

                        if (!empty($r->diagnosticos)) {
                            $texto = trim($r->diagnosticos, '{}');
                            $texto = str_replace(['\\"', '"', '(', ')'], '', $texto);
                            $diagnosticos_array = array_map('trim', explode(',', $texto));
                            $diagnosticos_array = array_filter($diagnosticos_array, function($d) {
                                return !empty($d);
                            });
                            $diagnosticos_str = implode(', ', $diagnosticos_array);
                        }


                        $procedimientos_str = '';

                        if (!empty($r->cpms_intervencion)) {
                            $texto = trim($r->cpms_intervencion, '{}');
                            preg_match_all('/\(([\d\.]+),\\\"([^"]+)\\\"\)/', $texto, $matches, PREG_SET_ORDER);
                            
                            $procedimientos_array = [];

                            foreach ($matches as $match) {
                                $codigo = trim($match[1]);
                                $descripcion = trim($match[2]);
                                $procedimientos_array[] = "$codigo - $descripcion";
                            }
                            if (empty($procedimientos_array)) {
                                $texto = str_replace(['\\"', '"', '(', ')'], '', $texto);
                                $procedimientos_array = array_map('trim', explode(',', $texto));
                            }
                            $procedimientos_array = array_filter($procedimientos_array, function($d) {
                                return !empty($d);
                            });

                            $procedimientos_str = implode(', ', $procedimientos_array);
                        }


                        array_push($variable, array(
                            $n++, 
                            $r->nombre_establecimiento, 
                            $r->medico_paterno." ".$r->medico_materno." ".$r->medico_nombre,
                            $r->fecha_atencion, 
                            $r->hora_registro, 
                            $r->nombre_servicio, 
                            $r->tipo_beneficiario,
                            $r->nro_doc_ident, 
                            $r->asegurado_paterno." ".$r->asegurado_materno." ".$r->asegurado_nombre, 
                            $r->sexo, 
                            $r->edadafiliado, 
                            $r->cuarto,
                            $r->cama,
                            $diagnosticos_str,
                            $procedimientos_str
                        ));
                    }
                }
                $sheet->with($variable)->mergeCells('A2:C2')->mergeCells('A3:C3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6')->mergeCells('A7:C7');
            });
        });

        // Devuelve la URL del archivo Excel generado
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }


