    public function genera_csv_receta_vale(Request $request){
      
        $path = public_path('tmp/csv');
        $path_zip = public_path('tmp/zip');
    
        if (!is_dir($path)) {
            mkdir($path);
        }

        if (!is_dir($path_zip)) {
            mkdir($path_zip);
            mkdir(public_path('tmp/zip/firmados'));
            mkdir(public_path('tmp/zip/sin_firma'));
        }
        
        $csv = "";
        if (Auth::check()):
            $csv .= Auth::user()->id;
        endif;
        //$csv = Auth::user()->id;
        $csv .= "_".date("YmdHis");
        
        
        Excel::create($csv, function($excel) use($request){
            $excel->sheet('GENERAL', function($sheet) use($request) {
                $model_receta = new Receta_vale;
                $variable = [];
                
                foreach($request->mov as $row):
                    $receta = $model_receta->GetRecetasByIdUser($row,$request->fecha_ini,$request->fecha_fin);
                    if(isset($receta)){
                        foreach($receta as $rowrv){
                            if ($rowrv->ruta_receta_dispensador == "") {
                                $this->ver_receta_vale2($rowrv->id);
                                array_push($variable, array(url().'/tmp/pdf/sin_firma/receta_dispensada'.$rowrv->id.'.pdf', url().'/upload_firma/?name=cf_receta_dispensada_'.$rowrv->id.'.pdf&id_tipo=receta&id_resol='.$rowrv->id, 'cf_receta_dispensada_'.$rowrv->id.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().'/images/escudo.jpg','1','7'));
                            }
                        }
                    }

                endforeach;
                $sheet->fromArray($variable, null, '', false, false);
            });
        })->store('csv',public_path('tmp/csv'));

            $obj = new Archive7z(public_path('tmp/zip/sin_firma/'.$csv.'.7z'));

            $model_receta = new Receta_vale;
            
            foreach($request->mov as $row){
                $receta = $model_receta->GetRecetasByIdUser($row,$request->fecha_ini,$request->fecha_fin);
                
                if(isset($receta)){
                    foreach($receta as $rowrv){
                        if ($rowrv->ruta_receta_dispensador == null) {
                            $obj->addEntry(public_path('/tmp/pdf/sin_firma/receta_dispensada_'.$rowrv->id.'.pdf')); 

                       }
                    }
                }
            }
        

    $resultado["csv"]=$csv;
        $resultado["sw"]=true;
        echo json_encode($resultado);
    }

    public function ver_receta_vale2($nro_receta) {
        //--------------------------------------------
        //var_dump($n); exit;
    $path = public_path('tmp/pdf');
    if (!is_dir($path)) {
      mkdir($path);
    }
    
    $path = public_path('tmp/pdf/sin_firma/');
    if (!is_dir($path)) {
      mkdir($path);
    }
    
        $model_farmacia = new Farmacia();
        $model_receta = new Receta_vale;
        $model_productos_receta = new Producto_receta;
        //--------------------------------------------  
        $receta = $model_receta->ShowAllById($nro_receta);
        $receta = $receta[0];

        if($receta->id_evaluacion!=0):
            $receta = $model_receta->ShowAllByIdEvaluacion($nro_receta);
            $receta = $receta[0];
        endif;

        $dni_beneficiario = $receta->dni_beneficiario;
        $establecimiento = $model_farmacia->GetEstablecimientoPNP($receta->id_farmacia);
        $medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($nro_receta);

        $productos = $model_receta->ProductosRecetaById($nro_receta);
        $model_receta_diagnostico = new Receta_diagnostico();
        $diagnosticos = $model_receta_diagnostico->DiagnosticosByIdReceta($nro_receta);

        if ($receta->tipo_receta=='EMERGENCIA'):
            if($establecimiento->id==76):
                $model_emergencia = new \App\Models\Emergencia;
                $obtenerdato = $model_emergencia->GetObtenerServicioReceta($receta->id_prestacion);
                if($obtenerdato->id_prioridad != 4 ):
                    $receta->servicio= $obtenerdato->servicio;
                    $receta->consultorio= $obtenerdato->consultorio;
                else:
                    $receta->servicio= "IV - PATOLOGÍA AGUDA COMÚN";
                    $receta->consultorio= "CONSULTORIO DE ATENCIÓN RÁPIDA (CAR)";
                endif;
            endif;
        endif;
    
        $carpeta = date("Y")."/".date("m")."/".date("d");
        $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_receta_dispensada_".$nro_receta.".pdf";
        $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_receta_dispensada_".$nro_receta.".pdf");
    
        $pdf = \PDF::loadView('pdf.firmar_receta_vale',compact('medicamentos','receta','establecimiento','productos','diagnosticos','codigo_qr','url_descarga'));
        
        $pdf->getDomPDF()->set_option("enable_php", true);
    
        file_put_contents($path."receta_dispensada_".$nro_receta.".pdf", $pdf->output());
    
    }
    public function exportar_reporte_imagenologia(Request $request)
    {   
        if (!Auth::check()):
            return redirect('/all_laboratorio_prescritos_by_ipress');
        endif;

        $model_user = new User();
        $id_user = $request->id_user;
        $user = $model_user->getByID($id_user);
        $user = $user->paterno . " " . $user->materno . ", " . $user->name;
        $estado = $request->estado;
        //==================== 
        $model_farma = new Farmacia();
        $farmacia = $model_farma->GetIpressByIduser($id_user);
        $id_establecimiento = $farmacia->id;
        //----------------------------------------------------------------------
        $tipo_atencion = $request->tipo_atencion;

        $id_servicio = $request->id_servicio;
        if ($request->referido == 1) {
            $referido = "SI";
        } elseif ($request->referido == 2) {
            $referido = "NO";
        } else {
            $referido = "";
        }
        $prioridad_emergencia = $request->id_prioridad;
        
        $fechaDesde = $request->fechaDesde;
        $fechaHasta = $request->fechaHasta;
        $dni_beneficiario = strtoupper($request->dni_beneficiario);
        // $nro_prestacion = $request->nro_prestacion;
        $nro_examen = $request->nro_examen;
        
        $model_laboratorio = new Laboratorio();
        $listados = $model_laboratorio->AllExamenLaboratorioByEstablecimientoAndFechaDesdeHasta($id_establecimiento, $fechaDesde, $fechaHasta, $dni_beneficiario, $nro_examen, $tipo_atencion, $id_servicio, $referido, $prioridad_emergencia,$estado);
        
        $cantidad = $model_laboratorio->GetCountExamenLaboratorioByFechaDesdeHasta($id_establecimiento, $fechaDesde, $fechaHasta, $dni_beneficiario, $nro_examen, $tipo_atencion, $id_servicio, $referido, $prioridad_emergencia,$estado);

        $excelName = 'Exportar_Reporte_de_laboratorio_' . $request->id_user . '_' . Carbon::now()->format('Y-m-d_H-i-s');
        $excelNameResponse = 'Exportar_Reporte_de_laboratorio_' . $request->id_user . '_' . Carbon::now()->format('Y-m-d_H-i-s') . '.xlsx';
        $excel = Excel::create($excelName, function ($excel) use ($farmacia, $fechaDesde, $fechaHasta, $cantidad, $user, $listados) {
            $excel->sheet('GENERAL', function ($sheet) use ($farmacia, $fechaDesde, $fechaHasta, $cantidad, $user, $listados) {
            
                            //--------------------------------------------------------------
                $variable = [];
                $n = 1;

                array_push($variable, array($farmacia->nombre));
                array_push($variable, array("Reporte de Laboratorio"));
                array_push($variable, array("Fecha Desde: " . $fechaDesde));
                array_push($variable, array("Fecha Hasta: " . $fechaHasta));
                array_push($variable, array("Total: " . $cantidad . " registros"));
                array_push($variable, array("Usuario : " . $user));
                array_push($variable, array(""));
                array_push($variable, array(
                    "N",
                    "PRIORIDAD",
                    "NRO. PRESTACIÓN",
                    "NRO. EX. LABORATORIO",
                    "TIPO DE ATENCIÓN",
                    "ESPECIALIDAD",
                    "HORA REGISTRO",
                    "FECHA ORDEN",
                    "TIPO DOC.",
                    "NRO. DOC.",
                    "BENEFICIARIO",
                    "MÉDICO",
                    "REFERIDO",
                    "PABELLÓN",
                    "PISO",
                    "HABITACIÓN",
                    "CAMA"
                ));
                try {
                    foreach ($listados as $r) { 
                    
                        if ($r->id_tipo_atencion == 2) {
                            $prioridad = $r->nom_prioridad;
                        } else {
                            $prioridad = " ";
                        }
                        if ($r->id_tipo_atencion == 1) {
                            $especialidad = $r->consultorio;
                        } elseif ($r->id_tipo_atencion == 2) {
                            $especialidad = $r->nom_especialidad_emergencia;
                        } else {
                            $especialidad = $r->consultorio;
                        }
                        $originalDate3 = $r->created_at;
                        $horaR = date("H:i:s", strtotime($originalDate3));
                        $originalDate1 = $r->firma_laboratorio;
                        $fechaE = date("d-m-Y", strtotime($originalDate1));
                        if ($r->id_tipo_atencion == 1) {
                            $referido = $r->referido; 
                        } else {
                            $referido = $r->unidad_policial == null ? "NO" : "SI"; 
                        }
                        if ($r->id_tipo_atencion == 2) {
                            $pabellon = $r->pabellon;
                        } else {
                            $pabellon = " ";
                        }
                        if ($r->id_tipo_atencion == 2) {
                            $piso = $r->piso;
                        } else {
                            $piso = " ";
                        }
                        if ($r->id_tipo_atencion == 2) {
                            $habitacion = $r->cuarto;
                        } else {
                            $habitacion = " ";
                        }
                        if ($r->id_tipo_atencion == 2) {
                            $cama = $r->cama;
                        } else {
                            $cama = " ";
                        }
                        array_push($variable, array(
                            $n++,
                            $prioridad,
                            $r->id_prestacion,
                            $r->id_lab,
                            $r->nom_tipo_atencion,
                            $especialidad,
                            $horaR,
                            $fechaE,
                            $r->tipo_doc_ident,
                            $r->nro_doc_ident,
                            $r->paterno_beneficiario . " " . $r->materno_beneficiario . " " . $r->nombre_beneficiario,
                            $r->paterno_medico . " " . $r->materno_medico . " " . $r->nombre_medico,
                            $referido,
                            $pabellon,
                            $piso,
                            $habitacion,
                            $cama
                        ));
                    }
                } catch (\Exception $e) {
                    $e->getMessage();
                } 

                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
            });
        });
            // Devuelve la URL del archivo Excel generado
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

    public function registrar_firma_kardex_enfermeria(Request $request)
    {
        $kardex_enfermeria_id = $request->id_kardex;
        $kardexUpdate = KardexEnfermerias::where("id", $kardex_enfermeria_id)->first();
        if (!isset($kardexUpdate)) {
            return response()->json([
                "message" => "No existe registro del kardex"
            ], 404);
        }
        $kardexUpdate->update([
            "ruta_firma" => "cf_kardex_enfermeria_{$kardex_enfermeria_id}.pdf",
            "fecha_firma" => Carbon::now(),
            "flag_firma" => 1
        ]);
        return response()->json([
            "message" => "Se actualizo la firma del kardex exitosamente"
        ], 200);
    }

