  public function genera_zip_alta_hospitalizacion(Request $request){
    $csv = $this->genera_nombre_csv();
    $obj = new Archive7z(public_path('tmp/zip/sin_firma/'.$csv.'.7z'));
    
    foreach($request->mov as $row) {
      $this->genera_pdf_alta_hospitalizacion($row, true);
      
      $obj->addEntry(public_path("/tmp/pdf/sin_firma/alta_hospitalizacion_{$row}.pdf")); 
    }

    $csv1 = $this->genera_nombre_csv();
    $obj1 = new Archive7z(public_path('tmp/zip/sin_firma/'.$csv1.'.7z'));
    
    foreach($request->mov as $row1) {
      $this->genera_hospitalizacion_epicrisis($row1, true);
      $obj1->addEntry(public_path("/tmp/pdf/sin_firma/hospitalizacion_epicrisis_{$row1}.pdf")); 
    }


    $resultado["csv"]=$csv;
    $resultado["sw"]=true;
    echo json_encode($resultado);
  }

  public function genera_hospitalizacion_epicrisis($id_hospitalizacion, $guardar = false)
    {
        $path = $this->valida_ruta_archivo_tmp();

        $model_hospitalizacion = new Hospitalizacione();
        $hospitalizacion = $model_hospitalizacion->getHospitalizacionById($id_hospitalizacion);
        $data_estancia = $model_hospitalizacion->GetDiasEstanciaByIdHospitalizacion($id_hospitalizacion);
        $dia_estancia = $data_estancia->dia_estancia;
        $servicios_concurrencia = null;
        if ($hospitalizacion->id_tipo_egreso == 1) {
            $servicios_concurrencia = $model_hospitalizacion->getServiciosConcurrenciaByIdHospitalizacion($id_hospitalizacion);
        }

        $model_establecimiento = new Establecimiento;
        $establecimiento = $model_establecimiento->GetById(Auth::user()->id_establecimiento);
        $nombre_establecimiento = $establecimiento[0]->nombre;

        $pdf = \PDF::loadView('pdf.firmar_hospitalizacion_epicrisis', compact('hospitalizacion','dia_estancia','servicios_concurrencia','nombre_establecimiento'));
        $pdf->getDomPDF()->set_option("enable_php", true);
        
        if ($guardar){
            file_put_contents($path."hospitalizacion-epicrisis_{$id_hospitalizacion}.pdf", $pdf->output());
        } else {
            return $pdf->stream('hospitalizacion_epicrisis.pdf');
        }
    }
