    public function registra_firma_informe_imagenologia(Request $request)
    {
        $cadena = "";
        $sw = false;
        $model_emergencia = new \App\Models\Emergencia;
        
        
        $model_prestacion = new \App\Models\Prestaciones;
        $model_radiologia = new \App\Models\Radiologia;
        $model_medico = new \App\Models\Medico;
        $model_consultorio = new \App\Models\Consultorio;
        $radiologia = $model_radiologia->GetRadiologiaById($request->id_resol);
        $procradiologia = $model_prestacion->obtenerPresProcePorIdServicioRadiologia($radiologia->id, 3, $request->id_servicio_radiologia, $request->id_pp);
        DB::beginTransaction();
            try {
                foreach($procradiologia as $row):
                    $fecha_firma_radio = date("d-m-Y H:i:s");
                    $ruta_radio = date("Y/m/d")."/cf_informe-imagenologia_".$row->id.".pdf";
                    $flag_radio = 1; //con token
                    $affected = DB::update("UPDATE prestacion_procedimientos SET  fecha_firma = ?, flag = ?, ruta_prestacion_procedimiento = ? WHERE id = ? ",
                                        [$fecha_firma_radio, $flag_radio, $ruta_radio, $row->id]);
                endforeach;

                DB::commit();
                $res = "Y";
