                        }
                    }
                }
                
                $sheet->fromArray($variable, null, '', false, false);
            });
        })->store('csv',public_path('tmp'.DIRECTORY_SEPARATOR.'csv'));

            $obj = new Archive7z(public_path('tmp'.DIRECTORY_SEPARATOR.'zip'.DIRECTORY_SEPARATOR.'sin_firma'.DIRECTORY_SEPARATOR.$csv.'.7z'));

            $model_prestacion = new \App\Models\Prestaciones;
            $model_radiologia = new \App\Models\Radiologia;
            $radiologia = $model_radiologia->GetRadiologiaById($request->mov[0]);
            $id_prestacion=$radiologia->id_prestacion;

            //$procradiologia = $model_radiologia->GetProcedimientosByIdPrestacionAndIdLabRadAndTipoAndIdServicioRadInformeAdicional($id_prestacion, $request->mov[0], 3, $request->id_servicio_radiologia, $request->id_pp, $request->id_informe_adicional);
            $procradiologia = $model_radiologia->GetProcedimientosByIdPrestacionAndIdLabRadAndTipoAndIdServicioRadInformeAdicional($request->mov[0],$request->id_servicio_radiologia, $request->id_pp, $request->id_informe_adicional);
                
            if(isset($procradiologia)){
                foreach($procradiologia as $row) {
