    public function genera_pdf_informe_imagenologia_adicional($prestacion, $radiologia, $id_prestacion,$id_radiologia, $id_servicio_radiologia, $idpp, $guardar = false, $id_informe_adicional){
        $path = $this->valida_ruta_archivo_tmp();

        $model_radiologia = new \App\Models\Radiologia;
        $model_medico = new \App\Models\Medico;
        $procradiologia = $model_radiologia->GetProcedimientosByIdRadiologiaAndIdServicioRadiologiaInformeAdicional($id_prestacion,$id_radiologia,$id_servicio_radiologia,$idpp,$id_informe_adicional);
        
        $medico = "";

        if (!empty($procradiologia[0]->dni_medico_validacion_act)):
            $medico = $model_medico->GetMedicoByDNI($procradiologia[0]->dni_medico_validacion_act);
        endif;

        $carpeta = date("Y")."/".date("m")."/".date("d");
        $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_informe-imagenologia-adicional_".$id_informe_adicional.".pdf";
        $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_informe-imagenologia-adicional_".$id_informe_adicional.".pdf");
        
        $pdf = \PDF::loadView('pdf.examen_radiologia_lns_adicional',compact('prestacion','radiologia','procradiologia','medico','codigo_qr','url_descarga','id_radiologia'));
        $pdf->getDomPDF()->set_option("enable_php", true);

        if ($guardar){
          file_put_contents($path."informe-imagenologia-adicional_{$id_informe_adicional}.pdf", $pdf->output());
          if (File::exists($path . "informe-imagenologia-adicional_{$id_informe_adicional}.pdf")) {
            // Si existe, registrar en el log que el archivo se generó correctamente
            Log::info("El archivo PDF se generó y guardó correctamente: informe-imagenologia-adicional_{$id_informe_adicional}.pdf");
        } else {
            // Si no existe, registrar en el log un mensaje de error
            Log::error("Error al generar o guardar el archivo PDF: informe-imagenologia-adicional_{$id_informe_adicional}.pdf");
        }
        } else {
          return $pdf->stream('informe-imagenologia-adicional.pdf');
        }
    }

