        $cantidad = count($radiologias);
        /////////////////////////////////////////////////////////////////////////////////////////////////////

        $excelName = 'Exportar_Reporte_de_Imagenes_' . auth()->user()->id . '_' . Carbon::now()->format('Y-m-d_H-i-s');
        $excelNameResponse = 'Exportar_Reporte_de_Imagenes_' . auth()->user()->id . '_' . Carbon::now()->format('Y-m-d_H-i-s') . '.xlsx';
        //dd($radiologias);
        //$excel = Excel::create($excelName, function ($excel) use ($fechaDesde, $fechaHasta,$fechaoDesde, $fechaoHasta,$fechamDesde,$id_establecimiento, $fechamHasta, $cantidad, $radiologias, $estado_muestra,$estado_informe) {
        $excel = Excel::create($excelName, function ($excel) use ($fecha_desde, $fecha_hasta, $id_establecimiento, $cantidad, $radiologias,$id_tipo_atencion) {
            // $excel->sheet('GENERAL', function ($sheet) use ($fechaDesde, $fechaHasta,$fechaHasta,$fechaoDesde, $fechaoHasta,$fechamDesde,$fechamHasta,$id_establecimiento, $cantidad, $radiologias, $estado_muestra,$estado_informe) {
            $excel->sheet('GENERAL', function ($sheet) use ($fecha_desde, $fecha_hasta, $id_establecimiento, $cantidad, $radiologias,$id_tipo_atencion) {
            
            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                $variable = [];
                $n = 1;

                array_push($variable, array("REPORTE DE IMÁGENES"));
                array_push($variable, array("Fecha Orden Desde: " . $fecha_desde. "   "."Fecha Orden Hasta: ".$fecha_hasta));
                array_push($variable, array("Total: " . $cantidad . " registros"));
                array_push($variable, array("Usuario : " . auth()->user()->paterno . " ".auth()->user()->materno.",".auth()->user()->name));
                array_push($variable, array(""));
                //24campos
                array_push($variable, array(
                    "N",
                    "ESTABLECIMIENTO",
                    "MÉDICO SOLICITANTE",
                    "FECHA ORDEN",
                    "FECHA CITA",
                    "HORA CITA",
                    "FECHA MUESTRA",
                    "HORA MUESTRA",
                    "FECHA INFORME",
                    "HORA INFORME",
                    "FECHA FIRMA",
                    "HORA FIRMA",
                    "TIPO DE ATENCIÓN",
                    "SERVICIO ATENCIÓN",
                    "CONSULTORIO ATENCIÓN",
                    "SERVICIO DE IMÁGENES",
                    "CIE-10",
                    "DIAGNÓSTICO",
                    "CÓDIGO CPMS",
                    "DESCRIPCIÓN CPMS ",
                    "LADO",
                    "PACIENTE",
                    "SEXO",
                    "PARENTESCO",
                    "FECHA DE NACIMIENTO",
                    "EDAD",
                    "TIPO DE DOC.",
                    "NRO. DOC.",
                    "REFERIDO",
                    "ADENDA",    
                    "ESTADO CITA",
                    "ESTADO TOMA DE MUESTRA",
                    "ESTADO INFORME",
                ));
                $sheet->setAutoFilter('A7:AG7');
                $sheet->cells('A7:AG7', function($cells) {
                    $cells->setBackground('#CEFF9E');   
                    $cells->setFontColor('#000000ff');    
                    $cells->setFontWeight('bold');           
                });
                try {
                    foreach ($radiologias as $r) { 
                        // ============================== VALORES DEFINIDOS ===============================
                        array_push($variable, array(
                            $n++,
                            $r->establecimiento,
                            $r->medico_solicitante,
