    public function genera_hospitalizacion_papeleta_egreso($id_hospitalizacion, $guarda = false){
        $path = $this->valida_ruta_archivo_tmp();
        
        $id_establecimiento=Auth::user()->id_establecimiento;

        $model_hospitalizacion = new Hospitalizacione();
        $hospitalizacion = $model_hospitalizacion->getDatosPapeletaEgreso($id_hospitalizacion);

        $date = Carbon::now();
        $fechaActual = $date->format('d/m/Y');
        $horaActual = $date->format('H:i:s');

        $dias_estancia = 0;
        $fecha_ingreso = Carbon::createFromFormat('d/m/Y', $hospitalizacion->fecha_ingreso);

        /* CALCULAR ESTANCIA EN HOSPITAL EN BASE A ALTA MEDICA*/

        $fecha_alta_administrativa = Carbon::createFromFormat('d/m/Y', $hospitalizacion->fecha_alta_medica);
        $dias_calculados = $fecha_alta_administrativa->diffInDays($fecha_ingreso);
        
        $dias_estancia = $dias_calculados + 1;

        $user_actual = Auth::user();
            
        $asegurado = DB::table('asegurados')
            ->leftJoin('distritos', 'asegurados.id_distrito','=','distritos.id_distrito')
            ->leftJoin('provincias', 'distritos.id_provincia','=','provincias.id_provincia')
            ->leftJoin('departamentos', 'provincias.id_departamento','=','departamentos.id_departamento')
            ->leftJoin('distritos as distrito_nacimiento', 'asegurados.id_distrito_nacimiento','=','distrito_nacimiento.id_distrito')
            ->leftJoin('provincias as provincia_nacimiento', 'distrito_nacimiento.id_provincia','=','provincia_nacimiento.id_provincia')
            ->leftJoin('departamentos as departamento_nacimiento', 'provincia_nacimiento.id_departamento','=','departamento_nacimiento.id_departamento')
            ->leftJoin('distritos as distrito_procedencia', 'asegurados.id_distrito_procedencia','=','distrito_procedencia.id_distrito')
            ->leftJoin('provincias as provincia_procedencia', 'distrito_procedencia.id_provincia','=','provincia_procedencia.id_provincia')
            ->leftJoin('departamentos as departamento_procedencia', 'provincia_procedencia.id_departamento','=','departamento_procedencia.id_departamento')
            ->leftJoin('razas', 'asegurados.id_raza','=','razas.id')
            ->leftJoin('estado_civiles', 'asegurados.id_estado_civil','=','estado_civiles.id')
            ->leftJoin('grado_instrucciones', 'asegurados.id_grado_instruccion','=','grado_instrucciones.id')
            ->leftJoin('ocupaciones', 'asegurados.id_ocupacion','=','ocupaciones.id')
            ->leftJoin('religiones', 'asegurados.id_religion','=','religiones.id')
            ->select('asegurados.*', 'distritos.descripcion as distrito', 'provincias.descripcion as provincia', 'departamentos.descripcion as departamento', 'razas.nombre as etnia',
                'estado_civiles.nombre as estado_civil', 'grado_instrucciones.nombre as grado_instruccion', 'ocupaciones.nombre as ocupacion', 'religiones.nombre as religion',
                'distrito_nacimiento.descripcion as distrito_nacimiento2', 'provincia_nacimiento.descripcion as provincia_nacimiento2', 'departamento_nacimiento.descripcion as departamento_nacimiento2',
                'distrito_procedencia.descripcion as distrito_procedencia2', 'provincia_procedencia.descripcion as provincia_procedencia2', 'departamento_procedencia.descripcion as departamento_procedencia2')
            ->where('asegurados.id',$hospitalizacion->id_asegurado)
            ->where('asegurados.id_estado_reg', 1)
            ->first();

        $titular = null;
        $persona_datos_adicionales = null;
        $grado = null;

        if ($asegurado->id_asegurado_titular != null || $asegurado->id_asegurado_titular > 0) {
            $titular = DB::table('asegurados')
                ->select('asegurados.*')
                ->where('id',$asegurado->id_asegurado_titular)
                ->where('id_estado_reg', 1)
                ->first();
            
            if ($titular != null) {
                $persona_datos_adicionales = DB::table('persona_datos_adicionales')
                    ->select('persona_datos_adicionales.*')
                    ->where('id_asegurado',$titular->id)
                    ->first();
                if ($persona_datos_adicionales != null) {
                    $grado = DB::table('titular_grados')
                    ->select('titular_grados.*')
                    ->where('id',$persona_datos_adicionales->id_grado)
                    ->first();
                }
            }
        }
        $concurrencias = DB::table('hospitalizacion_concurrencias as hc')
                ->join('consultorios as c', 'c.id', '=', 'hc.id_servicio')
                ->select('hc.id', 'hc.id_hospitalizacion', 'hc.id_servicio', 'c.nombre')
                ->where('hc.id_hospitalizacion', $id_hospitalizacion)
                ->where('hc.id_estado_reg', 1)
                ->get();

        $pdf = \PDF::loadView('pdf.hospitalizacion_papeleta_egreso',
                [
                    'asegurado' => $asegurado,
                    'concurrencias' => $concurrencias,
                    'dias_estancia' => $dias_estancia,
                    'fechaActual' => $fechaActual,
                    'grado' => $grado,
                    'horaActual' => $horaActual,
                    'hospitalizacion'=> $hospitalizacion,
                    'persona_datos_adicionales' => $persona_datos_adicionales,
                    'titular' => $titular,
                    'user_actual' => $user_actual
                ]
        );

        $pdf->getDomPDF()->set_option("enable_php", true);
        if ($guarda){
            Log::info("genera_hospitalizacion_papeleta_egreso", ["guardar" => true]);
            file_put_contents($path."hospitalizacion-papeleta-egreso_{$id_hospitalizacion}.pdf", $pdf->output());
        } else {
            Log::info("genera_hospitalizacion_papeleta_egreso", ["guardar" => false]);
            return $pdf->stream("papeleta_egreso_$id_hospitalizacion.pdf");
        }
    }

    public function exportar_reporte_atencion_detallado_emergencia_consejeria($id_user, $fecha_ini, $fecha_fin, $fecha_ini_registro, $fecha_fin_registro, $num_documento, $estado, $id_medico,
        $id_servicio_destino, $busqueda_datos, $tipo_atencion) {
    
        if ($fecha_ini == "0") $fecha_ini = "";
        if ($fecha_fin == "0") $fecha_fin = "";
        if ($fecha_ini_registro == "0") $fecha_ini_registro = "";
        if ($fecha_fin_registro == "0") $fecha_fin_registro = "";
        if ($num_documento == "0") $num_documento = "";
        if ($busqueda_datos == "0") $busqueda_datos = "";

        Excel::create('Exportar Reportes de Atenciones Emergencias Consejería', function ($excel) use ($id_user, $fecha_ini, $fecha_fin, $fecha_ini_registro, $fecha_fin_registro, $num_documento,
            $estado, $id_medico, $id_servicio_destino, $busqueda_datos, $tipo_atencion) {

            $modelfarma = new Farmacia;
            $farmacia = $modelfarma->GetFarmaByUser($id_user);
            $model_medico = new \App\Models\Medico();
            $model_consejeria = new \App\Models\Consejeria();
            $model_usuario = new User;
            $model_establecimiento = new Establecimiento;

            $usuario = $model_usuario->GetById($id_user);
            $nombre_usuario = $usuario->paterno . " " . $usuario->materno . " " . $usuario->name;

            $establecimiento = $model_establecimiento->GetById(Auth::user()->id_establecimiento);
            $nombre_establecimiento = $establecimiento[0]->nombre;

            $consejeria = $model_consejeria->all_emergencia_consejeria_ajax_params(
                $fecha_ini,
                $fecha_fin,
                $fecha_ini_registro,
                $fecha_fin_registro,
                $num_documento,
                $id_servicio_destino,
                $busqueda_datos,
                $estado,
                1,
                1000
            );

            $nro_consejerias = isset($consejeria[0]->totalrows) ? $consejeria[0]->totalrows : 0;

            $variable = [];
            array_push($variable, [$nombre_establecimiento]);
            array_push($variable, ["Reporte de Atenciones Emergencias Consejería"]);
            array_push($variable, ["Fecha Solicitud Desde: " . $fecha_ini]);
            array_push($variable, ["Fecha Solicitud Hasta: " . $fecha_fin]);
            array_push($variable, ["Fecha Registro Inicio: " . $fecha_ini_registro]);
            array_push($variable, ["Fecha Registro Fin: " . $fecha_fin_registro]);
            array_push($variable, ["Total: " . $nro_consejerias . " Atenciones de consejería"]);
            array_push($variable, ["Usuario: " . $nombre_usuario]);
            array_push($variable, [""]);

            array_push($variable, [
                "N°", "FECHA INGRESO DE EMERGENCIAS", "HORA INGRESO DE EMERGENCIAS", "FECHA ATENCION", "HORA ATENCION", "TIPO DOC", "NUMERO DOC",
                "NUMERO HISTORIA", "PACIENTE", "PARENTESCO", "SEXO", "FECHA NACIMIENTO", "EDAD",
                "APELLIDOS Y NOMBRES PACIENTE", "GRADO DEL TITULAR", "SEXO", "EDAD", "TIPO DE ORIGEN",
                "UPSS A CARGO", "SERVICIO A CARGO", "SERVICIO DESTINO", "CAMA", "PABELLON",
                "PROFESIONAL DE SALUD", "TIPO DOC PROFESIONAL", "NRO DOC PROFESIONAL",
                "DEPARTAMENTO", "CODIGO UPSS ESPECIALIDAD", "DIAGNÓSTICOS", "TIPO DIAGNÓSTICO", "PROCEDIMIENTOS", "TOTAL DE PROCEDIMIENTOS","FIRMADO"
            ]);

            $n = 1;
            foreach ($consejeria as $l) {
                array_push($variable, [
                    $n++, $l->fecha_ingreso, $l->hora_ingreso, $l->fecha_atencion, $l->hora_atencion, $l->tipo_doc_ident,
                    $l->dni_beneficiario, $l->nro_historia, $l->paterno_beneficiario . ' ' . $l->materno_beneficiario . ', ' . $l->nombre_beneficiario,
                    $l->tipo_beneficiario, $l->sexo, $l->fecha_nac, $l->edadpaciente,
                    $l->paterno_beneficiario . ' ' . $l->materno_beneficiario . ', ' . $l->nombre_beneficiario,
                    $l->grado, $l->sexo, $l->edadpaciente, $l->tipo_origen, $l->codigo . ' - ' . $l->codigo_upss, $l->servicio_cargo, $l->servicio_destino,
                    $l->cama, $l->pabellon, $l->medico_paterno . ' ' . $l->medico_materno . ' ' . $l->medico_nombre,
                    $l->medico_tipo_documento, $l->medico_dni, $l->departamento, $l->codigo_upss_especialidad,
                    $l->codigo_diagnostico . ' - ' . $l->nombre_diagnostico, $l->tipo_diagnostico,
                    $l->codigo_procedimiento . ' - ' . $l->nombre_procedimiento, $l->cantidad_procedimientos, $l->flag_firma == '[V]' ? 1 : ''
                ]);
            }

            $excel->sheet('Reporte', function ($sheet) use ($variable) {
                $sheet->fromArray($variable, null, 'A1', false, false);
                $sheet->setAutoSize(true);

                $sheet->mergeCells('A1:AA1');
                $sheet->mergeCells('A2:AA2');
                $sheet->mergeCells('A3:AA3');
                $sheet->mergeCells('A4:AA4');
                $sheet->mergeCells('A5:AA5');
                $sheet->mergeCells('A6:AA6');

                $sheet->cells('A7:AA7', function ($cells) {
                    $cells->setFontWeight('bold');
                    $cells->setAlignment('center');
                });
            });

        })->export('xls');
    
    }


    public function genera_alta_hosp_csv(Request $request){
      
        $path = public_path('tmp/csv');
        $path_zip = public_path('tmp/zip');
    
        if (!is_dir($path)) {
            mkdir($path);
        }

        if (!is_dir($path_zip)) {
            mkdir($path_zip);
            mkdir(public_path('tmp/zip/firmados'));
            mkdir(public_path('tmp/zip/sin_firma'));
        }
        
        $csv = "";
        if (Auth::check()):
            $csv .= Auth::user()->id;
        endif;
        //$csv = Auth::user()->id;
        $csv .= "_".date("YmdHis");

        
        Excel::create($csv, function($excel) use($request){
            $excel->sheet('GENERAL', function($sheet) use($request) {
                $model_hospitalizacion = new Hospitalizacione();
                $variable = [];
                Log::info("Excel::create", ["foreach()" => "Antes de entrar al bucle"]);
                foreach($request->mov as $row):
                    Log::info("Excel::create", ["foreach()" => "Entro al bucle"]);  
                    // ALTA
                    if ($row != 4419) {
                        $this->genera_pdf_alta_hospitalizacion($row, true);
                        array_push($variable, array(url().'/tmp/pdf/sin_firma/alta-hospitalizacion_'.$row.'.pdf', url().'/upload_firma/?name=cf_alta-hospitalizacion_'.$row.'.pdf&id_tipo=prestacion&id_resol='.$row, 'cf_alta-hospitalizacion_'.$row.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().'/images/escudo.jpg','1','7'));
                    }
                    // EPICRISIS
                    $this->genera_hospitalizacion_epicrisis($row, true);
                    array_push($variable, array(url().'/tmp/pdf/sin_firma/hospitalizacion-epicrisis_'.$row.'.pdf', url().'/upload_firma/?name=cf_hospitalizacion-epicrisis_'.$row.'.pdf&id_tipo=prestacion&id_resol='.$row, 'cf_hospitalizacion-epicrisis_'.$row.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().'/images/escudo.jpg','1','7'));

                    // PAPELETA DE EGRESO
                    $papeleta_egreso = $model_hospitalizacion->getDatosPapeletaEgreso($row);
                    if(isset($papeleta_egreso)){
                        $this->genera_hospitalizacion_papeleta_egreso($row, true);
                        array_push($variable, array(url().'/tmp/pdf/sin_firma/hospitalizacion-papeleta-egreso_'.$row.'.pdf', url().'/upload_firma/?name=cf_hospitalizacion-papeleta-egreso_'.$row.'.pdf&id_tipo=prestacion&id_resol='.$row, 'cf_hospitalizacion-papeleta-egreso_'.$row.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().'/images/escudo.jpg','1','7'));
                    }

                endforeach;
                $sheet->fromArray($variable, null, '', false, false);
            });
        })->store('csv',public_path('tmp/csv'));

            $obj = new Archive7z(public_path('tmp/zip/sin_firma/'.$csv.'.7z'));

            $model_hospitalizacion = new Hospitalizacione();
          
            foreach($request->mov as $row){
                //ALTA
                if ($row != 4419) {
                $obj->addEntry(public_path("/tmp/pdf/sin_firma/alta-hospitalizacion_{$row}.pdf"));
                } 
                //EPICRISIS
                $obj->addEntry(public_path("/tmp/pdf/sin_firma/hospitalizacion-epicrisis_{$row}.pdf")); 
                //PAPELETA
                $papeleta_egreso = $model_hospitalizacion->getDatosPapeletaEgreso($row);
                if(isset($papeleta_egreso)){
                    $obj->addEntry(public_path("/tmp/pdf/sin_firma/hospitalizacion-papeleta-egreso_{$row}.pdf")); 
                }
            }
        
	    $resultado["csv"]=$csv;
        $resultado["sw"]=true;
        echo json_encode($resultado);
    }

