    public function genera_pdf_traslado($id_evaluacion)
    {
        $path = $this->valida_ruta_archivo_tmp();
        
        $evaluacion = Evaluacione::find($id_evaluacion);
        
        $prestacion = DB::table('prestaciones as p')
            ->join('asegurados as a', 'p.id_asegurado', '=', 'a.id')
            ->join('tipo_beneficiarios as tb', 'a.id_tipo_beneficiario', '=', 'tb.id')
            ->join('asegurado_historias as ah', function($join) { $join->on('ah.id_asegurado', '=', 'a.id')->on('ah.id_establecimiento', '=', 'p.id_establecimiento'); })
            ->where('p.id', $evaluacion->id_prestacion)
            ->select('p.id as id_evaluacion', 'a.id as id_asegurado', 'a.nro_doc_ident as nro_doc_ident_asegurado', 'a.nombre as asegurado_nombre', 'a.paterno as asegurado_paterno', 'a.materno as asegurado_materno', 'a.id_tipo_beneficiario',
                'tb.codigo as tipo_beneficiario_codigo', 'tb.descripcion as tipo_beneficiario_descripcion', 'ah.id as id_asegurado_historias', 'ah.nro_historia',
                DB::raw("TO_CHAR(p.fecha_atencion::date, 'DD-MM-YYYY HH24:MI:SS') AS fecha_atencion"))
            ->limit(1)
            ->first();        
        
        $cambioCamaModel = new CambioCama();
        $traslado = $cambioCamaModel->getTrasladoByIdEvolucion($id_evaluacion);
        
        $model_prestacion = new Prestaciones(); 
        $diagnosticos_ingreso = $model_prestacion->GetDiagnosticoByIdPrestacionEmergencia($evaluacion->id_prestacion);

        $receta_diagnostico_model = new Receta_diagnostico();
        $diagnosticos_traslado = $receta_diagnostico_model->getDiagnosticosTrasladoByIdCambioCama($traslado->id);
        
        $model_establecimiento = new Establecimiento;

        $establecimiento = $model_establecimiento->GetById(Auth::user()->id_establecimiento);
        $nombre_establecimiento = $establecimiento[0]->nombre;

        //dato hospi, dato de admision
        $hospitalizacion = DB::table('hospitalizaciones as h')->where('h.id', $evaluacion->id_emergencia)->select(
            DB::raw("to_char(h.fecha_ingreso::date,'DD-MM-YYYY') as fecha_ingreso"), 
            DB::raw("to_char(h.hora_ingreso::time,'HH:MI:SS') as hora_ingreso")
        )->first();
        
        
        //$hospitalizacion = $model_receta->getHospitalizacionById_farmacia_new_x($evaluacion->id_emergencia);
        $primer_prestacion = Prestaciones::where('id_ext', $evaluacion->id_emergencia)->whereRaw("COALESCE(flag_intervencion_quirurgica, false) = false")->where('id_tipo_atencion', 3)->where('id_estado_reg', 1)->orderBy('id', 'asc')->first();
        if($primer_prestacion->id == $evaluacion->id_prestacion ):
            $prestacion->fecha_atencion = $hospitalizacion->fecha_ingreso.' '.$hospitalizacion->hora_ingreso;
        else:
            //Busca primer traslado
                $evaluacion_h = DB::table('evaluaciones as e')->where('e.id_emergencia', $evaluacion->id_emergencia)->where('e.flag_orden_traslado', 1)->select(
                    DB::raw("to_char(e.created_at::date,'DD-MM-YYYY') as fecha_ingreso"), 
                    DB::raw("to_char(e.created_at::time,'HH:MI:SS') as hora_ingreso")
                )->orderBy('id', 'desc')->offset(1)->first();
            
                $prestacion->fecha_atencion = $evaluacion_h->fecha_ingreso.' '.$evaluacion_h->hora_ingreso;
        endif;

        

        $carpeta = date("Y")."/".date("m")."/".date("d");
        $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_orden_traslado_".$id_evaluacion.".pdf";
        $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_orden_traslado_" . $id_evaluacion . ".pdf");
        $pdf = \PDF::loadView('pdf.hospitalizacion_orden_traslado_firma', compact("evaluacion", "prestacion", "traslado", "diagnosticos_ingreso", "diagnosticos_traslado", "url_descarga", "codigo_qr","nombre_establecimiento"));
        $pdf->setPaper('A4', 'portrait');
        $pdf->getDomPDF()->set_option("enable_php", true);
        file_put_contents($path."orden_traslado_".$id_evaluacion. ".pdf", $pdf->output());
    }

    public function exportar_lista_interconsulta($id_user, $fecha_ini, $fecha_fin, $num_documento, $apellidos_nombres, $estado, $id_medico, $id_servicio, $tipo_atencion)
    {
        if ($fecha_ini == "0") $fecha_ini = "";
        if ($fecha_fin == "0") $fecha_fin = "";
        if ($num_documento == "0") $num_documento = "";
        if ($apellidos_nombres == "0") $apellidos_nombres = "";

        Excel::create('Exportar Lista de Interconsulta', function($excel) use($id_user, $fecha_ini, $fecha_fin, $num_documento, $apellidos_nombres, $estado, $id_medico, $id_servicio, $tipo_atencion) {
            $excel->sheet('GENERAL', function($sheet) use($id_user, $fecha_ini, $fecha_fin, $num_documento, $apellidos_nombres, $estado, $id_medico, $id_servicio, $tipo_atencion) {
				
				$modelfarma = new Farmacia;
				$farmacia = $modelfarma->GetFarmaByUser($id_user);
                $establecimiento = $modelfarma->GetEstablecimientoPNP($farmacia->id);

                $model_usuario = new User;
				$usuario = $model_usuario->GetById($id_user);
                $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;
				
				$p[]=Auth::user()->id_establecimiento;
                $p[]=$fecha_ini;
				$p[]=$fecha_fin;
				$p[]=$num_documento;
				$p[]=strtoupper($apellidos_nombres);
				$p[]=$estado;
                $p[]=$id_medico;
				$p[]=$id_servicio;
				$p[]=1;
				$p[]=50000;
				
                $data = null;
                $model_interconsulta = new \App\Models\Interconsulta;
                if ($tipo_atencion == "3") {
                    $data = $model_interconsulta->listar_interconsulta_hospitalizacion_ajax($p);
                } else {
                    $data = $model_interconsulta->listar_interconsulta_ajax($p);
                }
                $cant_registros = isset($data[0]->totalrows) ? $data[0]->totalrows : 0;  
         
                $variable = [];
                $n = 1;
                array_push($variable, array($establecimiento->nombre));
                array_push($variable, array("Reporte de Interconsultas"));
                array_push($variable, array("Fecha Solicitud Desde: " . $fecha_ini));
				array_push($variable, array("Fecha Solicitud Hasta: " . $fecha_fin));
                array_push($variable, array("Total: " . $cant_registros . " registro(s)"));
                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array(""));
                array_push($variable, array("N°","FECHA SOLICITUD", "HORA SOLICITUD", "FECHA Y HORA REGISTRO SOLICITUD", "FECHA Y HORA RESPUESTA", "TIPO ATENCIÓN", "AREA (UBICACIÓN)", "SALA (UBICACIÓN)", "CAMA (UBICACIÓN)", "PROFESIONAL SOLICITANTE", "SERVICIO DE INTERCONSULTA", "PROFESIONAL QUE RESPONDE LA INTERCONSULTA","N° DOCUMENTO PACIENTE", "APELLIDOS Y NOMBRES PACIENTE", "PARENTESCO", "GRADO DEL TITULAR", "SEXO", "EDAD", "CODIGO SITEDS"));
                foreach ($data as $r) {
                    $fecha_rpta_atencion = $r->fecha_rpta_atencion != null ? $r->fecha_rpta_atencion : "";
                    $tipo_atencion = $r->tipo_atencion;
                    if ($r->id_evaluacion != 0) {
                        $tipo_atencion .= $r->id_tipo_atencion == 3 ? " - Evolución" : " - Evaluacion";
                    }
                    $area = $r->id_tipo_atencion == 3 ? "" : $r->nombre_area;
                    $sala = $r->id_tipo_atencion == 3 ? $r->nombre_area : $r->cuarto;
                    $cama = $r->cama;

                    array_push($variable, array($n++,$r->fecha_atencion, $r->hora_atencion, $r->created_at, $fecha_rpta_atencion,$tipo_atencion, $area, $sala, $cama, $r->paterno_medico.' '.$r->materno_medico.', '.$r->nombre_medico, $r->nombre_consultorio, $r->paterno_medico2.' '.$r->materno_medico2.', '.$r->nombre_medico2, $r->nro_doc_ident, $r->paterno.' '.$r->materno.', '.$r->nombre, $r->parentesco, $r->grado, $r->sexo, $r->edadpaciente, $r->siteds_emergencia));
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
            });
        })->export('xls');
    }
    
    /**
     * Firma sin token de Interconsulta Respuesta
     */
    public function sinTokensInterconsultaRpta(Request $request) {
        // proviene_formulario = 1 : Atencion Emergencia
        // proviene_formulario = 2 : Evaluacion Emergencia
        // proviene_formulario = 3 : Atencion y evolucion de Hospitalizacion
        // proviene_formulario_hosp = 1 : Atencion hospitalizacion
        // proviene_formulario_hosp = 2 : Evolucion hospitalizacion

        $firma_exitosa = false;
        $id_interconsulta_error = 0;

        DB::beginTransaction();
        try {
            foreach ($request->mov as $row):

                // Id interconsulta actual, sirve para mapear en log
                $id_interconsulta_error = $row;

                $interconsulta = App\Models\Interconsulta::find($row);
                if ($interconsulta->fecha_rpta_firma_interconsulta == ""){
                    $interconsulta->fecha_rpta_firma_interconsulta = date("d-m-Y H:i:s");
                    $interconsulta->ruta_rpta_interconsulta = date("Y/m/d")."/cf_interconsulta_rpta_".$row.".pdf";
                    $interconsulta->flag_rpta = 2; //sintoken
                    $interconsulta->save();
                }

                $model_receta = new Receta_vale();
                $recetas = $model_receta->GetRecetasByIdInterconsulta($row);
                
                if (!empty($recetas)):
                    // 
                    foreach ($recetas as $rv):
                        $receta = Receta_vale::find($rv->id);
                        for ($i = 0; $i < count($recetas); $i++):
                            if ($receta->fecha_firma == ""){
                                $receta->fecha_firma = date("d-m-Y H:i:s");
                                $receta->ruta_receta = date("Y/m/d")."/cf_receta_".$receta->id.".pdf";
                                $receta->flag = 2; //sintoken
                                $receta->save();
                            }
                        endfor;
                    endforeach;
                endif;
                
                $model_laboratorio = new Laboratorio();
                $laboratorios = $model_laboratorio->GetLaboratorioByIdInterconsulta($row);

                if (!empty($laboratorios)) {
                    foreach ($laboratorios as $lab) {
                        $laboratorio = Laboratorio::where('id', '=', $lab->id)->first();
                        for ($i = 0; $i < count($laboratorios); $i++) {
                            if ($laboratorio->fecha_firma == "") {
                                $laboratorio->fecha_firma = date("d-m-Y H:i:s");
                                $laboratorio->ruta_laboratorio = date("Y/m/d")."/cf_laboratorio_".$laboratorio->id.".pdf";
                                $laboratorio->flag = 2; //sintoken
                                $laboratorio->save();
                            }
                        }
                    }
                    // $respuesta = $model_laboratorios->insertarFlagCitaLaboratorio($row);
                }

                $model_radiologia = new App\Models\Radiologia();
                $radiologias = $model_radiologia->GetRadiologiaByIdInterconsulta($row);

                if (!empty($radiologias)) {
                    foreach ($radiologias as $rad) {
                        $radiologia = App\Models\Radiologia::where('id', '=', $rad->id)->first();
                        for ($i = 0; $i < count($radiologias); $i++) {
                            if ($radiologia->fecha_firma == "") {
                                $radiologia->fecha_firma = date("d-m-Y H:i:s");
                                $radiologia->ruta_radiologia = date("Y/m/d")."/cf_radiologia_".$radiologia->id.".pdf";
                                $radiologia->flag = 2; //sintoken
                                $radiologia->save();
                            }
                        }
                    }
                }
                
            endforeach;
            
            DB::commit();
            $firma_exitosa = true;

        } catch (\Exception $e) {
            DB::rollback();
            Log::error("Firma Sin Token Interconsulta Rpta => id_interconsulta: " . $id_interconsulta_error . 
                "\n\nmensaje: " . $e->getMessage() . 
                "\n\ndatos del request: " . json_encode($request->all())
            );
        } catch (\Throwable $th) {
            DB::rollback();
            Log::critical("Firma Sin Token Interconsulta Rpta => id_interconsulta: " . $id_interconsulta_error . 
                "\n\nmensaje: " . $th->getMessage() . 
                "\n\ndatos del request: " . json_encode($request->all())
            );
        }

        echo $firma_exitosa;
    }

    public function exportar_reporte_hoja_his($id_atencion, $id_medico, $id_servicio, $fecha_atencion ) {

        $excelName = 'Reporte_Hoja_HIS'. $id_medico. '_' . Carbon::now()->format('Y-m-d_H-i-s');
        $excelNameResponse = 'Reporte_Hoja_HIS_'. $id_medico . '_' . Carbon::now()->format('Y-m-d_H-i-s'). '.xlsx';
        $excel =Excel::create($excelName , function($excel) use($id_atencion, $id_medico, $id_servicio, $fecha_atencion) {
        $excel->sheet('GENERAL', function($sheet) use($id_atencion, $id_medico, $id_servicio, $fecha_atencion) {
                
        $variable = [];
        $n = 1;


    
            if($id_atencion!=0 && $id_medico!=0):
          
                if($id_atencion==2){
                    $id_servicio = 76;
                }
                $model_consultorio = new Consultorio;
                $upss = $model_consultorio->ShowCodigoUpssIdTipoAtencion($id_servicio,$id_atencion);
                
                if(count($upss)>0):
                  
                    
                    $id_servicio=$upss[0]->id_consultorio;
                    $codigo_upss=$upss[0]->codigo;
                    $nombre_upss=$upss[0]->nombre;

                    $dni_medico=Auth::user()->dni;
                    $id_establecimiento=Auth::user()->id_establecimiento;

                    $model_establecimiento = new Establecimiento();
                    $establecimiento = $model_establecimiento->GetByIdEstablecimiento($id_establecimiento);

                    $modelmedico = new Medico();
                    
                    if(Auth::user()->flagservicios==1 || Auth::user()->identificativo==1){
                        $medico = $modelmedico->GetMostrarMedicoById($id_medico);    
                    }else
                    {
                        $medico = $modelmedico->GetMostrarMedicoByDNI($dni_medico);    
                    }

                
                    if($id_atencion==3){
                      $prestaciones = $modelmedico->GetMostrarAtencionesMedicoByHISHO($id_atencion,$id_establecimiento,$fecha_atencion,$id_medico, $id_servicio);
                      
                    }
                    else{
                      $prestaciones = $modelmedico->GetMostrarAtencionesMedicoByHIS($id_atencion,$id_establecimiento,$fecha_atencion,$id_medico, $id_servicio);
                    }
                    
                    switch ($id_atencion) {
                        case '1': $nombre_atencion='AMBULATORIO';break;
                        case '2': $nombre_atencion='EMERGENCIA';break;
                        case '3': $nombre_atencion='HOSPITALIZACION';break;
                        case '4': $nombre_atencion='OTRO';break;
                    }

                    if($id_atencion==2){
                      $evaluaciones = $modelmedico->GetMostrarEvaluacionesMedicoByHIS($id_atencion,$id_establecimiento,$fecha_atencion,$id_medico);
                    }else{
                      $evaluaciones = $modelmedico->GetMostrarEvaluacionesMedicoByHISHO($id_atencion,$id_establecimiento,$fecha_atencion,$id_medico);
                    }

                    $model_medico = new \App\Models\Medico;
                    $dato_hoja_his = $model_medico->GetDocumentosPendientesFirmarHojaHis($id_atencion,$id_establecimiento,$fecha_atencion,$id_medico, $id_servicio);
                    
                    if(count($dato_hoja_his) > 0){
                      if($dato_hoja_his[0]->ruta_hoja_his!=null){ $flag_pendiente_firma = 1; }
                      else{ $flag_pendiente_firma = 0; }
                    }else{$flag_pendiente_firma = 0; }
                
                    $id_consultorio = $id_servicio;
                    $dni_medico = $medico->dni;

                    $sheet->mergeCells('A1:N1');
                    $sheet->cell('A1', function($cell) {$cell->setValue('HOJA HIS');  $cell->setFontSize(15); $cell->setFontWeight('bold'); $cell->setAlignment('center'); $cell->setValignment('middle'); });
                    $sheet->mergeCells('A3:A3');
                    
                    array_push($variable, array('Reporte HOJA HIS  De ' . $fecha_atencion ));
                    array_push($variable, array('Medico : ' . $medico->paterno .' '. $medico->materno .','. $medico->nombre ));
                    array_push($variable, array('DNI : ' . $medico->dni  ));
                    array_push($variable, array("ATENCIONES"));
                    array_push($variable, array("N","Hora Atencion","DNI", "Apellido Paterno", "Apellido Materno","Nombre", "Historia Clinica","E","S","Diagnostico Motivo de la Consulta","Tipo Diag","CIE10","CANT","CPT"));

                    foreach ($prestaciones as $u) {
                        $model_prestaciones = new \App\Models\Prestaciones;
                        $diagnostico = $model_prestaciones->GetDiagnosticoByIdPrestacion($u->id);
                        $procedimientos = $model_prestaciones->GetProcedimientoByIdPrestacion($u->id);
                        $cadena_diag = ''; $tipo_diagnostico = ""; $cod_diag = ''; $cod_proc = ''; $cant_proc = ''; 

                        foreach ($diagnostico as $d):
                            $cadena_diag .= $d->nombre.';';
                               if($d->id_tipo_diagnostico==1)$tipo_diagnostico = "P".';';
                               if($d->id_tipo_diagnostico==2)$tipo_diagnostico = "D".';';
                               if($d->id_tipo_diagnostico==3)$tipo_diagnostico = "R".';';
                            $cod_diag .= $d->codigo.';';

                        endforeach; 

                        foreach ($procedimientos as $p):
                            $cant_proc .= $p->cantidad.';';
                            $cod_proc .= $p->codigo.';';
                        endforeach;
                      
                        array_push($variable, array($n++, $u->horario, $u->nro_doc_ident, $u->paciente_paterno, $u->paciente_materno,$u->paciente_nombre, $u->nro_historia, $u->ipress, $u->upss,$cadena_diag,$tipo_diagnostico,$cod_diag,$cant_proc,$cod_proc )); 
                    }



                    if($id_atencion > 1):
                        array_push($variable, array(""));
                        array_push($variable, array(""));
                        array_push($variable, array("EVALUACIONES"));
                        array_push($variable, array("N","Hora Atencion","DNI", "Apellido Paterno", "Apellido Materno","Nombre", "Historia Clinica","E","S","Diagnostico Motivo de la Consulta","Tipo Diag","CIE10","CANT","CPT"));

                        foreach ($evaluaciones as $r) {
                            $model_prestaciones = new \App\Models\Prestaciones;
                            $model_evaluacion = new \App\Models\Evaluacione;
                            $model_radiologia = new \App\Models\Radiologia;
                            $model_laboratorio = new \App\Models\Laboratorio;
                            $diagnostico_eval = $model_evaluacion->GetDiagnosticoByIdEvaluacion($r->id);
                            $procedimientos = $model_prestaciones->GetProcedimientosByIdPrestacionydiagEvaluacion($r->id_prestacion, 1, $r->id);
                            //$laboratorios = $model_laboratorio->GetLaboratorioByIdPrestacionEvaluacion($r->id_prestacion,$r->id);
                            //$radiologias = $model_radiologia->GetRadiologiaByIdPrestacionEvaluacion($r->id_prestacion,$r->id);
                            $eval_diag = ''; $tipo_diagnostico = ""; $cod_eval_diag = ''; $cod_proc_eval = ''; $cant_proc_eval = ''; 

                            foreach ($diagnostico_eval as $de):
                                $eval_diag .= $de->nombre.';';
                                   if($de->id_tipo_diagnostico==1)$tipo_diagnostico .= "P".';';
                                   if($de->id_tipo_diagnostico==2)$tipo_diagnostico .= "D".';';
                                   if($de->id_tipo_diagnostico==3)$tipo_diagnostico .= "R".';';
                                $cod_eval_diag .= $de->codigo.';';


                            endforeach; 

                            foreach ($procedimientos as $pr):
                                $cant_proc_eval .= $pr->cantidad.';';
                                $cod_proc_eval .= $pr->codigo.';';
                            endforeach;
                          
                            array_push($variable, array($n++, $r->horario, $r->nro_doc_ident, $r->paciente_paterno, $r->paciente_materno,$r->paciente_nombre, $r->nro_historia, 'C', 'C',$eval_diag,$tipo_diagnostico,$cod_eval_diag,$cant_proc_eval,$cod_proc_eval )); 
                        }


                    endif;
                    
                    $sheet->with($variable)->mergeCells('A2:W2'); 
                endif;
            endif;

        });
    //});
    })->export('xls'); 
    //$excel->store('xlsx', false, true)['full'];
    //    return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

    
	public function genera_csv_anestesiologia_cqx(Request $request){
      
        $path = public_path('tmp/csv');
        $path_zip = public_path('tmp/zip');
    
        if (!is_dir($path)) {
            mkdir($path);
        }

        if (!is_dir($path_zip)) {
            mkdir($path_zip);
            mkdir(public_path('tmp/zip/firmados'));
            mkdir(public_path('tmp/zip/sin_firma'));
        }
        
        $csv = "";
        if (Auth::check()):
            $csv .= Auth::user()->id;
        endif;
        $csv .= "_".date("YmdHis");

        
        Excel::create($csv, function($excel) use($request){
            $excel->sheet('GENERAL', function($sheet) use($request) {
                $model_receta = new Receta_vale;
                $model_laboratorio = new \App\Models\Laboratorio;
                $model_radiologia = new \App\Models\Radiologia;
                $model_interconsulta = new \App\Models\Interconsulta;
                
                $variable = [];
                Log::info("genera_csv", ["cq_anestesia" => "Antes de entrar en condición"]);
                foreach($request->mov as $row):
                    if($request->proviene_formulario==3):
                        Log::info("genera_csv", ["prestacion" => $row]);  
                        $cq_anestesia = DB::table('anestesia_quirurgicas')
                                                    ->where('anestesia_quirurgicas.id_prestacion','=',$row)
                                                    ->select('anestesia_quirurgicas.*')
                                                    ->first();
                        Log::info("genera_csv", ["cq_anestesia" => $cq_anestesia]);                           
                        if (!is_null($cq_anestesia)) {
                            $this->ver_hospitalizacion_imprimir_cq_anestesia($row);
                            array_push($variable, array(url().'/tmp/pdf/sin_firma/hospitalizacion_atencion_'.$row.'.pdf', url().'/upload_firma/?name=cf_hospitalizacion_atencion_'.$row.'.pdf&id_tipo=prestacion&id_resol='.$row, 'cf_hospitalizacion_atencion_'.$row.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().'/images/escudo.jpg','1','7'));
                        } else {
                            $this->ver_hospitalizacion_imprimir($row);
                            array_push($variable, array(url().'/tmp/pdf/sin_firma/hospitalizacion_atencion_'.$row.'.pdf', url().'/upload_firma/?name=cf_hospitalizacion_atencion_'.$row.'.pdf&id_tipo=prestacion&id_resol='.$row, 'cf_hospitalizacion_atencion_'.$row.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().'/images/escudo.jpg','1','7'));
                        }
                    else:
                        $this->ver_prestacion_imprimir($row);
                        array_push($variable, array(url().'/tmp/pdf/sin_firma/prestacion_'.$row.'.pdf', url().'/upload_firma/?name=cf_prestacion_'.$row.'.pdf&id_tipo=prestacion&id_resol='.$row, 'cf_prestacion_'.$row.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().'/images/escudo.jpg','1','7'));
                        
                        $gastro = Gastroenterologia::where('prestacion_id', '=', $row)->first();
                        
                        if(isset($gastro)){
                            for ($i=0; $i < 2; $i++) { 
                                switch($i){
                                    case 0: if ($gastro->baja == 1) {
                                                $this->ver_informe_gastro_imprimir($gastro->id,$row,1);
                                            } 
                                            break;
                                    case 1: if ($gastro->alta == 1) {
                                                $this->ver_informe_gastro_imprimir($gastro->id,$row,2);
                                            }
                                            break;
                                }
                            }
                        }
                    endif;
                    
                    $receta = $model_receta->GetRecetasByIdPrestacion($row);
                    $laboratorios = $model_laboratorio->GetLaboratorioByIdPrestacion($row);
                    $radiologias = $model_radiologia->GetRadiologiaByIdPrestacion($row);
                    $interconsultas = $model_interconsulta->GetInterconsultaByIdPrestacion($row);
                   

                    //genera pdf recetas
                    if(isset($receta)){
                        foreach($receta as $rowrv){
                            if ($rowrv->ruta_receta == "") {
                                $this->ver_receta_vale_anestesiologia($rowrv->id);
                                array_push($variable, array(url().'/tmp/pdf/sin_firma/receta_'.$rowrv->id.'.pdf', url().'/upload_firma/?name=cf_receta_'.$rowrv->id.'.pdf&id_tipo=receta&id_resol='.$rowrv->id, 'cf_receta_'.$rowrv->id.'.pdf','0','45','350','70','Fecha de Firma: <DATE> Firmante: <SIGNER>',url().'/images/escudo.jpg','1','7'));
                            }
                        }
                    }

                    //genera pdf laboratorios
                    if(isset($laboratorios)){
                         foreach($laboratorios as $laboratorio) {
                             if ($laboratorio->fecha_firma == ""){
                                 $this->ver_laboratorio_imprimir($laboratorio->id);                                
			                 }
                         }
                     }                

                    //genera pdf radiologias
                    if(isset($radiologias)){
                        foreach($radiologias as $radiologia) {
                            if ($radiologia->fecha_firma == ""){
                                $this->ver_radiologia_imprimir($radiologia->id);
                            }
                        }
                    }
                    
                    if(isset($interconsultas)){
                      foreach($interconsultas as $interconsulta) {
                        if ($interconsulta->fecha_firma_interconsulta == ""){
                            $this->genera_pdf_interconsulta($interconsulta->id_interconsulta, true);
                        }
                      }
                    }

                endforeach;
                $sheet->fromArray($variable, null, '', false, false);
            });
        })->store('csv',public_path('tmp/csv'));

        $obj = new Archive7z(public_path('tmp/zip/sin_firma/'.$csv.'.7z'));

        $model_receta = new Receta_vale;
        $model_prestacion = new Prestaciones;
        $model_laboratorio = new \App\Models\Laboratorio;
        $model_radiologia = new \App\Models\Radiologia;
        $model_interconsulta = new \App\Models\Interconsulta;
        $model_referencia = new \App\Models\Referencia;
        
        foreach($request->mov as $row){
            $prestacion = $model_prestacion->GetEstadoFirmaPrestacion($row);
            $receta = $model_receta->GetRecetasByIdPrestacion($row);
            $laboratorios = $model_laboratorio->GetLaboratorioByIdPrestacion($row);
            $radiologias = $model_radiologia->GetRadiologiaByIdPrestacion($row);
            $interconsultas = $model_interconsulta->GetInterconsultaByIdPrestacion($row);
            
            if($prestacion[0]->id_tipo_atencion==3 && $prestacion[0]->ruta_prestacion == "" && $prestacion[0]->id_establecimiento == 76){
                $obj->addEntry(public_path('/tmp/pdf/sin_firma/hospitalizacion_atencion_'.$row.'.pdf'));
                $cq_anestesia = DB::table('anestesia_quirurgicas')
                                                ->where('anestesia_quirurgicas.id_prestacion','=',$row)
                                                ->select('anestesia_quirurgicas.*')
                                                ->first();
                if (is_null($cq_anestesia)) {
            $obj_hoja = \App\Models\HospitalizacionAtencione::where('id_prestacion', '=', $row)->first();
                    /*if($obj_hoja->hoja_terapeutica==1):
                        $obj->addEntry(public_path('/tmp/pdf/sin_firma/hoja_terapeutica_'.$row.'.pdf'));
                    endif;*/
                }
            }
            else{
                if($prestacion[0]->id_tipo_atencion!=3){
                    if($prestacion[0]->ruta_prestacion==""):
                        $obj->addEntry(public_path('/tmp/pdf/sin_firma/prestacion_'.$row.'.pdf'));
                    endif;
                    
                    $gastro = Gastroenterologia::where('prestacion_id', '=', $row)->first();
                
                    if(isset($gastro)){
                        for ($i=0; $i < 2; $i++) { 
                            switch($i){
                                case 0: if ($gastro->baja == 1) {
                                            $obj->addEntry(public_path('/tmp/pdf/sin_firma/informe_gastro_baja_'.$gastro->id.'.pdf'));
                                        } 
                                        break;
                                case 1: if ($gastro->alta == 1) {
                                            $obj->addEntry(public_path('/tmp/pdf/sin_firma/informe_gastro_alta_'.$gastro->id.'.pdf'));
                                        }
                                        break;
                            }
                        }
                    }
                }
                else{
                    if($prestacion[0]->ruta_prestacion=="" && $prestacion[0]->id_establecimiento != 76){
                        $obj->addEntry(public_path('/tmp/pdf/sin_firma/prestacion_'.$row.'.pdf'));
                    }
                }
                    
                
            }

            if(isset($receta)){
                foreach($receta as $rowrv){
                    if ($rowrv->ruta_receta == "") {
                        $obj->addEntry(public_path('/tmp/pdf/sin_firma/receta_'.$rowrv->id.'.pdf')); 

                    }
                }
            }

                if(isset($laboratorios)){
                    foreach($laboratorios as $laboratorio) {
                    if ($laboratorio->fecha_firma == ""){
                            $obj->addEntry(public_path('/tmp/pdf/sin_firma/laboratorio_'.$laboratorio->id.'.pdf')); 
                        }
                    }
            }

            if(isset($radiologias)){
                foreach($radiologias as $radiologia) {
                    if ($radiologia->fecha_firma == ""){
                        $obj->addEntry(public_path('/tmp/pdf/sin_firma/radiologia_'.$radiologia->id.'.pdf')); 
                    }
                }
            }

            if(isset($interconsultas)){
                foreach($interconsultas as $interconsulta) {
                    if ($interconsulta->fecha_firma_interconsulta == ""){
                        $obj->addEntry(public_path('/tmp/pdf/sin_firma/interconsulta_'.$interconsulta->id_interconsulta.'.pdf')); 

                    }
                }
            }
        }
    
	    $resultado["csv"]=$csv;
        $resultado["sw"]=true;
        echo json_encode($resultado);
    }
  
  public function ver_receta_vale_anestesiologia($nro_receta) {
        $path = public_path('tmp/pdf');
        if (!is_dir($path)) {
        mkdir($path);
        }
        
        $path = public_path('tmp/pdf/sin_firma/');
        if (!is_dir($path)) {
        mkdir($path);
        }
    
        $model_farmacia = new Farmacia();
        $model_receta = new Receta_vale;
        $model_productos_receta = new Producto_receta;
        //--------------------------------------------  
        $receta = $model_receta->ShowAllById($nro_receta);
        $receta = $receta[0];
        $dni_beneficiario = $receta->dni_beneficiario;
        $establecimiento = $model_farmacia->GetEstablecimientoPNP($receta->id_farmacia);
        $medicamentos = $model_productos_receta->ShowMedicinasById_receta_vale($nro_receta);

        $productos = $model_receta->ProductosRecetaByIdV3($nro_receta);
        $model_receta_diagnostico = new Receta_diagnostico();
        $diagnosticos = $model_receta_diagnostico->DiagnosticosByIdReceta($nro_receta);

        if ($receta->tipo_receta=='EMERGENCIA'):
            if($establecimiento->id==76):
                $model_emergencia = new \App\Models\Emergencia;
                $obtenerdato = $model_emergencia->GetObtenerServicioReceta($receta->id_prestacion);
                if($obtenerdato->id_prioridad != 4 ):
                    $receta->servicio= $obtenerdato->servicio;
                    $receta->consultorio= $obtenerdato->consultorio;
                else:
                    $receta->servicio= "IV - PATOLOGÍA AGUDA COMÚN";
                    $receta->consultorio= "CONSULTORIO DE ATENCIÓN RÁPIDA (CAR)";
                endif;
            endif;
        endif;

        //Datos adicionales
        if($receta->id_prestacion!=0):
            $model_prestacion = new \App\Models\Prestaciones;
            $prestacion = $model_prestacion->GetPrestacionById($receta->id_prestacion);
              $receta->talla =$prestacion->talla_cm;
              $receta->peso =$prestacion->peso_kg;
              $receta->cama = null; 
              $dato_adicional = null; 
              if($prestacion->id_ext!=null && $prestacion->id_tipo_atencion == 2):
                $model_emergencia = new \App\Models\Emergencia;
                $obtenerdato1 = $model_emergencia->GetObtenerServicioReceta($receta->id_prestacion);
                if($obtenerdato1->id_prioridad != 4 ):
                    $obtenerdato = $model_emergencia->GetObtenerServicioActual($prestacion->id_ext);
                    $datoadicional = $model_emergencia->GetObtenerCama($obtenerdato->cama);
                    $receta->cama = $datoadicional->cuarto.' - '. $datoadicional->cama;
                else:
                    $receta->cama = '';
                endif;
            else:
                if($prestacion->id_ext!=null && $prestacion->id_tipo_atencion == 3 ):
                  $model_hospitalizacion = new \App\Models\Hospitalizacione;
                  $dato_adicional = $model_hospitalizacion->GetObtenerDatos($prestacion->id_ext);
                  $receta->cama = $dato_adicional->cuarto.' - '. $dato_adicional->cama;
                endif;
            endif;
        else:
            $receta->talla = null;
            $receta->peso = null;
            $receta->cama = null; 
        endif;

        $titular = null;
        if ($receta->tipo_beneficiario != 'TITULAR'):
            $paciente_model = new \App\Models\Paciente();
            $titular = $paciente_model->GetAseguradoById($receta->id_asegurado_titular);
        endif;
        
        $carpeta = date("Y")."/".date("m")."/".date("d");
        $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_receta_".$nro_receta.".pdf";
