        $pdf = \PDF::loadView('pdf.firmar_receta_vale',compact('medicamentos','receta','establecimiento','productos','diagnosticos','codigo_qr','url_descarga','titular'));
        $pdf->getDomPDF()->set_option("enable_php", true);
        file_put_contents($path."receta_".$nro_receta.".pdf", $pdf->output());
    
    }


