                    else:
                        if($r->id_sub_consultorio!=1357):
                          
                            array_push($variable, array($n++,$r->fecha_atencion,$r->horario, $r->tipo_doc_ident, $r->nro_doc_ident,$r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,$r->parentesco,$r->situacion_paciente,$r->grado,$r->cip,$r->domicilio,$r->sexo,$r->fecha_nac, $r->edadafiliado,$r->usuario_cita,$r->tipo_cita,$r->servicio, $r->consultorio, $r->atencion, $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre,$r->condicion_establecimiento, $r->condicion_servicio,$diagnosticos,$procedimientos));
                        endif;

                    endif;
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
            });
        })->export('xls');
    }
    
