				array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                array_push($variable, array("Total: " . $nro_atendidas . " atenciones"));
                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array(""));
                array_push($variable, array("N","FECHA", "HORA", "TIPO DOC", "NUMERO DOC", "NUMERO HISTORIA", "PACIENTE","PARENTESCO","SEXO", "FECHA DE NACIMIENTO", "EDAD",
                    "RESPONSABLE CITA","TIPO DE CITA","SERVICIO", "CONSULTORIO", "TIPO ATENCION", "RESPONSABLE ATENCION", "CONDICION IPRESS","CONDICION UPSS", "DIAGNOSTICOS", "TIPO DIAGNOSTICO", "PROCEDIMIENTOS", "CANTIDAD"));
                $contador = 0;
                $encontrado = false;
                $i_quedado = 0;
                $aux_r = null;
                $hay_procedimientos = false;            
                foreach ($citas as $r) {
                    $hay_procedimientos = false;
                    for($i = $i_quedado; $i < count($procedimientos); $i++) {
                        $hay_procedimientos = true;
                        if ($r->id == $procedimientos[$i]->id):
                            array_push($variable, array(
                                $r->orden, $r->fecha_atencion, $r->horario, $r->tipo_doc_ident, $r->nro_doc_ident, $r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,
                                $r->parentesco, $r->sexo, $r->fecha_nac, $r->edadafiliado, $r->usuario_cita, $r->tipo_cita, $r->servicio, $r->consultorio, $r->atencion, 
                                $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre, $r->condicion_establecimiento, $r->condicion_servicio, $r->codigo_dx." - ".$r->nombre_dx, $r->tipo_dx,
                                $procedimientos[$i]->codigo_procedimiento." - ".$procedimientos[$i]->nombre_procedimiento,$procedimientos[$i]->cant_procedimiento)
                            );
                            $aux_r = $r;
                            $i_quedado = $i_quedado+1;
                            break;
                        else:
                            if ($aux_r && isset($aux_r->id) && isset($procedimientos[$i])) {
    if ($aux_r->id == $procedimientos[$i]->id) {        
        array_push($variable, array(
            $aux_r->orden, $aux_r->fecha_atencion, $aux_r->horario, $aux_r->tipo_doc_ident, $aux_r->nro_doc_ident, $aux_r->nro_historia, 
            $aux_r->asegurado_paterno.' '.$aux_r->asegurado_materno.', '.$aux_r->asegurado_nombre, 
            $aux_r->parentesco, $aux_r->sexo, $aux_r->fecha_nac, $aux_r->edadafiliado,
            $aux_r->usuario_cita, $aux_r->tipo_cita, $aux_r->servicio, $aux_r->consultorio, $aux_r->atencion, 
            $aux_r->medico_paterno.' '.$aux_r->medico_materno.', '.$aux_r->medico_nombre,
            $aux_r->condicion_establecimiento, $aux_r->condicion_servicio, '', '', 
            $procedimientos[$i]->codigo_procedimiento." - ".$procedimientos[$i]->nombre_procedimiento,
            $procedimientos[$i]->cant_procedimiento
        ));        
        $i_quedado = $i_quedado + 1;    
    } else {      
        array_push($variable, array(
            $r->orden, $r->fecha_atencion, $r->horario, $r->tipo_doc_ident, $r->nro_doc_ident, $r->nro_historia, 
            $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,
            $r->parentesco, $r->sexo, $r->fecha_nac, $r->edadafiliado, 
            $r->usuario_cita, $r->tipo_cita, $r->servicio, $r->consultorio, $r->atencion, 
            $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre,
            $r->condicion_establecimiento, $r->condicion_servicio, 
            $r->codigo_dx." - ".$r->nombre_dx, $r->tipo_dx, '', ''
        ));
        break;
    }
} else {  
    array_push($variable, array(
        $r->orden, $r->fecha_atencion, $r->horario, $r->tipo_doc_ident, $r->nro_doc_ident, $r->nro_historia, 
        $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,
        $r->parentesco, $r->sexo, $r->fecha_nac, $r->edadafiliado, 
        $r->usuario_cita, $r->tipo_cita, $r->servicio, $r->consultorio, $r->atencion, 
        $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre,
        $r->condicion_establecimiento, $r->condicion_servicio, 
        $r->codigo_dx." - ".$r->nombre_dx, $r->tipo_dx, '', ''
    ));
}
                        endif;
                    }					
                    $contador++;                    
                    if ($hay_procedimientos == false) {
                        if ($contador == count($citas)) {
                            array_push($variable, array(
                                $r->orden, $r->fecha_atencion, $r->horario, $r->tipo_doc_ident, $r->nro_doc_ident, $r->nro_historia, $r->asegurado_paterno.' '.$r->asegurado_materno.', '.$r->asegurado_nombre,
                                $r->parentesco, $r->sexo, $r->fecha_nac, $r->edadafiliado, $r->usuario_cita, $r->tipo_cita, $r->servicio, $r->consultorio, $r->atencion, 
                                $r->medico_paterno.' '.$r->medico_materno.', '.$r->medico_nombre, $r->condicion_establecimiento, $r->condicion_servicio, $r->codigo_dx." - ".$r->nombre_dx, $r->tipo_dx, '', '')
                            );
                        }
                    }					
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
                $sheet->cells('W8:W' . (count($variable) + 7), function($cells) {
                    $cells->setAlignment('center');  
                    $cells->setValignment('center');
                });
            });
        });
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

    public function ver_lab_orden_sin_reactivo($id_laboratorio) {

        $model_prestacion = new \App\Models\Prestaciones;
        $model_laboratorio = new \App\Models\Laboratorio;
        $model_medico = new \App\Models\Medico;
        $model_consultorio = new Consultorio();
        $laboratorio = $model_laboratorio->GetLaboratorioById($id_laboratorio);
        $id_prestacion=$laboratorio->id_prestacion;
        $res_prestacion = DB::table('prestaciones')->where('id', $id_prestacion)->first();
        $tipo_atencion = $res_prestacion->id_tipo_atencion;
        $diagnostico = $model_prestacion->GetDiagnosticoByIdPrestacionEvaluacion($id_prestacion, $laboratorio->id_evaluacion);
        $proclaboratorio = $model_prestacion->GetPrestacionLaboratorio($id_prestacion, $id_laboratorio);
        $fecha_atencion = null;
        switch ($tipo_atencion) {
            case 1:
                $titulo_cabecera = "CONSULTORIOS";
                $prestacion = $model_prestacion->GetPrestacionById($id_prestacion);
