        $Provincia = $model_establecimiento->GetProvinciaForUbego($establecimiento[0]->ubigeo);
        // $carpeta = date("Y")."/".date("m")."/".date("d");
        // $url_descarga = "https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_laboratorio_".$id_laboratorio.".pdf";
        // $codigo_qr = QrCode::format('png')->size(150)->generate("https://sigesapol.dirsapolpnp.gob.pe/".$carpeta."/cf_laboratorio_".$id_laboratorio.".pdf");
        
        $pdf = \PDF::loadView('pdf.mostrar_firmar_laboratorio_sin_reactivo_v2',compact('nivel','tipo_atencion','lista_rua','firmado','total_examenes','filas_por_columnas','consultorio','prestacion','diagnostico','total_examenes_prestacion_procedimientos','num_columna','titulo_cabecera','id_laboratorio','camas','establecimiento','Provincia','laboratorio','fecha_atencion'));
        $pdf->setPaper('A4', 'landscape');
        $pdf->getDomPDF()->set_option("enable_php", true);
        
        return $pdf->stream('ver_laboratorio.pdf');
    }

    public function exportar_detallado_quirurgico(Request $request) {
        $fecha_ini=$request->fecha_ini; 
        $fecha_fin=$request->fecha_fin;
        $dni=!empty($request->dni_beneficiario)?$request->dni_beneficiario:null;
        $paciente=!empty($request->nombre_beneficiario)?strtoupper($request->nombre_beneficiario):null;
        $estado=$request->estado;
        $id_servicio=$request->id_servicio;
        $id_tipo_atencion=$request->id_tipo_atencion;

        $fecha_ini_intervencion = isset($request->fecha_ini_intervencion) && $request->fecha_ini_intervencion !== '' ? $request->fecha_ini_intervencion: null;
        $fecha_fin_intervencion = isset($request->fecha_fin_intervencion) && $request->fecha_fin_intervencion !== ''? $request->fecha_fin_intervencion: null;

        $fecha_ini_format = !empty($fecha_ini)?Carbon::createFromFormat('d-m-Y', $fecha_ini)->format('Y-m-d'):null;
        $fecha_fin_format = !empty($fecha_fin)?Carbon::createFromFormat('d-m-Y', $fecha_fin)->format('Y-m-d'):null;
        $id_estado_pendiente =!empty($request->id_estado_pendiente)?$request->id_estado_pendiente:null;
        $id_medico = !empty($request->id_medico)?$request->id_medico:0;
        
        $id_user = Auth::user()->id;
		$modelfarma = new Farmacia();
        $farmacia = $modelfarma->GetFarmaByUser($id_user);
        $establecimiento = $modelfarma->GetEstablecimientoPNP($farmacia->id);
        $id_establecimiento=$establecimiento->id;
        $usuario = $modelfarma->GetNombreUsuarioByIdUser($id_user);
        $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;
        
        $Cqxintervencion = new \App\Models\CqxIntervencion();
        $data = $Cqxintervencion->getReporteDetalladoIntervenciones($fecha_ini_format, $fecha_fin_format,$fecha_ini_intervencion,$fecha_fin_intervencion,$dni,$paciente,$id_servicio,$estado,$id_tipo_atencion,$id_establecimiento,$id_medico);
        $cant_registros = count($data);
        $excelName = 'Exportar_Reportes_detallado_de_Lista_Pendientes_' . $id_user . '_' . Carbon::now()->format('Y-m-d H-i-s');
        $excelNameResponse = 'Exportar_Reportes_detallado_de_Lista_Pendientes_' . $id_user . '_' . Carbon::now()->format('Y-m-d H-i-s') . '.xlsx';
       
        $excel=Excel::create($excelName, function($excel) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $nombre_usuario, $id_user, $establecimiento, $data, $cant_registros) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $nombre_usuario, $id_user, $establecimiento, $data, $cant_registros) {

                //--------------------------------------------------------------
                $variable = [];
                $n = 1;
                array_push($variable, array($establecimiento->nombre));
                array_push($variable, array("Reporte detallado de centro quirurgico"));
                array_push($variable, array("Fecha Desde: " . $fecha_ini));
				array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                array_push($variable, array("Total: " . $cant_registros . " registros"));
                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array(""));

                array_push($variable, array(
                                        "N",
                                        "FECHA SOLICITUD",
                                        "FECHA INTERVENCION",
                                        "SALA ASIGNADA",
                                        "ESTADO",
                                        "DNI PACIENTE",
                                        "ASEGURADOS",
                                        "TELEFONO",
                                        "EDAD",
                                        "GRADO",
                                        "SERVICIO",
                                        "DIAGNOSTICOS",
                                        "PROCEDIMIENTO",
                                        "TIEMPO DE OPERACION SOLICITADO",
                                        "TIEMPO DE OPERACION REAL",
                                        "HORA ENTRADA",
                                        "HORA SALIDA",
                                        "INICIO CIRUGIA",
                                        "TERMINO CIRUGIA",
                                        "INICIO ANESTESIA",
                                        "TERMINO ANESTESIA",
                                        "SALIDA SOAP",
                                        "INGRESO URPA",
                                        "HORA ALTA ANESTESIOLOGIA",
                                        "HORA COORDINACION LLAMADA ANESTESIOLOGIA",
                                        "SALIDA URPA",
                                        "INGRESO CLINICA DIA",
                                        "HORA ALTA CIRUJANO",
                                        "HORA COORDINACION LLAMADA CIRUGIA",
                                        "SALIDA CLINICA DIA",
                                        "MEDICO CIRUJANO",
                                        "MEDICO ANESTESIOLOGO",
                                        "TIPO CIRUGIA",
                                        "TIPO ANESTESIA",
                                        "TIPO OPERACIÓN",
                                        'SUSPENDIDO POR',
                                        'FECHA SUSPENSIÓN',
                                        'HORA SUSPENSIÓN',
                                        'TIPO SUSPENSIÓN',
                                        'MOTIVO SUSPENSIÓN',
                                        'OTRA DESCRIPCION',
                                        'FUE ADMISIONADO',
                                        'FUE SUSPENDIDO'
                                    ));
                
                if (isset($data) && !empty($data) && count($data) > 0) {
                    foreach ($data as $r) {
                        $diagnosticos_str = '';

                        if (!empty($r->diagnosticos)) {
                            $texto = trim($r->diagnosticos, '{}');
                            $texto = str_replace(['\\"', '"', '(', ')'], '', $texto);
                            $diagnosticos_array = array_map('trim', explode(',', $texto));
                            $diagnosticos_array = array_filter($diagnosticos_array, function($d) {
                                return !empty($d);
                            });
                            $diagnosticos_str = implode(', ', $diagnosticos_array);
                        }
                        $procedimientos_str = '';

                        if (!empty($r->cpms_intervencion)) {

                            $texto = trim($r->cpms_intervencion, "{} \t\n\r\0\x0B");

                            $procedimientos_array = [];

                            if (preg_match_all('/\(([\d\.]+),\\\"([^"]+)\\\"\)/', $texto, $matches, PREG_SET_ORDER)) {
                                foreach ($matches as $match) {
                                    $procedimientos_array[] = trim($match[1]) . ' - ' . trim($match[2]);
                                }
                            } else {
                                $texto = str_replace(['\\"', '"', '(', ')'], '', $texto);
                                $procedimientos_array = array_map('trim', explode(',', $texto));
                            }

                            $procedimientos_array = array_filter($procedimientos_array);
                            $procedimientos_str = implode(', ', $procedimientos_array);
                        }

                        array_push($variable, array(
                            $n++, 
                            $r->fecha_solicitud,
                            $r->fecha_intervencion, 
                            $r->sala_asignada, 
                            $r->estado, 
                            $r->dni_paciente,
                            $r->nombres_asegurado, 
                            $r->telefonos,
                            $r->edad_asegurado,
                            $r->grado_asegurado,
                            $r->nombre_servicio,
                            $diagnosticos_str,
                            $procedimientos_str,
                            $r->tiempo_operacion_solicitado,
                            $r->tiempo_operacion_real,
                            $r->hora_entrada,
                            $r->hora_salida,
                            $r->inicio_cirugia,
                            $r->fin_cirugia,
                            $r->inicio_anestesia,
                            $r->fin_anestesia,
                            $r->salida_soap,
                            $r->ingreso_urpa,
                            $r->hora_alta_anestesiologo,
                            $r->hora_coordinacion_llamada_anestesiologia,
                            $r->salida_urpa,
                            $r->ingreso_clinica_dia,
                            $r->hora_alta_cirujano,
                            $r->hora_coordinacion_llamada_cirugia,
                            $r->salida_clinica_dia,
                            $r->medico_cirujano,
                            $r->medico_anestesiologo,
                            $r->tipo_cirugia,
                            $r->tipo_anestesia,
                            $r->tipo_operacion,
                            $r->suspendido_por,
                            $r->fecha_suspension,
                            $r->hora_suspension,
                            $r->tipo_suspension,
                            $r->motivo_suspension,
                           (isset($r->otro_descripcion) && trim($r->otro_descripcion) !== '' && strtolower(trim($r->otro_descripcion)) !== 'null')? $r->otro_descripcion: '',
                           $r->fue_admisionado,
                           $r->is_suspended,
                        ));
                    }
                }
                $sheet->with($variable)->mergeCells('A2:C2')->mergeCells('A3:C3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6')->mergeCells('A7:C7');
            });
        });

        // Devuelve la URL del archivo Excel generado
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }
    
    public function exportar_asegurados_ipress($id) {
        $id_establecimiento = Auth::user()->id_establecimiento;
        $fechaInicio = null;
        if ($id == 1) {
            $fechaInicio = Carbon::now()->subDays(30);
        } elseif ($id == 2) {
            $fechaInicio = Carbon::now()->subDays(90);
        }
        $query = DB::table('prestaciones as p')
            ->join('asegurados as a', 'a.id', '=', 'p.id_asegurado')
            ->leftJoin('departamentos as dpto', 'dpto.id_departamento', '=', 'a.id_departamento')
            ->leftJoin('provincias as prov', 'prov.id_provincia', '=', 'a.id_provincia')
            ->leftJoin('distritos as dist', 'dist.id_distrito', '=', 'a.id_distrito')
            ->where('p.id_establecimiento', $id_establecimiento);
        if ($fechaInicio) {
            $query->where('p.created_at', '>=', $fechaInicio);
        }
        $femas = $query
            ->selectRaw("
                DISTINCT ON (a.id)
                a.id as id_asegurado,
                (a.paterno || ' ' || a.materno || ', ' || a.nombre) as nombre_completo,
                a.nro_doc_ident as documento,
                a.sexo,
                EXTRACT(YEAR FROM AGE(a.fecha_nac::date)) AS edad,
                dpto.descripcion AS departamento,
                prov.descripcion AS provincia,
                dist.descripcion AS distrito,
                p.created_at
            ")
            ->orderBy('a.id')
            ->orderBy('p.created_at', 'desc')
            ->get();
        Excel::create('Reporte_Asegurados', function ($excel) use ($femas, $id) {
            $excel->sheet('GENERAL', function ($sheet) use ($femas, $id) {
                $variable = [];
                $n = 1;
                $sheet->mergeCells('A1:I1');
                $sheet->cell('A1', function ($cell) use ($id) {
                    $titulo = 'Reporte de Asegurados';
                    if ($id == 1) $titulo .= ' (Últimos 30 días)';
                    elseif ($id == 2) $titulo .= ' (Últimos 90 días)';
                    else $titulo .= ' (Todos)';
                    $cell->setValue($titulo);
                    $cell->setFontSize(15);
                    $cell->setFontWeight('bold');
                    $cell->setAlignment('center');
                });
                array_push($variable, array(""));
                array_push($variable, array(
                    "N°",
                    "Nombre Completo",
                    "Documento",
                    "Sexo",
                    "Edad",
                    "Departamento",
                    "Provincia",
                    "Distrito",
                    "Fecha Registro"
                ));
                foreach ($femas as $u) {
                    array_push($variable, array(
                        $n++,
                        $u->nombre_completo,
                        $u->documento,
                        $u->sexo,
                        $u->edad,
                        $u->departamento,
                        $u->provincia,
                        $u->distrito,
                        $u->created_at
                    ));
                }
                $sheet->fromArray($variable, null, 'A2', false, false);
            });
        })->export('xlsx');
    }

     public function exportar_reporte_firmas_pendientes(Request $request) {   
        if (!Auth::check()):
            return redirect('/auth/login');
        endif;
        //----------------------------------------------------------------------
        $id_user =Auth::user()->id;
        $flag_fp = Auth::user()->flag_firmas_pendientes;
        $id_establecimiento = Auth::user()->id_establecimiento;
        $model_establecimiento = new \App\Models\Establecimiento;
        $establecimiento= $model_establecimiento->GetById($id_establecimiento);
        $fecha_desde  = isset($request->fecha_ini_fp) && $request->fecha_ini_fp != '' ? $request->fecha_ini_fp : null;
        $fecha_hasta  = isset($request->fecha_fin_fp) && $request->fecha_fin_fp != '' ? $request->fecha_fin_fp : null;
        $division     = isset($request->division) && $request->division != '' ? $request->division : null;
        $departamento = isset($request->departamento) && $request->departamento != '' ? $request->departamento : null;
        $user         = isset($request->prof_salud) && $request->prof_salud != '' ? $request->prof_salud : null;
        $pagina       = null; 
        $limit        = null; 
        $model_docsinfirmar = new \App\Models\Docsinfirmar;
        $firmas_pendientes = $model_docsinfirmar-> AllFirmasPendientesReportePrestaciones($id_establecimiento,$fecha_desde,$fecha_hasta,$division,$departamento,$user,$pagina,$limit);
        $cantidad = count($firmas_pendientes);
        /////////////////////////////////////////////////////////////////////////////////////////////////////

        $excelName = 'Reporte_de_Firmas_Pendientes_' . auth()->user()->id . '_' . Carbon::now()->format('Y-m-d_H-i-s');
        $excelNameResponse = 'Reporte_de_Firmas_Pendientes_' . auth()->user()->id . '_' . Carbon::now()->format('Y-m-d_H-i-s') . '.xlsx';
        $excel = Excel::create($excelName, function ($excel) use ($establecimiento,$fecha_desde,$fecha_hasta,$division,$departamento,$user,$cantidad,$firmas_pendientes) {
            $excel->sheet('GENERAL', function ($sheet) use ($establecimiento,$fecha_desde,$fecha_hasta,$division,$departamento,$user,$cantidad,$firmas_pendientes) {
            
            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                $variable = [];
                $n = 1;

                array_push($variable, array("REPORTE DE FIRMAS PENDIENTES"));
                array_push($variable, array("Reporte exportado el: " . Carbon::now()->format('d-m-Y_H-i-s')));
                array_push($variable, array("Total: " . $cantidad . " registros"));
                array_push($variable, array("Usuario : " . auth()->user()->paterno . " ".auth()->user()->materno.",".auth()->user()->name));
                array_push($variable, array(""));
                //24campos
                array_push($variable, array(
                    "N",
                    "ESTABLECIMIENTO",
                    "PROFESIONAL DE LA SALUD",
                    "DIVISIÓN",
                    "DEPARTAMENTO",
                    "ORIGEN DE ATENCIÓN",
                    "N° DE FIRMAS PENDIENTES",
                ));
                $sheet->setAutoFilter('A7:G7');
                $sheet->cells('A7:G7', function($cells) {
                    $cells->setBackground('#f0ad4e');   
                    $cells->setFontColor('#000000ff');    
                    $cells->setFontWeight('bold');           
                });
                try {
                    foreach ($firmas_pendientes as $fp) { 
                        // ============================== VALORES DEFINIDOS ===============================
                        array_push($variable, array(
                            $n++,
                            $establecimiento[0]->nombre,
                            $fp->medico,
                            $fp->unidad_pertenece,
                            $fp->sub_unidad_pertenece,
                            $fp->sub_unidad_atencion,
                            $fp->total_pendientes_firmas
                        ));
                    }
                } catch (\Exception $e) {
                    // $e->getMessage();
                     \Log::error('Error generando Excel de firmas pendientes: ' . $e->getMessage());
                    throw $e; 
                } 

                $sheet->with($variable)
                    ->setAutoSize(false) 
                    ->setWidth([
                        'A' => 10,  // N
                        'B' => 40,  // ESTABLECIMIENTO
                        'C' => 40,  // PROFESIONAL DE LA SALUD
                        'D' => 40,  // DIVISIÓN PERTENECE
                        'E' => 40,  // DEPARTAMENTO PERTENECE
                        'F' => 40,  // DEPARTAMENTO ATENCION
                        'G' => 70   // N° DE FIRMAS PENDIENTES

                    ])
                    ->mergeCells('A2:E2')
