        $fecha_desde  = isset($request->fecha_ini_fpe) && $request->fecha_ini_fpe != '' ? $request->fecha_ini_fpe : null;
        $fecha_hasta  = isset($request->fecha_fin_fpe) && $request->fecha_fin_fpe != '' ? $request->fecha_fin_fpe : null;
        $division     = isset($request->division_enf) && $request->division_enf != '' ? $request->division_enf : null;
        $departamento = isset($request->departamento_enf) && $request->departamento_enf != '' ? $request->departamento_enf : null;
        $user         = isset($request->prof_salud_enf) && $request->prof_salud_enf != '' ? $request->prof_salud_enf : null;
        $pagina       = null;
        $limit        = null;
        $model_docsinfirmar = new \App\Models\Docsinfirmar;
        $firmas_pendientes = $model_docsinfirmar->AllFirmasPendientesReporteEnfermeria($id_establecimiento,$fecha_desde,$fecha_hasta,$division,$departamento,$user,$pagina,$limit);
        $cantidad = count($firmas_pendientes);
        /////////////////////////////////////////////////////////////////////////////////////////////////////
        $excelName = 'Reporte_de_Firmas_Pendientes_Enfermeria_' . auth()->user()->id . '_' . Carbon::now()->format('Y-m-d_H-i-s');
        $excelNameResponse = 'Reporte_de_Firmas_Pendientes_Enfermeria_' . auth()->user()->id . '_' . Carbon::now()->format('Y-m-d_H-i-s') . '.xlsx';
        $excel = Excel::create($excelName, function ($excel) use ($establecimiento,$cantidad,$firmas_pendientes) {
            $excel->sheet('GENERAL', function ($sheet) use ($establecimiento,$cantidad,$firmas_pendientes) {
                $variable = [];
                $n = 1;
                array_push($variable, array("REPORTE DE FIRMAS PENDIENTES - ENFERMERÍA"));
                array_push($variable, array("Reporte exportado el: " . Carbon::now()->format('d-m-Y_H-i-s')));
                array_push($variable, array("Total: " . $cantidad . " registros"));
                array_push($variable, array("Usuario : " . auth()->user()->paterno . " ".auth()->user()->materno.",".auth()->user()->name));
                array_push($variable, array(""));
                array_push($variable, array(
                    "N",
                    "ESTABLECIMIENTO",
                    "PROFESIONAL DE ENFERMERÍA",
                    "DIVISIÓN",
                    "DEPARTAMENTO",
                    "ORIGEN DE ATENCIÓN",
                    "N° DE FIRMAS PENDIENTES",
                ));
                $sheet->setAutoFilter('A7:G7');
                $sheet->cells('A7:G7', function($cells) {
                    $cells->setBackground('#8E44AD');
                    $cells->setFontColor('#ffffff');
                    $cells->setFontWeight('bold');
                });
                try {
                    foreach ($firmas_pendientes as $fp) {
                        array_push($variable, array(
                            $n++,
                            $establecimiento[0]->nombre,
                            $fp->enfermero,
                            $fp->unidad_pertenece,
                            $fp->sub_unidad_pertenece,
                            $fp->sub_unidad_atencion,
                            $fp->total_pendientes_firmas
                        ));
                    }
                } catch (\Exception $e) {
                    \Log::error('Error generando Excel de firmas pendientes enfermería: ' . $e->getMessage());
                    throw $e;
                }

                $sheet->with($variable)
                    ->setAutoSize(false)
                    ->setWidth([
                        'A' => 10,  // N
                        'B' => 40,  // ESTABLECIMIENTO
                        'C' => 40,  // PROFESIONAL DE ENFERMERÍA
                        'D' => 40,  // DIVISIÓN PERTENECE
                        'E' => 40,  // DEPARTAMENTO PERTENECE
                        'F' => 40,  // ORIGEN DE ATENCION
                        'G' => 70   // N° DE FIRMAS PENDIENTES
                    ])
                    ->mergeCells('A2:E2')
                    ->mergeCells('A3:C3')
                    ->mergeCells('A4:C4')
                    ->mergeCells('A5:C5');

                $sheet->cell('A2', function($cell) {
                    $cell->setAlignment('center');
                    $cell->setFontWeight('bold');
                });
            });
        });
            // Devuelve la URL del archivo Excel generado
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

