                    ->mergeCells('A2:E2')
                    ->mergeCells('A3:C3')
                    ->mergeCells('A4:C4')
                    ->mergeCells('A5:C5');

                $sheet->cell('A2', function($cell) {
                    $cell->setAlignment('center');
                    $cell->setFontWeight('bold');
                });
            });
        });
            // Devuelve la URL del archivo Excel generado
        $excel->store('xlsx', false, true)['full'];
        return response()->json(['excelNameResponse' => $excelNameResponse]);
    }

    public function exportar_reporte_referencia($fecha_ini, $fecha_fin, $dni, $paciente, $estado,$establecimiento_actual, $buscar_servicio, $buscar_servicio_destino) {
        
        if($dni==0)$dni="";
        if($paciente==0)$paciente="";
        
        Excel::create('Exportar Reportes de Referencias', function($excel) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $establecimiento_actual, $buscar_servicio, $buscar_servicio_destino) {
            $excel->sheet('GENERAL', function($sheet) use($fecha_ini, $fecha_fin, $dni, $paciente, $estado, $establecimiento_actual, $buscar_servicio, $buscar_servicio_destino) {
                
                $model_referencias = new Referencia();
                //----------------------------------------------------------------------
                $p[] = Auth::user()->id_establecimiento; 
                $p[] = $establecimiento_actual;
                $p[] = $fecha_ini;
                $p[] = $fecha_fin;
                $p[] = $dni;
                $p[] = $paciente;
                $p[] = $estado;
                $p[] = $buscar_servicio;
                $p[] = $buscar_servicio_destino;
                $p[]=1;
                $p[]=10000;
                
                $referencias = $model_referencias->listar_referencia_ajax($p);

                $modelfarma = new Farmacia();
                $establecimiento = $modelfarma->GetEstablecimientoPNP(Auth::user()->id_farmacia);
                $usuario = $modelfarma->GetNombreUsuarioByIdUser(Auth::user()->id);
                $nombre_usuario = $usuario->paterno." ".$usuario->materno." ".$usuario->name;

                $nro_atendidas = isset($referencias[0]->totalrows)?$referencias[0]->totalrows:0;
                $variable = [];
                $n = 1;
                array_push($variable, array($establecimiento->nombre));
                array_push($variable, array("Reporte de Referencias Medicas"));
                array_push($variable, array("Fecha Desde: " . $fecha_ini));
                array_push($variable, array("Fecha Hasta: " . $fecha_fin));
                array_push($variable, array("Total: " . $nro_atendidas . " atenciones"));
                array_push($variable, array("Usuario : " . $nombre_usuario));
                array_push($variable, array(""));
                array_push($variable, array("N","FECHA", "IPRESS ORIGEN DE REF", "SERVICIO ORIGEN DE REF", "MEDICO QUE REFIERE", "DNI PACIENTE", "PACIENTE","SEXO","EDAD","GRADO","SERVICIO DESTINO DE REF","ESTADO","IPRESS DESTINO DE CONTRAREFERENCIA"));

                foreach ($referencias as $r) {
                    if($r->referencias_ipress_no_pnp == '1'):
                        $estado = "  REFERIDO A IPRESS NO PNP";
                    else:
                        switch ($r->estado_proceso) {
                            case 1: $estado = "Referencia Pendiente"; break;
                            case 2: $estado = "Referencia Solicitada"; break;
                            case 3: $estado = "Referencia Invalidada"; break;
                            case 4: $estado = "Referencia Validado"; break;
                            case 5: if($r->flag == 1){
                                        $estado = "Referencia Cita Registrada";
                                    } else{ 
                                        $estado = "Referencia Triaje Registrada";
                                    }   break;
                            case 6: $estado = "Contrareferencia Pendiente"; break;
                            case 7: $estado = "Contrareferencia Culminada"; break;
                            case 8: $estado = "Contrareferencia Culminada Por Emergencia"; break;
                            case 9: $estado = "Contrareferencia Corte Culminado enEmergencia"; break;
                            case 10:$estado = "Proceso Finalizado"; break;
                            default: $estado = "---"; break;
                        } 
                    endif;

                    array_push($variable, array($n++,$r->fecha_atencion,$r->establecimiento, $r->nombre_servicio_referencia, $r->paterno_medico.' '.$r->materno_medico.', '.$r->nombre_medico,$r->nro_doc_ident, $r->paterno.' '.$r->materno.', '.$r->nombre, $r->sexo,$r->edadpaciente,$r->grado,$r->nombre_servicio_destino,$estado,$r->destino_establecimiento));
                    
                }
                $sheet->with($variable)->mergeCells('A2:E2')->mergeCells('A3:E3')->mergeCells('A4:C4')->mergeCells('A5:C5')->mergeCells('A6:C6');
            });
        })->export('xls');
    }
}

